INSERT INTO public.document_files (
  id,document_id,file_type,storage_path,download_filename,mime_type,file_size,sha256,page_count,is_downloadable,download_block_reason
)
SELECT (x->>'id')::uuid,(x->>'document_id')::uuid,x->>'file_type',x->>'storage_path',x->>'download_filename',
       x->>'mime_type',(x->>'file_size')::bigint,x->>'sha256',(x->>'page_count')::integer,
       (x->>'is_downloadable')::boolean,x->>'download_block_reason'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT DO NOTHING;

COMMIT;

SELECT 'moj-all-verified-judgments-review-002-chunk-101' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"f66f04d9-0ca3-51ae-b906-752719ce02f4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج ومحاولة إدخالها إلى السجن -بينة غير موصلة -مقاومة رجال األمن - عدم ثبوت الدعوى.","document_number":"34375086","case_number":"34224886","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف التصديق على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/15","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج ومحاولة إدخالها إلى السجن -بينة غير موصلة -مقاومة رجال األمن - عدم ثبوت الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34375086:‬تاريخه‪1434/05/15 :‬هـ‬\n                          ‫رقم الدعوى‪34224886:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 35127293‬تاريخه‪1435/1/25:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصد الترويــج ومحاولة‬\n       ‫إدخالهــا إلــى الســجن ‪ -‬بينــة غيــر موصلــة ‪ -‬مقاومــة رجــال األمــن ‪-‬‬\n                                                           ‫عــدم ثبــوت الدعــوى‪.‬‬\n\n\n\n\n       ‫ـك َما‬     ‫يحـ ِ‬ ‫ـك َوأ َْط َيـ َـب ِر َ‬        ‫(مــا أ َْط َي َبـ ِ‬\n                                                                         ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪َ :‬‬\n       ‫ل ْر َمـ ُة ْالُ ْؤمِ ـ ِـن‬ ‫ـس ُم َح َّمــدٍ ِب َيــدِ ِه َ ُ‬   ‫ـك َوا َّلــذِ ي َن ْفـ ُ‬‫ـك َوأَعْ َظـ َـم ُح ْر َم َتـ ِ‬   ‫أَعْ َظ َمـ ِ‬\n                                                                                                                      ‫أَعْ َظـ ُـم عِ ْنـ َـد َّ ِ‬\n                                                                                              ‫الل ُح ْر َمـ ًة مِ ْنـ ِ‬\n                       ‫ـك َما ِلـ ِه َو َدمِ ـ ِه َوأ َْن َن ُظـ َّـن ِبـ ِه ِإ َّل َخ ْيـ ًـرا)‬\n                                                                                                                    ‫‪ -2‬الضرر يزال‪.‬‬\n                                                    ‫‪ -3‬املواد (‪ )22‬و(‪ )65‬من نظام املرافعات الشرعية‪.‬‬\n                                                             ‫‪ -4‬املادة (‪ )221‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n       ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n       ‫بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة بقصــد الترويــج ومحاولــة‬\n       ‫إدخالهــا إلــى الســجن ‪ ،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n       ‫واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n       ‫و بعقوبــة الســجن طبقــا لنظــام الســجن والتوقيــف وبعقوبــة تعزيريــة‬\n       ‫ملقاومــة رجــل األمــن‪ ،‬مت القبــض عليــه وهــو يحــاول إدخــال كيــس بــه‬\n\n‫‪175‬‬\n\f‫قطعــة مــن احلشــيش وعــدد مــن احلبــوب احملظــورة حتت شــبك أحــد عنابر‬\n‫الســجن‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n‫للحشــيش املخــدر واإلمفيتامــن‪ ،‬أنكــر أمــام احملكمــة مــا أســنده إليه‬\n‫املدعــي العــام‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه وقــررت‬\n‫ســماع شــهادة الشــهود فلــم جتــد فيهــا مــا يثبــت دعواه‪،‬قضــت احملكمــة‬\n‫بعــدم إدانــة املدعــى عليــه مبــا نســب إليــه يف الدعــوى وأخلــت ســبيله‬\n‫منهــا‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت‬\n                              ‫محكمــة االســتئناف التصديــق علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 34224886‬وتاريــخ‬\n‫‪1434/05/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341186809‬وتاريــخ‬\n‫‪ 1434/05/14‬ه ـ ففــي يــوم األحــد املوافق‪1434/06/18‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 :45‬صباح ـ ًا وفيهــا حضــر املدعــي العــام ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬والتكليــف رقــم‬\n‫‪ 24‬يف ‪1432/01/16‬ه ـ وتقــدم بالئحــة دعــواه ضــد‪ 26 ....... ،‬عام ـاً‪،‬‬\n‫‪ .......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ ،).....‬املهنــة ‪.......‬‬\n‫موظــف أهلــي‪ ،‬متعلــم‪ ،‬موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب‬\n‫أمــر متديــد التوقيــف رقــم ( ه ـ م‪ )8966/5/2‬وتاريــخ ‪1434/2/6‬ه ـ ‪،‬‬\n‫اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي على‬\n‫املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬انــه بتاريــخ ‪1434/1/10‬ه ـ‬\n\n                                                                                       ‫‪176‬‬\n\f      ‫وأثنــاء زيــارة نــزالء الســجن وصلــت إخباريــة مــن احــد الــزوار ألحــد‬\n      ‫حــراس الســجن بأنــه يوجــد يف شــبك الزيــارة التابــع بعنبــر (‪ )4‬شــخص‬\n      ‫يحــاول إدخــال ممنوعــات عــن طريــق الشــبك وبــدوره ابلــغ ضابــط خفــر‬\n      ‫فتــم القبــض عليــه مــن قبــل إفــراد احلراســات وبيــده كيــس مربــع‬\n      ‫الشــكل بيــده اليمنــى يوجــد بداخلــه مــادة ســوداء اللــون بلــغ وزنهــا‬\n      ‫(‪43,5‬جــم) مــن احلشــيش املخــدر وعــدد (‪ )12‬حبــة مــن احلبــوب املؤثــرة‬\n      ‫عقلي ـ ًا يحــاول إدخالهــا مــن حتــت الشــبك عــن طريــق ســلك معدنــي‬\n      ‫وعنــد محاولــه القبــض عليــه قــاوم ورمــى الكيــس باجتــاه الشــبك‪ .‬وقــد‬\n      ‫اثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/165‬ك ش م) لعــام ‪1434‬ه ـ‬\n      ‫إيجابيــة العينتــن مــن الكميتــن املضبوطــة واملرســلة للتحليــل علــى مادة‬\n      ‫اإلمفيتامــن املؤثــرة عقلي ـ ًا واحلشــيش املخــدر واملدرجــة باجلــدول رقــم‬\n      ‫(‪ )2‬فئــة (ب) وامللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n      ‫باســتجواب املدعــى عليــه أفــاد إنــه كان يف زيــارة ألخيــه بعنبــر (‪)4‬‬\n      ‫بالســجن العــام بجــدة وأثنــاء الزيــارة حضــر رجــل األمــن واتهمــه بحيــازة‬\n      ‫ممنوعــات وأن رجــل األمــن اآلخــر قــام بالتفتيــش أســفل شــبك الزيــارة‬\n      ‫ووجــد كيــس نايلــون يحتــوي علــى حبــوب وحشــيش وســلمها لرجــل‬\n      ‫األمــن الــذي قــام بتفتيشــه والقبــض عليــه‪ .‬وبســماع أقــوال الشــهود أفــاد‬\n      ‫املواطــن (‪ ).....‬أنــه كان متواجــد ًا بالســجن العــام لزيــارة أخيــه بعنبــر‬\n      ‫(‪ )4‬وأثنــاء ذلــك شــاهد رجــل األمــن يصــرخ ثــم امســك باملدعــى عليــه‬\n      ‫مــن كتفــه وفتشــه وفتــش جــواره ولــم يجــد شــيء مــن املمنوعــات ثــم‬\n      ‫أحضــر رجــل األمــن الثانــي املتواجــد بــن الشــبكني كيــس نايلــون‬\n      ‫شــفاف ال يعلــم مــا بداخلــه‪ .‬وبســماع أقــوال الشــاهد الثانــي املواطــن‬\n      ‫(‪ ).....‬شــهد انــه كان متواجــد ًا بالســجن العــام لزيــارة أخيــه بعنبــر‬\n\n\n‫‪177‬‬\n\f‫(‪ )4‬وأثنــاء ذلــك شــاهد رجــل األمــن يصــرخ ثــم أمســك املدعــى عليــه‬\n‫ولــم يجــد معــه شــيء مــن املمنوعــات ولــم يشــاهد رجــل االمــن الثانــي‬\n‫عندمــا وجــد كيــس نايلــون بــن الشــبكني ‪ ،‬وأضــاف ان رجــل االمــن‬\n‫الثانــي لــم يقــم مــن علــى كرســيه لكونــه خــرج مــن موقــع الزيــارة حــن‬\n‫محاولــة رجــل األمــن األول القبــض علــى املدعــى عليــه‪ .‬وبســماع أقــوال‬\n‫رجــل األمــن (‪ ).....‬أفــاد انــه أثنــاء عملــه بالســجن اخبــره احــد الــزوار‬\n‫أن املدعــى عليــه يحــاول إدخــال ممنوعــات إلــى الســجن فاخبــر ضابــط‬\n‫العنبــر وكلفــه بالذهــاب إلــى عنبــر (‪ )4‬فشــاهد املدعــى عليــه وبيــده‬\n‫اليمنــى كيــس نايلــون يحــاول إدخالــه مــن أســفل الشــبك عــن طريــق‬\n‫ســلك معدنــي ممــدود مــن داخــل العنبــر وعنــد القبــض عليــه قــام املدعــى‬\n‫عليــه مبقاومــة عنيفــة ورمــى مــا بيــده باجتــاه الشــبك فبحــث عنــه ولــم‬\n‫يجــده وســمع أثنــاء القبــض عليــه الســجناء يقولــون لــه ارميــه وبحــث عنــه‬\n‫ولــم يجــده ثــم ذهــب رجــل األمــن اآلخــر إلــى مــا بــن الشــبكني فاحضــر‬\n‫الكيــس وســلمه لــه‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام إلــى‬\n‫املدعــى عليــه بحيــازة (‪ )43,5‬ثالثــة وأربعــن جرام ـ ًا مــن مــادة احلشــيش‬\n‫املخــدر وعــدد (‪ )12‬حبــه مــن حبــوب اإلمفيتامــن املؤثــرة عقليـ ًا بقصــد‬\n‫الترويــج اســتناد ًا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ومحاولــة إدخالهــا إلــى الســجن العــام وفــق‬\n‫الفقــرة (‪ )2‬مــن املــادة (‪ )29‬مــن نظــام الســجن ودور التوقيــف‪ .‬وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪-1 -:‬مــا جــاء بشــهادة الشــهود املنــوه عنهــا لفــه‬\n‫ا املرفــق لفــه‬\n               ‫(‪-2 .)21-20‬مــا ورد مبحضــر القبــض املنــوه عنــه تفصي ـ ً‬\n‫ا املرفــق لفــه (‪.)2‬‬  ‫(‪-3 .)1‬مــا ورد مبحضــر التحريــز املنــوه عنــه تفصي ـ ً‬\n‫‪-4‬مــا ورد بالتقريــر الكيميائــي املنــوه عنــه املرفــق لفــه (‪ .)22‬وباالطــاع‬\n\n\n                                                                                       ‫‪178‬‬\n\f      ‫علــى ســوابقه عثــر لــه علــى ســابقة دخــول مدرســة‪ .‬وحيــث ان مــا أقــدم‬\n      ‫عليــه املدعــى عليــه مــن األفعــال احملرمــة شــرع ًا واحملرمــة نظامـ ًا طبقـ ًا‬\n      ‫للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثرات العقليــة الصادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ والقفــرة (‪ )2‬مــن‬\n      ‫املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف الصــادر باملرســوم امللكــي‬\n      ‫رقــم (م‪ )31/‬وتاريــخ ‪1398/6/21‬ه ـ ‪ ،‬لــذا اطلــب إثبــات مــا اســند‬\n      ‫إليــه واحلكــم عليــه مبعاقبتــه بالعقوبــات األصليــة والتكميليــة التاليــة‪:‬‬\n      ‫‪-1‬بالســجن لقــاء مــا اســند إليــه اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪)38‬‬\n      ‫مــن نظــام مكافحــة املخــدرات والفقــرة (‪ )2‬مــن املــادة (‪ )29‬مــن نظــام‬\n      ‫بالســجن والتوقيــف املشــار إليهمــا مــع اجللــد والغرامــة اســتناد ًا لــذات‬\n      ‫الفقــرة (‪ )1‬املــادة (‪ )38‬املشــار لهــا ‪ ،‬وتشــديد العقوبــة عليــه اســتناد ًا‬\n      ‫للفقــرة (‪ )2‬احلالــة (ب) مــن ذات املــادة (‪ )38‬مــن نظــام املخــدرات أعــاه‪.‬‬\n      ‫‪-2‬منعــه مــن الســفر إلــى خــارج اململكــة ‪ ،‬وذلــك بعــد انتهــاء تنفيــذ‬\n      ‫العقوبــة اســتناد ًا الفقرتــن (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة‬\n      ‫املخــدرات املشــار إليــه‪ .‬كمــا اطلــب بتعزيــره لقــاء املقاومــة لرجــل األمــن‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه أجــاب بقولــه ما ذكــره املدعي العام‬\n      ‫مــن أننــي حــزت احلشــيش املخــدر واحلبــوب املؤثــرة علــى العقــل بقصــد‬\n      ‫الترويــج وحاولــت إدخالهــا إلــى الســجن فغيــر صحيــح ومــا ذكــره مــن‬\n      ‫أننــي قاومــت حينمــا أرادوا تفتيشــي والقبــض علــي فغيــر صحيــح وعلــي‬\n      ‫الســابقة التــي ذكــر هكــذا أجــاب إثــر هــذا طلبــت مــن املدعــي العــام‬\n      ‫بينتــه طبــق دعــواه فاســتمهل فامهــل عليــه رفعــت اجللســة يف متــام الســاعة‬\n      ‫احلاديــة عشــرة صباحــا إلــى يــوم االثنــن املوافــق ‪1434/06/26‬ه ـ‬\n      ‫الســاعة التاســعة والربــع صباحــا وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n‫‪179‬‬\n\f‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/06/18‬ه ـ احلمــد هلل‬\n‫وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة مبحافظــة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة برقــم ‪ 34224886‬وتاريــخ ‪ 1434/05/15‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341186809‬وتاريــخ ‪ 1434/05/14‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافــق‪ 1434/06/27‬ه ـ افتتحت اجللســة الســاعة العاشــرة‬\n‫والربــع صباحــا وفيهــا حضــر ‪ .......‬ســعودي اجلنســية حامــل بطاقــة أحوال‬\n‫ذات الرقــم (‪ ).....‬و (‪ ).....‬ســعودي اجلنســية حامــل بطاقــة ذات الســجل‬\n‫املدنــي رقــم (‪ ).....‬وطلبــا اإلذن للشــهادة فأذنــت لهمــا فقــال كل واحــد‬\n‫منهمــا مبفــرده أشــهد هلل العظيــم أنــه ال عالقــة تربطنــي باملدعــى عليــه‬\n‫وأننــي كنــت يــوم القبــض علــى املدعــى عليــه يف الســجن زائــرا ورأيــت‬\n‫املدعــى عليــه يتهــم بحيازتــه ملخــدرات مــن قبــل العســكري الــذي يتجول‬\n‫علــى الســجناء بــدون مقدمــات توجــه إلــى املدعــى عليــه وقــال إنــك تدخــل‬\n‫مخــدرات وأخــذه إلــى الداخــل وزاد األول (‪ ).....‬وابلــغ مــن العمــر اثنــن‬\n‫وثالثــن ســنة وقــد كنــت زائــرا لصديــق لــي وزاد الثانــي وابلــغ مــن العمــر‬\n‫ســبعة وعشــرين ســنة وقــد كنــت بجــوار الزائــر للمدعــى عليــه ولــم أرى‬\n‫منه ما يريب فلم اره يســقط شــيئا أو يخفي شــيئا بل اســتنكرت اتهامه‬\n‫يف ذلــك هكــذا شــهد كل واحــد منهمــا مبفــرده إثــر هــذا أكــدت‬\n‫علــى املدعــي العــام إحضــار مزيــد بينــة و رفعــت اجللســة يف متــام الســاعة‬\n‫العاشــرة والنصــف صباحــا إلــى يــوم األربعــاء املوافــق ‪14340705‬ه ـ‬\n‫الســاعة التاســعة والربــع صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n\n\n                                                                                     ‫‪180‬‬\n\f      ‫مبحافظــة جــدة ففــي يــوم األحــد املوافــق‪ 1434/12/01‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة الثانيــة عشــرة ظهــرا وفيهــا حضــر الطرفــان فســألت‬\n      ‫املدعــي العــام عمــا رفعــت اجللســة الســابقة ألجلــه فأجــاب مقــرر ًا بينتــي‬\n      ‫هــي شــهادة رجــال الضبــط والتحريــز وقــد طلبتهــم للشــهادة عــدة مــرات‬\n      ‫ولــم ميتثلــوا هكــذا أجــاب إثــر هــذا رجعــت إلــى مــا جعلــه أدلــة لــه يف‬\n      ‫األوراق فاطلعــت علــى محضــر القبــض وتضمــن أنــه بنــاء علــى إخباريــة‬\n      ‫أحــد زوار الســجن بــأن زائــر ًا يحــاول إدخــال ممنوعــات للســجن جــرى‬\n      ‫ضبــط املدعــى عليــه وبيــده كيــس يحــوي مــادة ســوداء اللــون وهــو يزمــع‬\n      ‫إدخالــه مــن حتــت الشــبك عــن طريــق ســلك معدنــي وقــاوم أثنــاء القبــض‬\n      ‫عليــه ورمــى الكيــس كمــا اطلعــت علــى محضــر التحريــر لفــة رقــم‪2‬‬\n      ‫وتضمــن حتريــز املضبــوط مــع املدعــى عليــه وهــو مــادة الســوداء يشــتبه‬\n      ‫أن تكــون حشيش ـ ًا مخــدر ًا وبلــغ وزنهــا ثالثــة وأربعــون جرام ـ ًا ونصــف‬\n      ‫اجلــرام واثنــا عشــر حبــة يشــتبه أن تكــون حبوبـ ًا محظــورة كمــا اطلعــت‬\n      ‫علــى شــهادة الشــهود احملــررة يف ملــف التحقيــق لفــة رقــم‪ 30‬ولــم تــزد‬\n      ‫عمــا ذكــروه يف شــهادتهم يف اجللســة الســابقة فبنــاء علــى مــا تقــدم‬     ‫ّ‬\n      ‫مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه مــا اتهــم بــه وملــا ورد يف‬\n      ‫نظــام اإلجــراءات اجلزائيــة يف مادتــه الواحــدة والعشــرين بعــد املائتــن‬\n      ‫مــن أنــه تطبــق األحــكام الــواردة يف نظــام املرافعــات الشــرعية فيمــا‬\n      ‫لــم يــرد لــه حكــم يف نظــام اإلجــراءات اجلزائيــة وفيمــا ال يتعــارض مــع‬\n      ‫طبيعــة الدعــوى اجلنائيــة وملــا ورد يف نظــام املرافعــات الشــرعية يف مادتــه‬\n      ‫عمــا دفــع بــه‬\n                    ‫اخلامســة والســتني مــن جــواز إمهــال أحــد الطرفــن للجــواب ّ‬\n      ‫الطــرف اآلخــر وجــواز تكــرار املهلــة لعــذر شــرعي ويف مادتــه الثانيــة‬\n      ‫والعشــرين مــن اعتبــار مــن لــم يحضــر شــهوده عاجــز ًا بعــد تكــرار املهلــة‬\n\n\n‫‪181‬‬\n\f‫لــه وأن للمحكمــة حينئــذ الفصــل يف الدعــوى‪ ،‬وملــا ســبق مــن إقــرار‬\n‫املدعــي العــام بتغيــب شــهوده علــى طلبهــم مــرات عــدة وألن الضــرر يــزال‬\n‫وبقــاء الســجني دون حكــم ضــرر بـ ّـن وألن مــا يف األوراق ال يقــوم بينــة‬\n‫علــى مــا اتهــم بــه املدعــى عليــه وملــا شــهد بــه الشــهود مــن أنهــم لــم يــروا‬\n‫حســن‬   ‫شــيئ ًا وألن األصــل يف املســلم الســامة وال يظــن بــه إال خيــر ًا فقــد ّ‬\n                    ‫األلبانــي مــا رواه ابــن ماجــه والبيهقــي وغيرهمــا عــن َع ْبـ ُـد َّ ِ‬\n‫الل ْبـ ُـن ُع َمـ َـر‬\n‫ك ْع َب ـ ِة َو َي ُقــولُ ‪:‬‬‫ـوف ِبا ْل َ‬                                     ‫الل َص َّلــى َّ ُ‬\n                                         ‫الل َع َل ْي ـ ِه َو َسـل ََّم َي ُطـ ُ‬                   ‫قَ ــالَ َر َأ ْيـ ُـت َر ُســولَ َّ ِ‬\n‫ـس‬  ‫يحـ ِـك َمــا َأ ْع َظ َمـ ِـك َو َأ ْع َظـ َـم ُح ْر َم َتـ ِـك َوا َّلــذِ ي ن َْفـ ُ‬ ‫«مــا َأ ْط َي َبـ ِـك َو َأ ْط َيـ َـب ِر َ‬     ‫َ‬\n                                                         ‫ُم َح َّمــدٍ ِب َيــدِ ِه َل ُْر َمـ ُة ْال ُْؤمِ ـ ِـن َأ ْع َظـ ُـم عِ ْنـ َـد َّ ِ‬\n ‫الل ُح ْر َمـ ًة مِ ْنـ ِـك َما ِلـ ِه َو َدمِ ـ ِه َوأَنْ‬\n‫ن َُظـ َّـن ِب ـ ِه ِإ َّل َخ ْيـ ًـرا»‪ ،‬لــذا كلــه فلــم تثبــت لــدي إدانــة املدعــى عليــه مبــا‬\n‫نســب إليــه يف الدعــوى وأخليــت ســبيله منهــا وبذلــك حكمــت و وأعلنــت‬\n‫ذلــك يف متــام الســاعة الثانيــة عشــرة والربــع ظهــرا فقنــع بــه واعتــرض‬\n‫املدعــي العــام فأجبتــه لذلــك وجعلــت لــه يــوم غــد موعــد ًا الســتالم نســخة‬\n‫احلكــم وتقــدمي اعتراضــه عليــه يف مــدة أقصاهــا شــهر فــإن مضــت املــدة‬\n‫اكتســب احلكــم القطعيــة بقــوة النظــام فــأدرك ذلــك وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                                                       ‫‪ 1434/12/01‬ه ـ ‪.‬‬\n‫احلمــد اهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة برقــم ‪ 341186809‬وتاريــخ‬\n‫‪1435/1/16‬ه ـ املرفــق بهــا القــرار القضائــي رقــم ‪ 34375086‬وتاريــخ‬\n‫‪1434/12/1‬ه ـ الصــادر مــن فضيلــة الشــيخ (‪ )....‬القاضــي باحملكمــة‬\n\n\n                                                                                                                                                  ‫‪182‬‬\n\f      ‫اجلزائيــة بجــدة ‪ ،‬املتضمــن دعــوى املدعــى العــام ضــد (‪ )....‬املتهــم بحيــازة‬\n      ‫احلشــيش املخــدر واحلبــوب احملظــورة بقصــد الترويــج احملكــوم فيــه مبــا‬\n      ‫دون باطنــه وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫قررنــا املوافقــة علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                   ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪183‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":175,"source_page_end":183,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cadf8a01b93a83c06d97dd4ff047d57e5e71c898d2a10dbebd6cc076d492aafc","normalized_text_hash":"5cad1b401601b7bed63cdda7c43dc33550e21147955f7eb4f3c3433fde10960e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p175-34375086"},{"id":"a0d32998-d05b-50cb-9b01-1c83221236e2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -دفع غير مقبول -إدانة باحليازة املجردة عن القصد -حد املسكر -تعزير بالسجن واجللد والغرامة واإلبعاد .","document_number":"34227223","case_number":"34242690","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/26","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -دفع غير مقبول -إدانة باحليازة املجردة عن القصد -حد املسكر -تعزير بالسجن واجللد والغرامة واإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34227223:‬تاريخه‪1434/05/26 :‬هـ‬\n                    ‫رقم الدعوى‪34242690:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34282924‬تاريخه‪1434/7/30:‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬دفــع غيــر‬\n ‫مقبــول‪ -‬إدانــة باحليــازة املجــردة عــن القصــد ‪ -‬حــد املســكر ‪ -‬تعزيــر‬\n                                ‫بالســجن واجللــد والغرامــة واإلبعــاد ‪.‬‬\n\n\n\n\n ‫املــواد (‪ )39‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                          ‫العقليــة‪.‬‬\n\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n ‫بحيــازة احلشــيش املخــدر بقصــد االســتعمال وتعاطيه لــه ‪ ،‬واحلكم عليه‬\n ‫بعقوبــة الســجن واإلبعــاد عــن البــاد طبقــا لنظــام مكافحــة املخــدرات‬\n ‫واملؤثــرات العقليــة‪ ،‬مت تفتيشــه شــخصي ًا فعثــر داخــل جيــب قميصــه‬\n ‫األمامــي علــى قطعــة يشــتبه أن تكــون مــن احلشــيش‪ ،‬أثبــت التقريــر‬\n ‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر‪ ،‬أقــر‬\n ‫أمــام احملكمــة بتعاطــي احلشــيش وحيازتــه وأنكــر مــا أســنده إليــه‬\n ‫املدعــي العــام مــن حيازتــه بقصــد التعاطــي ودفــع بأنــه ال يعلــم عــن‬\n ‫وجودهــا يف جيبــه‪ ،‬قضــت احملكمــة بإدانتــه بتعاطــي احلشــيش املخــدر‬\n ‫وبحيازتــه حيــازة مجــردة وقــررت جلــده حــد املســكر ثمانــون جلــد ًة‬\n\n                                                                                ‫‪184‬‬\n\f      ‫علنـ ًا دفعــة واحــدة وســجنه ملــدة ســتة أشــهر وجلــده مائــة وخمســن جلــدة‬\n      ‫مفرقــة وتغرميــه مبلــغ ثالثــة آالف ريــال وإبعــاده عــن البــاد بعــد انتهــاء‬\n      ‫محكوميتــه‪ ،‬عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‪،‬‬\n                          ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق ‪1434/5/28‬ه ـ لــدي‬\n      ‫أنــا ‪ .......‬رئيــس احملكمــة اجلزائيــة بالدمــام وبنــاء علــى املعاملــة الــواردة‬\n      ‫إلينــا مــن هيئــة التحقيــق واالدعــاء العــام باملنطقــة الشــرقية برقــم‬\n      ‫‪ 27194‬وتاريــخ ‪1434/5/26‬ه ـ واملقيــدة لدينــا برقــم ‪341281228‬‬\n      ‫وتاريــخ ‪1434/5/26‬ه ـ واحملالــة لنــا برقــم ‪ 34242690‬وتاريــخ‬\n      ‫ا فيهــا ادعــي علــى‬ ‫‪1434/5/26‬ه ـ عليــه قــدم املدعــي العــام دعــواه قائـ ً‬\n      ‫‪ .......‬بنجالديشــي اجلنســية مبوجب رخصة اإلقامة رقم ‪ .......‬وباالطالع‬\n      ‫علــى محضــر القبــض املعــد مــن قبــل مركــز أمــن طــرق صالصــل بتاريخ‬\n      ‫‪1434/4/22‬ه ـ اتضــح أنــه أثنــاء إقامــة نقطــة تفتيــش مقابــل املركــز مت‬\n      ‫االشــتباه بســيارة مــن نــوع (‪ )......‬حتمــل اللوحــة رقــم (‪ )....‬بقيــادة املدعــى‬\n      ‫عليــه املذكــور أعــاه ويرافقــه املقيــم (‪ - )..‬صــدر بحــق مرافــق املدعــى‬\n      ‫عليــه املقيــم‪ .......‬أمــر حفــظ الدعــوى رقــم (‪36‬ح‪ /‬ه ـ ق‪ )34/9‬وتاريــخ‬\n      ‫‪1434/5/5‬ه ـ اســتناد ًا للمــادة (‪ )124‬مــن نظــام اإلجــراءات اجلزائيــة ‪.-‬‬\n      ‫وباســتيقافهما وطلــب إثباتيهمــا لوحــظ عليهمــا االرتبــاك وصــدور رائحة‬\n      ‫يشــتبه أنهــا رائحــة املســكر وبتفتيــش املدعــى عليــه املذكــور أعــاه‬\n      ‫عثــر داخــل جيــب قميصــه األمامــي علــى قطعــة صغيــرة تــزن (‪ )0.3‬ثالثــة‬\n      ‫مــن العشــرة مــن مــادة يشــتبه أنهــا احلشــيش املخدر‪،‬وبتفتيــش املرافــق‬\n\n‫‪185‬‬\n\f‫عثــر معــه علــى مــادة يشــتبه أنهــا محظــورة فتــم القبــض عليهمــا‪ .‬وببعــث‬\n‫عينــه مــن (دم ‪ +‬بــول) املدعــى عليــه املذكــور أعــاه للتحليــل ‪ ،‬ورد‬\n‫تقريــر مركــز الســموم والكيميــاء الشــرعية رقــم(‪712‬م أ) وتاريــخ‬\n‫‪1434/4/30‬ه ـ املتضمــن إيجابيــة عينــة البــول املأخــوذة منــه ملركبــات‬\n‫احلشــيش املخــدر احملظــور دولي ـ ًا واخلاضــع لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم(م‪ )39/‬وتاريــخ‬\n‫‪1426/7/8‬ه ـ واملــدرج يف اجلــدول رقــم(‪ )1‬فقــرة (أ) امللحــق بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وببعــث عينــة مــن القطعــة‬\n‫املضبوطــة معــه للتحليــل‪ ،‬ورد تقريــر مركــز الســموم والكيميــاء‬\n‫الشــرعية رقــم(‪2024‬ك ش) وتاريخ‪1434/4/27‬ه ـ املتضمــن إيجابيــة‬\n‫عينــة القطعــة املرســلة واملضبوطــة مــع املدعــى عليــه ملــادة احلشــيش‬\n‫املخــدر احملظــور دولي ـ ًا واملــدرج يف اجلــدول رقــم(‪ )1‬فقرة(أ)امللحــق‬\n‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــد اســتهلكت العينــة‬\n‫يف التحليــل‪ .‬وبســماع أقوالــه واســتجوابه أقــر بصحــة واقعــة القبــض‬\n‫عليــه ووجــود قطعــة احلشــيش املخــدر داخــل جيــب قميصــه‪ ،‬وأفــاد‬\n‫انــه اشــترى قميصــه الــذي ضبــط بداخلــة قطعــة احلشــيش املخــدر مــن‬\n‫شــخص ال يعرفــه وانــه قــد تكــون تلــك القطعــة املضبوطــة عائــدة لــه‪.‬‬\n‫وانتهــى التحقيــق معــه إلــى توجيــه االتهــام لــه بتعاطــي احلشــيش املخــدر‬\n‫‪ ،‬وحيازتــه لقطعــة تــزن (‪ )0،3‬ثالثــة مــن العشــرة مــن اجلــرام مــن‬\n‫احلشــيش املخــدر بقصــد االســتعمال‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬إقــراره حتقيقــا بوجــود القطعــة داخــل القميــص الــذي يرتديــه املــدون‬\n‫علــى الصفحتــن رقــم(‪ )2،1‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪)25‬‬\n‫وإقــراره أثنــاء ســماع أقوالــه املــدون علــى الصفحــة رقــم (‪ )3‬مــن ملــف‬\n\n\n                                                                                   ‫‪186‬‬\n\f      ‫إجــراءات االســتدالل املرفــق لفــة رقــم (‪ -2 .)1‬مــا تضمنــاه التقريــران‬\n      ‫الكيميائيــان الشــرعيان املرفقــان علــى اللفتــن رقمــي (‪-3.)32،29‬‬\n      ‫مــا جــاء يف محضــر التحريــز املــدون علــى الصفحــة رقــم (‪ )1‬مــن ملــف‬\n      ‫إجــراءات االســتدالل املرفــق لفــه رقــم(‪ - 4)1‬مــا تضمنــه محضــر القبض‬\n      ‫والتفتيــش املرفــق علــى اللفــة رقــم(‪ .)2‬وبالبحــث عمــا إذا كان لديــه‬\n      ‫ســوابق اتضــح عــدم وجــود ســوابق مســجلة عليــه وحيــث إن مــا أقــدم‬\n      ‫عليــه املدعــى عليــه املذكــور ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪-‬‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا اســتنادا للفقــرة الثانيــة مــن‬\n      ‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ يف عقوباتــه‬\n      ‫األصليــة والتكميليــة أطلــب بإثبــات إدانتــه مبــا نســب إليــه واحلكــم‬\n      ‫عليــه باالتــي‪ -1:‬عقوبــة الســجن الــواردة يف الفقرة(‪)1‬األولــى مــن املــادة‬\n      ‫(‪ )41‬مــن النظــام املشــار إليــه أعــاه بحقــه لقــاء مــا اســند إليــه مــن‬\n      ‫اتهــام‪ -2.‬إبعــاده عــن البــاد بعــد تنفيــذ عقوبتــه وفقـ ًا ملــا تضمنتــه الفقــرة‬\n      ‫(‪ )2‬الثانيــة مــن املــادة (‪ )56‬السادســة واخلمســن مــن النظــام املشــار إليــه‬\n      ‫هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه بواســطة‬\n      ‫املترجــم املتعــاون بنجالديشــي اجلنســية مبوجــب اإلقامــة الصــادرة مــن‬\n      ‫الدمــام برقــم ‪ .......‬قــال مــا ذكــره املدعــي العــام مــن تعاطــي احلشــيش‬\n      ‫وحيازتــي قطعــة احلشــيش يف جيــب قميصــي صحيــح ولكننــي ال أعلــم‬\n      ‫عنهــا فقــد اشــتريت القميــص يف نفــس يــوم القبــض علــي هكــذا أجــاب‬\n      ‫وقــد جــرى منــا دراســة أوراق املعاملــة واالطــاع علــى ملــف التحقيــق مــع‬\n      ‫املدعــى عليــه لفــة ‪ 25‬فوجــد يتضمــن املصادقــة علــى وجــود القطعــة يف‬\n      ‫قميصــه وإنــكار عائديتهــا لــه كمــا جــرى منــا االطــاع علــى التقريــر‬\n\n\n‫‪187‬‬\n\f‫الكيمــاوي الشــرعي رقــم ‪ 2024‬ك ش املتضمــن إيجابيــة القطــع ملــادة‬\n‫احلشــيش كمــا جــرى منــا االطــاع علــى صحيفــة ســوابق املدعــى عليــه‬\n‫فوجــدت خاليــة فبنــاء علــى مــا تقــدم وحيــث صــادق املدعــى عليــه علــى‬\n‫تعاطــي احلشــيش وأقــر بوجــود القطعــة يف قميصــه ومــا دفــع بــه ال يقبــل‬\n‫لــذا فقــد قــررت االتــي اوالً‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بحيــازة‬\n‫قطعــة احلشــيش تــزن ثالثــة مــن العشــرة مــن اجلــرام حيــازة مجــرده ثانيــا‪:‬‬\n‫اهمــال املــادة ((‪ ))41‬لعــدم ثبــوت موجبهــا واعمــال املــادة ((‪ ))39‬مــن‬\n‫نظــام املكافحــة مــع مراعــاة ((‪ ))60‬مــن النظــام لكــون املدعــى عليــه‬\n‫وافــد مصيــره االبعــاد وذلــك بســجنه ســتة أشــهر مــن تاريــخ إيقافــه علــى‬\n‫ذمــة هــذه القضيــة وجلــده مائــة وخمســن جلــده مفرقــة بــن كل دفعــة‬\n‫وأخــرى عشــرة أيــام وإلزامــه بدفــع غرامــة ثالثــة آالف ريــال لبيــت املــال‬\n‫وجلــده حــد املســكر ثمانــون جلــدة علنــا دفعــة واحــدة يفــرق بينهــا وبــن‬\n‫التعزيــز بعشــرة أيــام وإبعــاده عــن البــاد بعــد انتهــاء محكوميتــه اعمــا ًال‬\n‫للمــادة ((‪ ))56‬مــن نظــام املكافحــة وبذلــك حكمــت للحــق العــام‬\n‫وبعــرض احلكــم علــى الطرفــن قــررا االعتــراض وبــاهلل التوفيــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر ‪1434/5/28‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/8/16‬ه ـ افتتحــت‬\n‫اجللســة الرابعــة يف متــام الســاعة التاســعة والنصــف صباحــا حيــث وردتنــا‬\n‫املعاملــة املتعلقــة بدعــوى املدعــي العــام ضــد مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية بخطــاب رقــم ‪ 341676917‬وتاريــخ ‪1434/8/8‬ه ـ‬\n‫وبرفقهــا القــرار رقــم ‪ 34282924‬وتاريــخ ‪1434/7/30‬ه ـ واملتضمــن‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم وقــد أغلقــت اجللســة يف متــام الســاعة احلاديــة عشــر‬\n                          ‫وخمســة وأربعــون دقيقــة حــرر يف ‪1434/8/16‬هــ‪.‬‬\n                                                                                       ‫‪188‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":184,"source_page_end":188,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ef7c05a3586c0e8cf19ab785b68c40a229d5f473be67578c8e27bcc62669990d","normalized_text_hash":"bc7c851699d819d46c2044853796f49e521ec902b3af89dea5ab17176cf8a2fb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p184-34227223"},{"id":"1a569809-961f-5226-91f7-5bfed047e912","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -إقرار -إدانة- نزول عن احلد األدنى للعقوبة -ال اجتهاد مع وجود نص نظامي -قيادة سيارة حتت تأثير املخدر -حد املسكر -تعزير بالسجن واإلبعاد -إثبات.","document_number":"3424254","case_number":"34244859","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف أن وقف تنفيذ عقوبة اإلبعاد اجتهاد مع وجود نص نظامي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/05/27","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -إقرار -إدانة- نزول عن احلد األدنى للعقوبة -ال اجتهاد مع وجود نص نظامي -قيادة سيارة حتت تأثير املخدر -حد املسكر -تعزير بالسجن واإلبعاد -إثبات.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3424254 :‬تاريخه‪1433/05/27 :‬هـ‬\n                         ‫رقم الدعوى‪34244859:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34246254‬تاريخه‪1434/06/19 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬إقــرار‪ -‬إدانــة‪-‬‬\n      ‫نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬ال اجتهــاد مــع وجــود نــص نظامــي‬\n      ‫‪ -‬قيــادة ســيارة حتــت تأثيــر املخــدر ‪ -‬حــد املســكر ‪ -‬تعزيــر بالســجن‬\n                                                              ‫واإلبعــاد ‪ -‬إثبــات‪.‬‬\n\n\n\n\n      ‫املــواد (‪ )41‬و(‪ )56‬و (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                ‫العقليــة‪.‬‬\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n      ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لــه‪ ،‬واحلكــم عليــه‬\n      ‫بعقوبــة الســجن واإلبعــاد عــن البــاد طبقــا لنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة‪ ،‬مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا‬\n      ‫علــى ســيجارة يشــتبه أن تكــون مخلوطــة باحلشــيش‪ ،‬أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر‪ ،‬أقــر‬\n      ‫أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬قضــت احملكمــة بإدانــة‬\n      ‫املدعــى عليــه بحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لــه‬\n      ‫وقــررت جلــده ثمانــن جلــدة دفعــة واحــدة حــد املســكر وســجنه ملــدة‬\n\n‫‪189‬‬\n\f‫أربعــة أشــهر وإبعــاده عــن البــاد بعــد تنفيــذ العقوبــة بحقــه مــع وقــف‬\n‫تنفيــذ هــذه العقوبــة بحقــه‪ ،‬الحظــت محكمــة االســتئناف أن وقــف‬\n‫تنفيــذ عقوبــة اإلبعــاد اجتهــاد مــع وجــود نــص نظامــي‪ ،‬قــررت احملكمــة‬\n‫االبتدائيــة الرجــوع عمــا حكمــت بــه مــن وقــف التنفيــذ‪ ،‬عــارض املدعى‬\n‫عليــه علــى احلكــم ولــم يعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة‬\n               ‫االســتئناف املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪ 34244859‬وتاريــخ‬\n‫‪1434/05/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341292609‬وتاريــخ‬\n‫‪1434/05/27‬ه ـ ففــي يــوم االثنــن املوافق‪1434/06/12‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 :15‬وفيهــا حضــر املدعــي العــام املكلــف من مرجعة‬\n‫برقــم ه ـ ع ‪ 51/3/‬يف ‪1431/5/24‬ه ـ وحضــر حلضــوره املدعــى عليــه‬\n‫‪ .......‬مينــي اجلنســية مبوجــب رخصــة إقامــة رقــم ‪ .......‬وادعــى املدعــى‬\n‫العــام بدعــواه احملــررة لدينــا أنــه عنــد الســاعة الثانيــة عشــر مســاء‬\n‫اخلميــس املوافــق ‪1434/5/2‬ه ـ وأثنــاء قيــام فرقــة املخــدرات بعملهــا‬\n‫يف حــي ‪ .....‬بخميــس مشــيط مت االشــتباه يف ســيارة ‪ .....‬وباســتيقافها‬\n‫وطلــب إثبــات قائدهــا املتهــم وبتفتيشــه لــم يعثــر معــه علــى أي شــيء مــن‬\n‫املمنوعــات وبتفتيــش الســيارة عثــر بداخلهــا علــى ســيجارة يشــتبه أن‬\n‫تكــون مخلوطــة مبــادة احلشــيش املخــدر بلــغ وزنهــا (‪ )0.7‬ســبعة مــن‬\n‫العشــرة مــن اجلــرام فقبــض عليــه وســلم إلــى إدارة مكافحــة املخــدرات‬\n\n                                                                                    ‫‪190‬‬\n\f      ‫بخميــس مشــيط وســلمت لــه ســيارته وأغراضــه الشــخصية وبســماع‬\n      ‫أقــوال املتهــم أقــر بأنــه عثــر يف ســيارته علــى ســيجارة مخلوطــة مبــادة‬\n      ‫احلشــيش املخــدر وهدفــه مــن حيازتهــا االســتعمال وانــه اســتخدم مــن‬\n      ‫املضبــوط كمــا أقــر بأنــه يتعاطــى احلشــيش املخــدر من الســابق وبتحليل‬\n      ‫عينــة ممــا مت ضبطــه ثبــت أنهــا مخلوطــة مبــادة احلشــيش املخــدر مبوجــب‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم (‪/938‬م) لعــام ‪1434‬ه ـ الصــادر من‬\n      ‫مركــز مراقبــة الســموم الطبيــة الشــرعية مبنطقــة عســير وقــد انتهــى‬\n      ‫التحقيــق مــع املذكــور إلــى توجيــه االتهــام لــه بحيــازة أعقاب ســجائر بلغ‬\n      ‫وزنهــا (‪ )0.7‬ســبعة مــن العشــرة مــن اجلــرام بقصــد التعاطــي والتعاطــي‬\n      ‫مــن نــوع املضبــوط ومــن الســابق كمــا أقــرر توجيــه االتهــام لــه بقيــادة‬\n      ‫الســيارة حتــت تأثيــر احلشــيش املخــدر وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪1‬ـ مــا تضمنــه إقــراره علــى صفحــة (‪ )9-12‬مــن ملــف ضبــط إجــراءات‬\n      ‫قضيــة مخــدرات مرفــق لفــة رقــم (‪2 )1‬ـ مــا تضمنــه محضــر القبــض‬\n      ‫والتفتيــش لفــه رقــم (‪3 )9‬ـ مــا تضمنــه التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪/938‬م) لعــام ‪1432‬ه ـ لفــه رقــم (‪ )16‬وبالبحــث عــن ســوابقه‬\n      ‫اتضــح عــدم وجــود ســوابق مســجلة عليــه لــذا أطلــب إثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه مبــا يلــي ‪1‬ـ عقوبــة تعزيريــة وفقــا ملــا ورد يف املــادة (‪)1/41‬‬\n      ‫احلاديــة واألربعــن الفقــرة األولــى مــن النظــام املشــار إليــه لقــاء حيازتــه‬\n      ‫ســيجاره مخلوطــة مبــادة احلشــيش املخــدر بلــغ وزنهــا (‪ )0.7‬ســبعة مــن‬\n      ‫العشــرة مــن اجلــرام بقصــد االســتعمال واســتعمال مــن املضبــوط يف‬\n      ‫الســابق ‪2‬ـ إبعــاده مــن اململكــة العربيــة الســعودية بعــد تنفيــذ العقوبــة‬\n      ‫وفقــا ملــا ورد يف املــادة (‪ )56‬السادســة واخلمســن الفقــرة (‪ )2‬الثانيــة مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ -3‬إثبــات إدانتــه بقيــادة‬\n\n\n‫‪191‬‬\n\f‫الســيارة حتــت تأثيــر احلشــيش املخــدر وإفهامــه بــأن عقوبتــه الــواردة‬\n‫بالفقــرة رقــم (‪ )1‬مــن املــادة (‪ )68‬الثامنــة والســتون مــن نظــام املــرور‬\n‫علــى ذلــك عائــد للجهــات املختصــة هكــذا ادعــى وبســؤال املدعــى عليــه‬\n‫أجــاب قائــا مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح وصحيــح‬\n‫أننــي أتعاطــي احلشــيش املخــدر ومــا حصــل خطــأ منــي وأنــا تائــب إلــى‬\n‫اهلل ممــا فعلــت لكنــي معتــرض علــى إبعــادي عــن البــاد فأنــا مســتثمر‬\n‫يف هــذه البــاد ولــدي مــا يزيــد عــن أربعــن عامــا وعــدة مصانــع للرخــام‬\n‫علي وعلى‬ ‫املزخــرف والطــاوالت الرخاميــة ويف إبعــادي عــن البالد ضــرر ّ‬\n‫مــن يعمــل عنــدي وفيــه خســارة ماليــة كبيــرة جــدا هكــذا أفــاد ثــم ابــرز‬\n‫لنــا مــا يفيــد ذلــك مــن ســجالت جتاريــة بعــدد أربــع مصانــع يف ‪ ....‬و‪......‬‬\n‫و‪ ..........‬و‪ .....‬ومرخــص لــه مــن قبــل الهيئــة العامــة لالســتثمار وبرنــت‬\n‫صــادر مــن اجلــوازات مبــن يعمــل لديــه مرفقــه صورهــا باملعاملــة وبعــد‬\n‫ذلــك رأيــت رفــع اجللســة للتأمــل وحــدد لهــم موعــد يــوم االثنــن املوافــق‬\n‫‪1434/6/19‬ه ـ الســاعة التاســعة اختتمــت اجللســة الســاعة ‪ 8.55‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                           ‫يف ‪1434/06/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االثنــن املوافــق ‪1434/06/19‬‬\n‫ويف متــام الســاعة التاســعة افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‬\n‫وحضــر حلضــوره املدعــى عليــه وبعــد تأمــل الدعــوى واإلجابــة واالطــاع‬\n‫علــى املعاملــة اخلاصــة بهمــا وبنــاء علــى مــا تقــدم وبنــاء علــى التقريــر‬\n‫الكيميائــي الشــرعي املتضمــن إيجابيــة العينــة املضبوطــة مــع املدعــى‬\n‫عليــه وبنــاء علــى مصادقــة املدعــى عليــه علــى دعــوى املدعــي العــام‬\n‫وأعلــن توبتــه وندمــه وذكــر انــه مســتثمر يف البــاد وان يف احلكــم يف‬\n\n\n                                                                                      ‫‪192‬‬\n\f      ‫إبعــاده عــن البــاد مفســده وبنــاء علــى القاعــدة الشــرعية التــي تقــول درء‬\n      ‫املفاســد أولــى مــن جلــب املصالــح ‪ ،‬وهــي قاعــدة جليلــة القــدر عظيمــة‬\n      ‫النفــع‪ ،‬وحاصلهــا أن دالئــل الشــريعة املطهــرة دلــت علــى أنــه حكــم اهلل‬\n      ‫تعالــى يــدور مــع مــا يترجــح عنــد تعــارض املصالــح واملفاســد‪ ،‬واملضــار‬\n      ‫واملنافــع‪ ،‬فيكــون الشــيء مطلوبــا شــرعا إن ترجحــت مصاحلــه علــى‬\n      ‫مفاســده‪ ،‬ويكــون ممنوعــا إن كان العكــس ‪ ،‬ومبــا أن يف إبعــاد‬\n      ‫املدعــى عليــه عــن البــاد مفســدة أعظــم مــن املصلحــة يف عقوبتــه بإبعــاده‬\n      ‫إذ الضــرر متعــدٍ عليــه وعلــى غيــره ولقولــه الرســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم ( ال ضرر وال ضرار )‪ ،‬حديث حســن رواه ابن ماجة والدارقطني‬\n      ‫وحيــث ال يوجــد ســوابق مســجلة علــى املدعــى عليــه لذلــك كلــه ثبــت‬\n      ‫لــدي شــرعا إدانــة املدعــى عليــه مبــا نســب إليــه يف الدعــوى وحكمــت‬\n      ‫عليــه باالتــي أو ًال ‪ /‬حكمــت علــى املدعــى عليــه مبوجــب املــادة احلاديــة‬\n      ‫واألربعــن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واســتنادا‬\n      ‫إلــى املــادة الســتني مــن ذات النظــام وحيــث اظهــر املدعــى عليــه توبتــه‬\n      ‫وندمــه ولعــدم وجــود ســوابق مســجلة عليــه لــذا حكمــت عليــه بالســجن‬\n      ‫أربعــة أشــهر‪ .‬ثانيـاً‪ /‬حكمــت عليــه مبوجــب املــادة السادســة واخلمســن‬\n      ‫الفقــرة الثانيــة مــن ذات النظــام بإبعــاده عــن البــاد بعــد تنفيــذ العقوبــة‬\n      ‫بحقــه وال يســمح لــه بالعــودة إليهــا‪ ،‬إال فيمــا عــدا مــا تســمح بــه تعليمــات‬\n      ‫احلــج والعمــرة مــع وقــف تنفيــذ العقوبــة بحقــه للمصلحــة الراجحــة يف‬\n      ‫ذلــك ويف حــال عودتــه ألي فعــل معاقــب عليــه شــرعا تنفــذ العقوبــة بحقــه‬\n      ‫بإبعــاده عــن البــاد‪ .‬ثالث ـاً‪ /‬حكمــت عليــه بجلــده ثمانــن جلــده دفعــة‬\n      ‫واحــده حــد املســكر لقــاء اعترافــه بتعاطــي احلشــيش املخــدر‪ .‬رابع ـاً‪/‬‬\n      ‫ثبــت لــدي إدانتــه بقيــادة الســيارة حتــت تأثيــر احلشــيش املخــدر وافهمتــه‬\n\n\n‫‪193‬‬\n\f‫إن عقوبتــه علــى ذلــك عائــدة للجهــة املختصــة هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم‬\n‫كمــا قــرر املدعــي العــام املعارضــة علــى احلكــم وطلــب رفــع احلكــم‬\n‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة واالكتفــاء بالئحــة‬\n‫الدعــوى العامــة وأمــرت بتنظيــم القــرار الــازم لذلــك ورفعــه مــع كامــل‬\n‫أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم اختتمــت اجللســة‬\n‫الســاعة ‪ ...9.45‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/08/09‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليــه وقــد عــادت أوراق املعاملــة بخطــاب رئيــس محكمــة االســتئناف‬\n‫برقــم ‪ 341657838‬يف ‪1434/07/29‬ه ـ مشــفوعا بهــا قــرار املالحظــة‬\n‫مــن أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة اجلزائيــة الثالثــة برقــم‬\n‫‪34272315‬يف ‪1434/07/18‬ه ـ املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫وباالطــاع علــى مــا جــاء يف القــرار وصــورة ضبطــه وأوراق املعاملــة تقــرر‬\n‫إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن مــا قــرره فضيلتــه مــن وقــف‬\n‫تنفيــذ العقوبــة املقــررة بحــق املدعــى عليــه يف الفقــرة ثانيــا ملــا قــرره مــن‬\n‫تعليــل يف غيــر محلــه فــا اجتهــاد مــع وجــود نــص نظامــي فعلــى فضيلتــه‬\n‫مالحظــة مــا ذكــر وإكمــال الــازم واهلل املوفــق وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى الــه وصحبــه ســلم أه ـ ولوجاهــة مــا ذكــره أصحــاب‬\n‫الفضيلــة قضــاة االســتئناف فقــد رجعــت عــن حكمــي يف وقــف تنفيــذ‬\n‫العقوبــة بحــق املدعــى عليــه يف إبعــاده عــن البــاد وأفهمــت املدعــى عليــه‬\n\n\n                                                                                          ‫‪194‬‬\n\f      ‫إن احلكــم نافــذا حســب األنظمــة والتعليمــات يف ذلــك هــذا مــا ظهــر لــي‬\n      ‫وبــه حكمــت وبعرضــه علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب‬\n      ‫رفــع احلكــم لالســتئناف بــدون الئحــة واالكتفــاء بــاألوراق الســابقة‬\n      ‫املرفقــة باملعاملــة وأمــا املدعــي العــام فقــرر عــدم املعارضــة علــى احلكــم‬\n      ‫وأمــرت باحلــاق ذلــك يف القــرار وإعــادة كامــل أوراق املعاملــة حملكمــة‬\n      ‫االســتئناف لتدقيــق احلكــم اختتمــت اجللســة الســاعة الثامنــة والربــع‬\n      ‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم‪ .‬حــرر يف ‪1434/08/09‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف خميــس مشــيط برقــم‬\n      ‫‪ 341876675‬وتاريــخ ‪1434/8/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .................‬برقــم ‪34246254‬‬\n      ‫وتاريــخ ‪1434/6/19‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪............‬‬\n      ‫مينــي اجلنســية ‪ -‬يف قضيــة (مخــدرات) علــى الصفــة املوضحــة يف القــرار‬\n      ‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث ســبق‬\n      ‫دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب‬\n      ‫بــه فضيلتــه واحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قــرار الدائــرة رقــم‬\n      ‫‪ 34272315‬وتاريــخ ‪1434/7/18‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء األخيــر‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                      ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪195‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":189,"source_page_end":195,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"945c5bbccaa75f2947df26644f59da368422a4f45d9bd3ab32adc7f36a2a3669","normalized_text_hash":"78f4c07eb053d77581c2f00631788611b894d90667514e26712d6e3c993b53c5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p189-3424254"},{"id":"21972ea3-c061-5778-8d22-6620cc4e50f3","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي والترويج -إقرار -دفع غير مقبول ملوجب -إدانة باحليازة املجردة عن القصد -عقوبة بحدها األعلى -سوابق.","document_number":"34241672","case_number":"34255436","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/14","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي والترويج -إقرار -دفع غير مقبول ملوجب -إدانة باحليازة املجردة عن القصد -عقوبة بحدها األعلى -سوابق.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34241672:‬تاريخه‪1434/06/14:‬هـ‬\n                   ‫رقم الدعوى‪34255436:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34269274‬تاريخه‪1434/07/16:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي‬\n‫والترويــج‪ -‬إقــرار‪ -‬دفــع غيــر مقبــول ملوجــب‪ -‬إدانــة باحليــازة املجــردة‬\n                     ‫عــن القصــد ‪ -‬عقوبــة بحدهــا األعلــى ‪ -‬ســوابق‪.‬‬\n\n\n\n\n‫املــواد (‪ )38‬و(‪ )39‬و(‪ )56‬و(‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                               ‫العقليــة‪.‬‬\n\n\n\n\n‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة بقصــد الترويــج وحيــازة‬\n‫ســيجارة حشــيش بقصــد االســتعمال ‪ ،‬واحلكــم عليــه بعقوبــة الســجن‬\n‫واجللــد والغرامــة واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة حيــث قبــض عليــه بعــد ورود معلومــات عــن ترويجــه‬\n‫املخــدرات وبتفتيشــه شــخصيا عثــر بحوزتــه علــى حبــوب محظــورة‬\n‫و ســيجارة حشــيش وبتفتيــش منزلــه عثــر علــى كميــة كبيــرة مــن‬\n‫احلشــيش واحلبــوب احملظــورة‪ -‬أثبــت التقريــر الكيميائــي الشــرعي‬\n‫إيجابيــة العينــة املرســلة للحشــيش املخــدر واإلمفيتامــن‪ ،‬أقــر أمــام‬\n‫احملكمــة بحيــازة املخــدرات إال أنــه دفــع بكــون قصــده مــن حيازتهــا‬\n\n                                                                                 ‫‪196‬‬\n\f      ‫تســليمها للجهــة املختصــة‪ ،‬املدعــى عليــه مــن أربــاب الســوابق ومــا دفــع‬\n      ‫بــه غيــر مقبــول فقــد قضــت احملكمــة بإدانــة املدعــى عليــه بحيــازة‬\n      ‫احلشــيش املخــدر واحلبــوب احملظــورة حيــازة مجــردة مــع التهمــة القويــة‬\n      ‫بــأن يكــون قصــده الترويــج وقــررت ســجنه ملــدة خمــس ســنوات وجلــده‬\n      ‫خمســمائة جلــدة مفرقــة وتغرميــه مبلــغ خمســة آالف ريــال ومنعــه مــن‬\n      ‫الســفر خــارج اململكــة ملــدة خمــس ســنوات وقــد عــارض املدعــى عليــه‬\n      ‫واملدعــي العــام علــى احلكــم‪ ،‬قــررت محكمــة االســتئناف املوافقــة‬\n                                                                       ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/6/14‬ه ـ لــدي أنــا‬\n      ‫القاضــي باحملكمــة اجلزائيــة بالطائــف وبنــاء علــى املعاملــة املقيــدة برقم‬\n      ‫‪ 341345013‬يف ‪1434/6/4‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيس برقم‬\n      ‫‪ 34255436‬يف ‪1434/6/4‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــى‬\n      ‫العــام بالتعميــد رقــم ‪ 2367‬يف ‪1433/3/12‬هـ ـ وادعــى علــى احلاضــر‬\n      ‫باملجلــس الشــرعي‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫ـاء علــى توفــر املعلومــات إلدارة مكافحــة املخــدرات‬      ‫‪ .......‬قائــا انــه بنـ ً‬\n      ‫عــن قيــام شــخص بترويــج احلبــوب احملظــورة واحلشــيش املخــدر بحــي‬\n      ‫العقيــق وميتلــك ســيارة رقــم اللوحــة (‪ ).....‬ومبتابعتــه والبحــث والتحــري‬\n      ‫عنــه لوحــظ املدعــى عليــه بقيــادة الســيارة املذكــورة مبحطــة جبــال‬\n      ‫الهــدا وبالقبــض عليــه وتفتيشــه ضبــط يف برجلــه اليمنــى كيــس نايلــون‬\n      ‫بداخلــه (‪ )399‬حبــة كانــت (بالشــراب) وضبــط برجلــه اليمنــى علــى‬\n      ‫بكــت دخــان بداخلــه ســيجارة ملفوفــة تــزن (‪ )2.3‬جرامــن وثالثــة‬\n\n‫‪197‬‬\n\f‫مــن العشــرة مــن اجلــرام كانــت بالشــراب وباالنتقــال ملنــزل املدعــى‬\n‫عليــه وتفتيــش الغرفــة اخلاصــة باملدعــى عليــه عثــر علــى حقيبتــن‬\n‫ذكــر املدعــى عليــه بأنهــا لــه وبتفتيــش احلقيبــة األولــى ضبــط بداخلهــا‬\n‫(‪ )6896‬حبــه وبتفتيــش احلقيبــة الثانيــة ضبــط بداخلهــا أكيــاس تــزن‬\n‫(‪ )2869.5‬ألفــان وثمامنائــة وتســعة وســتون جــرام ونصــف كمــا عثــر‬\n‫داخــل الشــنطة علــى ثالثــة مسدســات (مت فــرز أوراق مســتقلة لقضيــة‬\n‫الســاح ) وقــد أثبتــت التقريــر الكيميائــي الشــرعي رقــم ( ‪)5805‬‬\n‫وتاريــخ ‪1434/4/2‬ه ـ احتــواء مــا مت ضبطــه علــى مادتــي احلشــيش‬\n‫املخــدر واإلمفيتامــن احملظورتــن وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫للمدعــى عليــه بحيــازة (‪ )7295‬ســبعة اآلف ومائتــن وخمســة وتســعني‬\n‫حبــة مــن حبــوب اإلمفيتامــن احملظــورة وأكيــاس بهــا حشــيش مخــدر‬\n‫تــزن (‪ )2869.5‬ألفــان وثمامنائــة وتســعة وســتون جــرام وخمســة مــن‬\n‫العشــرة مــن اجلــرام بقصــد الترويــج لكبــر الكميــة وحيــازة ســيجارة‬\n‫ممزوجــة باحلشــيش املخــدر تــزن (‪ )2.3‬جرامــن وثالثــة مــن العشــرة‬\n‫مــن اجلــرام بقصــد االســتعمال وهــو فعــل محــرم ومعاقــب عليــه نظام ـ ًا‬\n‫وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات الصــادر‬\n‫باملرســوم امللكــي رقــم (‪ )39‬وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة‬\n‫والقرائــن التاليــة ‪ -1‬محضــر القبــض والتفتيــش املنــوه عنــه ‪ -2‬التقريــر‬\n‫الكيميائــي الشــرعي املنــوه عنــه املرفــق وبالبحــث عــن ســوابقه عثــر لــه‬\n‫علــى أربعــة عشــر ســابقة ســت ســوابق ســرقة نصــب واحتيــال وســابقة‬\n‫مضاربــة وســابقة محاولــة لــواط وســابقة فعــل فاحشــة لــواط ونهــب‬\n‫وســابقتي حيــازة واســتعمال مخــدرات وســابقة اشــتباه ترويــج مخــدرات‬\n‫وســابقة تســتر وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n\n\n                                                                                  ‫‪198‬‬\n\f      ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ومجــرم نظامـ ًا أطلــب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه‪ -1 -:‬ســجنه وجلــده وتغرميــه وفقـ ًا‬\n      ‫للفقــرة األولــى مــن املــادة الثامنــة والثالثــن مــن النظــام املشــار إليــه‪-2 .‬‬\n      ‫منعــه مــن الســفر خلــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتــه وفقـ ًا للفقــرة‬\n      ‫األولــى مــن املــادة السادســة واخلمســن‪ .‬هــذه دعــواي‪ .‬وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره املدعــي العــام يف دعــواه مــن‬\n      ‫اتهامــي بحيــازة الكميــة املضبوطــة مــن احلبــوب احملظــورة واحلشــيش‬\n      ‫املخــدر بقصــد الترويــج وحيازتــي لســيجارة ممزوجــة باحلشــيش املخــدر‬\n      ‫بقصــد االســتعمال فكلــه غيــر صحيــح إطالق ـ ًا ‪ ،‬والصحيــح أننــي‬\n      ‫اســتأجرت ســيارة وركــب معــي شــخص أثيوبــي وعنــد مشــاهدته‬\n      ‫رجــال األمــن هــرب فذهبــت إلــى البيــت ووجــدت يف شــنطة الســيارة‬\n      ‫الشــنطتني املضبوطتــن وأظنهــا لذلــك الشــخص فقمــت بإنزالهــا يف‬\n      ‫منزلــي بقصــد تســليمها للقســم الحق ـ ًا وأنــا ال أعلــم مــا بداخلهــا ويف‬\n      ‫اليــوم التالــي وجــدت يف الســيارة كيــس نايلــون يحتــوي علــى (‪)399‬‬\n      ‫ثالثمائــة وتســع وتســعني حبــة مــن احلبــوب احملظــورة وســيجارة حشــيش‬\n      ‫فخشــيت أن يتــم القبــض علــي وهــي بحوزتــي فقمــت بوضــع الكيــس‬\n      ‫الــذي يحتــوي علــى احلبــوب بداخــل شــرابي وســيجارة احلشــيش بداخلهــا‬\n      ‫البكــت املربــوط برجلــي حتــى أرجــع إلــى البيــت وأســلمها جميع ـ ًا‬\n      ‫للحكومــة مــع الشــنطتني التــي يف املنــزل فتــم القبــض علــي واتهامــي‬\n      ‫بذلــك ‪ ،‬وأمــا الســوابق التــي علــى فصحيحــة هكــذا أجــاب فســألت‬\n      ‫املدعــي العــام عــن البينــة علــى دعــواه فيمــا نفــاه املدعــى عليــه فأجــاب‬\n      ‫بقولــه‪ :‬بينتــي علــى ذلــك إقــراره املرصــود باملعاملــة لفــة (‪ )1‬ص (‪)14‬‬\n      ‫املتضمــن (إقــراره بــأن جميــع مــا ضبــط بحوزتــه يعــود لــه شــخصياً) ‪،‬‬\n\n\n‫‪199‬‬\n\f‫وكــون الكميــة املضبوطــة كبيــرة ‪ ،‬وليــس لــدي ســوى ذلــك هكــذا‬\n‫أجــاب وبعــرض هــذا اإلقــرار علــى املدعــى عليــه أجــاب بقولــه‪ :‬إننــي لــم‬\n‫أعتــرف بذلــك إطالقـ ًا هكــذا أجــاب وبتصفــح أوراق املعاملــة لفــه (‪)1‬‬\n‫ص (‪ )23‬تبــن وجــود إقــرار للمدعــى عليــه يتضمــن (اعترافــه بأنــه أقــر‬\n‫بإقــراره الســابق خوف ـ ًا علــى والدتــه) وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أجــاب بقولــه‪ :‬هــذا صحيــح فقــد اعترفــت بذلــك خوف ـ ًا علــى والدتــي‬\n‫ألنهــا كانــت معــي وأريــد الذهــاب بهــا إلــى املنــزل هكــذا أجــاب فبعــد‬\n‫ســماعي للدعــوى وإجابــة املدعــى عليــه بنفــي مــا جــاء فيهــا مــع إقــراره‬\n‫بحيــازة الكميــة الــواردة يف الدعــوى وإخفــاءه لكميــة مــن احلبــوب‬\n‫ا ذلــك‬ ‫وســيجارة حشــيش يف رجلــه ويف الشــراب التــي كانــت عليــه معلـ ً‬\n‫مبــا جــاء يف جوابــه ‪ ،‬وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا أقــوال‬\n‫املدعــى عليــه املشــار إلــى مضمونهــا ســابق ًا ‪ ،‬والتقريــر الكيميائــي‬\n‫الشــرعي املتضمــن إيجابيــة العينــات املضبوطــة ملادتــي احلشــيش املخــدر‬\n‫واإلمفيتامــن احملظورتــن ‪ ،‬وألن مــا ذكــره املدعــى عليــه مــن تعليــل ال‬\n‫ميكــن قبولــه ؛ ألن املفتــرض يف مثــل هــذه احلالــة تســليم هــذه احلقائــب‬\n‫إلــى اجلهــة املختصــة مباشــرة ‪ ،‬كمــا أن مــا ذكــره مــن إخفــاءه لكميــة‬\n‫مــن احلبــوب احملظــورة وســيجارة حشــيش يــدل علــى أنهــا تعــود لــه ‪،‬‬\n‫كمــا أن تضــارب أقوالــه يف املعاملــة وأثنــاء احملاكمــة يقــوي التهمــة‬\n‫ضــده بصحــة مــا نســب إليــه إضافــة إلــى وجــود ســوابق لــه يف حيــازة‬\n‫وترويــج املخــدرات ‪ ،‬ولكــون الكميــة املضبوطــة كبيــرة واألصــل يف‬\n‫ـاء علــى املــواد الثامنــة والثالثني والتاســعة‬\n                                               ‫مثلهــا أن يكــون للترويــج ‪ ،‬وبنـ ً‬\n‫والثالثــن والسادســة واخلمســن والثانيــة والســتني مــن نظــام مكافحــة‬\n‫املخــدرات ‪ ،‬وألن بينــة املدعــي العــام يف كــون الكميــة املضبوطــة مــع‬\n\n\n                                                                                       ‫‪200‬‬\n\f      ‫املدعــى عليــه تعــود لــه بقصــد الترويــج غيــر موصلــة وألن األصــل أن مــن‬\n      ‫وجــد معــه شــيء فهــو لــه حتــى يثبــت خــاف ذلــك ‪ ،‬ولكثــرة ســوابق‬\n      ‫املدعــى عليــه لهــذا كلــه فقــد صــدر منــي مــا يلــي‪ :‬أوالً‪ :‬ثبــت لــدي‬\n      ‫إدانــة املدعــى عليــه بحيــازة الكميــة املضبوطــة والــواردة يف الدعــوى‬\n      ‫مــن احلشــيش املخــدر وحبــوب االمفتيامــن احملظــورة حيــازة مجــردة‬\n      ‫وحكمــت عليــه لقــاء ذلــك بســجنه خمــس ســنوات مــن تاريــخ إيقافــه ‪،‬‬\n      ‫وجلــده خمســمائة جلــده مفرقــة علــى عشــر دفعــات متســاوية يف العــدد‬\n      ‫بــن كل دفعــة وأخــرى مــدة ال تقــل عــن أســبوع ‪ ،‬وتغرميــه خمســة آالف‬\n      ‫ريــال ‪ ،‬ومنعــه مــن الســفر خــارج اململكــة ملــدة خمس ســنوات بعــد انتهاء‬\n      ‫محكوميتــه‪ .‬ثاني ـاً‪ :‬لــم تثبــت لــدي إدانتــه بحيــازة الكميــة املضبوطــة‬\n      ‫بقصــد الترويــج وإمنــا تتوجــه التهمــة القويــة ضــده بذلــك واكتفيــت‬\n      ‫بعقوبتــه علــى ذلــك مبــا ورد يف (أوال) ‪ ،‬وبعــرض احلكــم علــى املدعــى‬\n      ‫عليــه قــرر االعتــراض بــدون الئحــة وأمــا املدعــي العــام فقــرر االعتــراض‬\n      ‫بالئحــة فجــرى إفهامــه بتعليمــات االســتئناف وصلــى اهلل وســلم علــى‬\n      ‫ســيدنا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1434/6/14‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافــق ‪1434/7/29‬ه ـ‬\n      ‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n      ‫قــرار الدائــرة اجلزائيــة اخلامســة رقــم (‪ )34269274‬يف ‪1434/7/16‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬وللمعلوميــة جــرى حتريــر ذلــك ‪،‬‬\n              ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/7/29‬هــ‪.‬‬\n\n\n\n\n‫‪201‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":196,"source_page_end":201,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ede58b3296b7aa0b02b5afb2de2a8882bcd23c42e3167866327f7669e66618d4","normalized_text_hash":"5c25449eed0c1007307d9d030e418306c1a4d91c4d0ebdd9536c7f96bc9c5012","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p196-34241672"},{"id":"946f735f-b6ad-5637-841b-f3aa78492a59","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد الترويج وتعاطيه والشروع يف بيعه- إقرار -عدم احلاجة لسماع شهادة الشهود -بينة غير موصلة -إدانة باحليازة بقصد التعاطي -نزول عن احلد األدنى للعقوبة.","document_number":"34252509","case_number":"34283189","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/26","year":"1434","subject":"مخدرات -حيازة حشيش بقصد الترويج وتعاطيه والشروع يف بيعه- إقرار -عدم احلاجة لسماع شهادة الشهود -بينة غير موصلة -إدانة باحليازة بقصد التعاطي -نزول عن احلد األدنى للعقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34252509 :‬تاريخه‪1434/06/26 :‬هـ‬\n                    ‫رقم الدعوى‪34283189 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34277618‬تاريخه‪1434/7/24:‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد الترويــج وتعاطيــه والشــروع يف بيعه‪-‬‬\n ‫إقــرار‪ -‬عــدم احلاجــة لســماع شــهادة الشــهود ‪ -‬بينــة غيــر موصلــة‪ -‬إدانــة‬\n              ‫باحليــازة بقصــد التعاطــي‪ -‬نــزول عــن احلــد األدنــى للعقوبة‪.‬‬\n\n\n\n\n ‫املــواد (‪ )41‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                          ‫العقليــة‪.‬‬\n\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n ‫بحيــازة احلشــيش املخــدر بقصــد الترويــج وشــروعه يف ترويجــه وتعاطيــه‬\n ‫لــه‪ ،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة واملصــادرة واإلبعــاد‬\n ‫عــن البــاد طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬مت‬\n ‫االتفــاق معــه علــى شــراء حشــيش مخــدر فوافــق علــى ذلــك ويف الوقــت‬\n ‫واملــكان احملدديــن حضــر وعنــد شــروعه يف اإلســتالم والتســليم شــاهد‬\n ‫رجــال األمــن فحــاول ابتــاع قطعــة احلشــيش املتفق على شــراءها فقبض‬\n ‫عليــه‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n ‫للحشــيش املخــدر‪ ،‬أقــر أمــام احملكمــة بحيــازة احلشــيش املخــدر‬\n ‫بقصــد التعاطــي وتعاطيــه لــه وأنكــر أن يكــون قصــده الترويــج‪،‬‬\n\n                                                                                     ‫‪202‬‬\n\f      ‫اطلعــت احملكمــة علــى بينــات املدعــي العــام وقــررت عدم احلاجة لســماع‬\n      ‫شــهادة شــهود محضــر القبــض لكونــه لــم يتضمــن اإلشــارة إلــى عمليــة‬\n      ‫االســتالم والتســليم‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه بحيــازة‬\n      ‫احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لــه وقــررت جلــده ثمانــن‬\n      ‫جلــدة دفعــة واحــدة حــد املســكر وســجنه ملــدة شــهرين وإبعــاده إلــى‬\n      ‫بــاده‪ ،‬كمــا قضــت بــرد طلــب املدعــي العــام تطبيــق املــواد (‪)53-38‬‬\n      ‫بحقــه لعــدم ثبــوت موجبــه‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‬\n           ‫العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنا القاضــي يف احملكمة اجلزائية مبحافظة‬\n      ‫القطيــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة مبحافظــة القطيف برقــم ‪ 34283189‬وتاريخ ‪1434/06/19‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 341487741‬وتاريــخ ‪1434/06/19‬ه ـ ففــي‬\n      ‫يــوم االثنــن ‪ 1434/06/26‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪10 :30‬‬\n      ‫وفيهــا حضــر املدعــي العــام بصفتــي مدعي ـ ًا عامــا يف دائــرة التحقيــق‬\n      ‫واالدعــاء العــام مبحافظــة القطيــف أدعــي علــى البالــغ مــن العمــر (‪)25‬‬\n      ‫بحرينــي اجلنســية الجــئ برقــم (‪ )....‬محصــن موظــف أهلــي املقبــوض‬\n      ‫عليــه بتاريــخ ‪1434/4/21‬ه ـ وأحيــل لســجن محافظــة القطيــف اســتنادا‬\n      ‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ باالطــاع علــى‬\n      ‫محضــر البــاغ والقبــض والتفتيــش املعــد مــن قبل رجال الضبــط اجلنائي‬\n      ‫مبكافحــة املخــدرات بالدمــام تبــن أنــه بتاريــخ ‪ 1434/4/21‬ه ـ وبنــاء‬\n      ‫علــى املعلومــات املتوفــرة مــن أحــد مصادرهــم الســرية والتــي تفيــد عــن‬\n\n‫‪203‬‬\n\f‫شــخص يدعــى (‪ )....‬مــن ســكان القطيــف داريــن لــه نشــاط يف ترويــج‬\n‫احلشــيش املخــدر واحلبــوب احملظــورة ويســتخدم اجلــوال رقــم () واســتعد‬\n‫املصــدر لإلطاحــة باملذكــور باجلــرم املشــهود عليــه فقــد مت متكــن‬\n‫املصــدر مــن االتصــال هاتفيــا علــى املــروج وطلــب منــه شــراء حشــيش‬\n‫مخــدر مببلــغ مئتــي ريــال وحبــوب محظــورة مببلــغ مئتــي ريــال فوافــق‬\n‫املــروج علــى ذلــك وطلــب مــن املصــدر احلضــور لــه عنــد منزلــه وأنــه جاهــز‬\n‫لتســليمها وجــرى تفتيــش املصــدر وســيارته وترقيــم مبلــغ وقــدره (‪)400‬‬\n‫أربعمائــة ريــال وزود املصــدر باملبلــغ احلكومــي وحتــرك حتــت أنظــار‬\n‫الفرقــة حتــى تقابــل مــع املروج ثم ركب املروج مع املصدر وعند شــروعه‬\n‫يف عمليــة االســتالم والتســليم شــاهد الفرقــة فحــاول ابتــاع القطعة التي‬\n‫مت االتفــاق علــى بيعهــا ومتــت الســيطرة عليــه وبتفتيشــه شــخصي ًا لــم يعثــر‬\n‫بحوزتــه علــى أي شــيء مــن احملظــورات وعثــر معــه علــى الهاتــف اجلــوال‬\n‫الــذي قــام باســتخدامه للتنســيق يف عمليــة الترويــج ومبلــغ وقــدره (‪)886‬‬\n‫ثمامنائــة وســتة وثمانــون ريــاال وبطاقــة صــراف (‪ ).....‬وفيــزا كارت (‪).....‬‬\n‫ومفتــاح ســيارة وأقــر املــروج أمــام الفرقــة بــأن هــذه هــي القطعــة التــي‬\n‫أحضرهــا للترويــج والتــي حــاول ابتالعهــا‪ ،‬وهــي قطعــة تــزن خمســة‬\n‫جرامــات وثمانيــة مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر أثبــت‬\n‫التقريــر الكيميائــي الشــرعي رقــم (‪ )2035‬وتاريــخ ‪ 1434/4/29‬ه ـ‬\n‫إيجابيــة عينــة مــا مت ضبطــه ملــادة احلشــيش املخــدر واملــدرج علــى اجلــدول‬\n‫األول فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات وباســتجوابه أقــر‬\n‫بأنــه يتعاطــى احلشــيش املخــدر ومبواجهتــه مبــا ورد مبحضــر القبــض‬\n‫مــن أنــه مت االتصــال بــه علــى جوالــه رقــم () ذكــر أن بينــه وبــن صلــة‬\n‫قرابــة وأنــه اتصــل بــه أكثــر مــن مــرة يطلــب منــه املخــدرات وذكــر‬\n\n                                                                                      ‫‪204‬‬\n\f      ‫لــه بأنــه ال يســتطيع إحضــار املخــدرات لــه وانــه ال يقــوم بالترويــج وقــد‬\n      ‫أســفر التحقيــق عــن اتهامــه بحيــازة قطعــة تــزن خمســة جرامــات وثمانيــة‬\n      ‫مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر بقصــد الترويــج والشــروع‬\n      ‫وفقــا للفقــرة رقــم (‪ )2‬مــن‬\n                                   ‫يف بيعهــا وتعاطيــه احلشــيش املخــدر املجــرم ً‬\n      ‫املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة ‪-1‬محضــر البــاغ والقبــض والتفتيــش املنــوه‬\n      ‫عنــه املــدون علــى الصفحــات رقــم (‪ )11-2‬مــن ملــف ضبــط إجــراءات‬\n      ‫االســتدالل املرفــق علــى اللفــة رقــم (‪-2 )1‬إقــراره بــان مــا مت ضبطــه يعــود‬\n      ‫لــه شــخصيا بقصــد االســتخدام وباســتخدامه للحشــيش املخــدر املــدون‬\n      ‫علــى الصفحــة رقــم (‪ )1‬مــن محضــر االســتجواب املرفــق علــى اللفــة‬\n      ‫رقــم (‪-3 )13‬التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق علــى‬\n      ‫اللفــة رقــم (‪ )19‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى‬\n      ‫ســوابق مســجله علــى املســتوى العــام وحيــث إن مــا أقــدم عليــه املذكــور‬\n      ‫وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ونظام ـ ًا لــذا أطلــب احلكــم عليــه مبــا يلــي أوال‪ :‬إثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه مبــا يلــي ‪ -1‬بعقوبــة الســجن واجللــد والغرامــة الــواردة‬\n      ‫بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام مــع مراعــاة مــا ورد‬\n      ‫باملــادة رقــم (‪ )62/1‬مــن النظــام ‪-2‬إبعــاده عــن اململكــة إعمــاال ملقتضــى‬\n      ‫الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن النظــام ثانيـاً‪ :‬مصــادرة الهاتــف‬\n      ‫اجلــوال العائــد للمدعــى عليــه مــن نــوع (‪ ).....‬برقــم االتصــال (‪ ).....‬ويحمــل‬\n      ‫الرقــم املصنعــي (‪ ).....‬الرتباطــه بالقضيــة وفقــا للفقــرة رقــم (‪ )1‬مــن‬\n      ‫املــادة رقــم (‪ )53‬مــن النظــام مــع املطالبــة بإســقاط شــريحة الهاتــف‬\n      ‫النقــال وعــدم صرفهــا لنفــس املدعــى عليــه وفقــا لتعميــم ســمو وزيــر‬\n\n\n‫‪205‬‬\n\f‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1429/2/10-9‬ه ـ هــذه دعواي والســام‬\n‫وبعرضهــا علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام مــن القبــض‬\n‫علــي يف تاريــخ ‪ 1434/4/21‬ه ـ عندمــا اتصــل بــي صديــق لــي وطلــب‬\n‫مقابلتــي عنــد البــاب وخرجــت وركبــت معــه الســيارة وأثنــاء ذلــك حضــر‬\n‫فرقــة مــن مكافحــة املخــدرات وعندمــا شــاهدتهم كان معــي قطعــة‬\n‫حشــيش مخــدر صغيــرة حاولــت ابتالعهــا والعثــور بحوزتــي علــى الهاتــف‬\n‫اجلــوال رقــم (‪ ).....‬ومبلــغ قــدره ثمامنائــة وســتة وثمانــون ريــا ًال وبطاقــة‬\n‫صــراف ومفتــاح ســيارة وجهــاز جــوال مــن نــوع (‪ ).....‬كل ذلــك صحيــح‬\n‫ا وقصــدي مــن حيــازة هــذه القطعــة التعاطــي الشــخصي‬          ‫جملـ ًة وتفصيـ ً‬\n‫وأنــا أتعاطــى احلشــيش املخــدر منــذ فتــرة وأمــا مــا ذكــره املدعــي العــام‬\n‫مــن ترويجــي احلشــيش املخــدر واحلبــوب احملظــورة وشــروعي يف عمليــة‬\n‫ا والصحيــح‬    ‫بيــع هــذه القطعــة كل ذلــك غيــر صحيــح جمل ـ ًة وتفصي ـ ً‬\n‫مــا ذكرتــه لكــم وبطلــب البينــة مــن املدعــي العــام علــى نيــة الترويــج‬\n‫وشــروعه يف بيعهــا قــال بينتــي إقــراره حتقيق ـ ًا املــدون علــى لفــة رقــم‬\n‫(‪ )13-12-11‬ومحضــر البــاغ والقبــض والتفتيــش املــدون علــى صفحــة‬\n‫(‪ )11-2‬مــن ملــف التحقيــق املرفــق لفــة رقــم (‪ )1‬ومبطالعــة اقــراره‬\n‫حتقيق ـ ًا وجدتــه موافق ـ ًا إلجابتــه لدينــا يف املجلــس الشــرعي ومبطالعــة‬\n‫محضــر القبــض املــدون علــى صفحــة (‪ )11‬مــن ملف التحقيــق املرفق لفة‬\n‫رقــم (‪ )1‬وجدتــه موافق ـ ًا لدعــوى املدعــي العــام وبعــرض احملضــر علــى‬\n‫املدعــى عليــه قــال احملضــر غيــر صحيــح بخصــوص شــروعي يف عمليــة‬\n‫ترويــج هــذه القطعــة مــن احلشــيش املخــدر والصحيــح مــا ذكرتــه لكــم‬\n‫هــذا وقــد جــرى االطــاع علــى التقريــر الكيمــاوي الشــرعي املشــار‬\n‫إليــه أعــاه فوجدتــه كمــا ذكــر وإلــى أن محضــر القبــض والتفتيــش‬\n\n\n                                                                                       ‫‪206‬‬\n\f      ‫والضبــط املشــار إليــه أعــاه ليــس فيــه مــا يشــير إلــى عمليــة االســتالم‬\n      ‫والتســليم وهــي الركــن األســاس واملؤثــر يف إثبــات الترويــج مــن عدمــه‬\n      ‫ـاء علــى مــا تقــدم مــن‬\n                              ‫لــذا لــم أجــد مــا يبــرر إحضــار الفرقــة القابضــة فبنـ ً‬\n      ‫الدعــوى واإلجابــة وإلــى مصادقــة املدعــى عليــه علــى دعــوى املدعي العام‬\n      ‫بخصــوص حيازتــه قطعــة احلشــيش املخــدر املذكــورة أعــاه لقصــد‬\n      ‫التعاطــي وتعاطيــه احلشــيش املخــدر وإنــكاره ترويــج احلشــيش املخــدر‬\n      ‫ولــم يثبــت املدعــي العــام ذلــك وإلــى أن محضــر القبــض خــال مــن الركن‬\n      ‫األســاس إلثبــات عمليــة الترويــج وهــي االســتالم والتســليم وإلــى مــا تــدل‬\n      ‫عليــه املــادة التاســعة واخلمســون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫التــي تتضمــن أن احملكمــة ال تتقيــد بالوصــف الــوارد يف الئحــة الدعــوى‬\n      ‫وعليهــا أن تعطــي الفعــل الوصــف الــذي يســتحقه وإلــى مــا تــدل عليــه‬\n      ‫املادتــان الواحــدة واألربعــون والسادســة واخلمســون مــن نظــام مكافحــة‬\n      ‫املخــدرات وإلــى عــدم الســوابق وقلــة الكميــة ومــا تــدل عليــه املــادة‬\n      ‫الســتون مــن نظــام مكافحــة املخــدرات لــكل مــا ســبق فقــد ثبــت لــدي‬\n      ‫إدانــة املدعــى عليــه بحيــازة قطعــة حشــيش مخــدر وزنها خمســة جرامات‬\n      ‫وثمانيــة بالعشــرة مــن اجلــرام لقصــد التعاطــي وتعاطيــه احلشــيش املخــدر‬\n      ‫وبعــده حكمــت مبــا يلــي أو ًال بســجن املدعــى عليــه ملــدة شــهرين اعتبــار ًا‬\n      ‫مــن تاريــخ إيداعــه الســجن تطبيقـ ًا للمــادة الواحــدة واألربعــن مــن نظــام‬\n      ‫مكافحــة املخــدرات ومت النــزول عــن احلــد األدنــى مــن العقوبــة إعمــا ًال‬\n      ‫للمــادة الســتني مــن ذات النظــام ثاني ـ ًا إبعــاده إلــى بــاده بعــد إنهــاء مــا‬\n      ‫لــه ومــا عليــه تطبيقـ ًا للمــادة السادســة واخلمســن مــن ذات النظــام ثالثـ ًا‬\n      ‫بجلــده ثمانــن جلــدة دفعــة واحــدة حــد املســكر يف مــكان عــام رابع ـ ًا‬\n      ‫رددت دعــوى املدعــي العــام بخصــوص تطبيــق املادتــن الثامنــة والثالثــن‬\n\n\n‫‪207‬‬\n\f‫والثالثــة واخلمســن مــن نظــام مكافحــة املخــدرات لعــدم ثبــوت قيــام‬\n‫املوجــب الشــرعي وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫القناعــة واملدعــي العــام عدمهــا وطلــب االســتئناف وأجيــب لطلبــه كمــا‬\n‫قــرر أن الئحتــه االعتراضيــة مــا يف أوراق املعاملــة وأمــرت برفــع كامــل‬\n‫أوراق املعاملــة إلــى محكمــة االســتئناف باملنطقــة الشــرقية وأغلقــت‬\n‫اجللســة يف متــام الســاعة ‪ 10 :55‬وصــل اهلل علــى نبينــا محمــد وعلــى الــه‬\n‫وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة‬\n‫اجلزائيــة مبحافظــة القطيــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم ‪ 34283189‬وتاريخ‬\n‫‪ 1434/06/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341487741‬وتاريــخ‬\n‫‪ 1434/06/19‬ه ـ ففــي يــوم األربعــاء ‪ 1434/08/03‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 08 :30‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية مبوجــب خطابهــم رقــم ‪ 341658512‬وتاريــخ ‪1434/07/30‬ه ـ‬\n‫واملقيــدة لدينــا برقــم ‪ 341658512‬وتاريــخ ‪1434/08/02‬ه ـ وبرفقهــا‬\n‫القــرار الصــادر مــن قضــاة محكمــة االســتئناف الدائــرة اجلزائيــة‬\n‫الثالثيــة األولــى ‪ -‬ج‪ 1/‬رقــم ‪ 34277618‬يف ‪1434/07/24‬ه ـ واملتضمن‬\n‫املصادقــة علــى احلكــم وبــه تعتبــر القضيــة منتهيــة وأغلقــت اجللســة يف‬\n‫متــام الســاعة ‪ 08 :45‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                           ‫وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":202,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"99018e4e721455ec99aff1adb12508a148b77e369fed91abfe86002b4780ccfd","normalized_text_hash":"9eafc6dcc3a1c130c2853ca8888392b2f444b5b7757304dfd37d1b2c8217999d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p202-34252509"},{"id":"c93af952-71aa-5d84-8bfb-bc2f830132a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -شراء وحيازة احلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -التستر على مصدر املضبوطات -إقرار املدعى عليه بشراء وحيازة احلشيش املخدر -إنكار املدعى عليه التستر على مصدر املضبوطات -إقامة حد املسكر -تعزير املدعى عليه بالسجن واإلبعاد عن الباد.","document_number":"34267356","case_number":"34311511","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/12","year":"1434","subject":"مخدرات -شراء وحيازة احلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -التستر على مصدر املضبوطات -إقرار املدعى عليه بشراء وحيازة احلشيش املخدر -إنكار املدعى عليه التستر على مصدر املضبوطات -إقامة حد املسكر -تعزير املدعى عليه بالسجن واإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34267356 :‬تاريخه ‪1434/7/12:‬هـ‬\n                         ‫رقم القضية‪34311511 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34290705‬تاريخه‪1434/08/08 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬شــراء وحيــازة احلشــيش املخــدر بقصــد التعاطــي ‪ -‬تعاطــي‬\n      ‫احلشــيش املخــدر ‪ -‬التســتر علــى مصــدر املضبوطــات ‪ -‬إقــرار املدعــى‬\n      ‫عليــه بشــراء وحيــازة احلشــيش املخــدر ‪ -‬إنــكار املدعــى عليــه التســتر‬\n      ‫علــى مصــدر املضبوطــات ‪ -‬إقامــة حــد املســكر ‪ -‬تعزيــر املدعــى عليــه‬\n                                                  ‫بالســجن واإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                 ‫‪ -1‬قوله تعالى( وال تقتلوا النفس التي حرم اهلل إال باحلق)‪.‬‬\n                       ‫‪ -2‬قوله تعالى (وال تفسدوا يف األرض بعد صالحها )‪.‬‬\n                   ‫‪ -3‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n      ‫‪ -4‬املــادة ‪ 56‬الفقــرة الثانيــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                       ‫العقليــة‪.‬‬\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليــه مقيــم بشــراء وحيــازة احلشــيش املخدر‬\n      ‫بقصــد التعاطــي‪ ،‬تعاطيــه احلشــيش املخــدر‪ ،‬التســتر علــى مصــدر‬\n      ‫املضبوطــات‪ ،‬وطلــب املدعــي العــام إثبــات مــا اســند إليــه واحلكــم عليــه‬\n      ‫بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬و إبعــاده عن اململكة‬\n      ‫بعــد تنفيــذ احملكوميــة و بعقوبــة تعزيريــة لقــاء تســتره علــى مصــدر‬\n\n‫‪209‬‬\n\f‫املخــدرات‪ ،‬مت القبــض علــى املدعــى عليــه بعــد اســتيقافه و تفتيشــه‬\n‫بعــد االشــتباه بــه مــن قبــل ســلطات األمــن و بتفتيشــه ضبــط كميــة مــن‬\n‫احلشــيش املخــدر‪ ،‬إقــرار املدعــى عليــه بشــراء وحيــازة احلشــيش املخــدر‬\n‫بقصــد التعاطــي‪ ،‬إقــرار املدعــى عليــه بتعاطــي احلشــيش املخــدر‪،‬‬\n‫إنــكار املدعــى عليــه التســتر علــى مصــدر املضبوطــات‪ ،‬عــدم وجــود‬\n‫بينــة للمدعــي العــام علــى مــا أنكــره املدعــى عليــه ســوى مــا جــاء يف‬\n‫أوراق املعاملــة‪ ،‬إقامــة حــد املســكر علــى املدعــى عليــه‪ ،‬تعزيــر املدعــى‬\n‫عليــه بالســجن واإلبعــاد فيمــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة‪،‬‬\n‫عــدم ثبــوت إدانــة املدعــى عليــه بالتســتر علــى مصــدر املضبوطــات‪،‬‬\n                               ‫تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة‬\n                  ‫أنــا ‪ ............‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫الــواردة إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ‪ 10097‬وتاريــخ ‪1434/7/4‬ه ـ واملقيــدة بهــذه احملكمــة برقــم‬\n‫‪ 341630165‬وتاريــخ ‪1434/7/5‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيــس‬\n‫برقــم ‪ 34311511‬وتاريــخ ‪1434/7/5‬ه ـ فتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام ‪ ............‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب‬\n‫خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n‫األحســاء ذي الرقــم ‪ ............‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه‬\n‫ا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لدائــرة التحقيــق‬      ‫قائ ـ ً‬\n‫واالدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪ ............‬مصــري‬\n\n                                                                                          ‫‪210‬‬\n\f      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ............‬العمــر ‪ 33‬عام ـ ًا احلالــة‬\n      ‫االجتماعيــة متــزوج باالطــاع علــى محضــر القبــض رقــم (‪ )............‬املعــد‬\n      ‫مــن قبــل أمــن الطــرق التابــع ملركــز الدهنــاء تبــن أنــه مت اســتيقاف‬\n      ‫املدعــى عليــه حيــث كان يقــود ســيارة مــن نــوع بيجــو (‪2007‬م) حتمــل‬\n      ‫اللوحــة (‪ )............‬اللــون (أســود) وبتفتيشــه وتفتيــش املركبــة ضبــط‬\n      ‫علــى عــدد (‪ )6‬ســتة قطــع ســوداء اللــون تــزن جميعهــا (‪ )32.5‬اثنــن‬\n      ‫وثالثــن جــرام وخمســة مــن العشــرة مــن اجلــرام كانــت موجــودة بداخــل‬\n      ‫جــوارب كانــت موضوعــه بداخلــه حــذاء موضــع علــى املقعــدة اخللفيــة‬\n      ‫بالســيارة ‪ .‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪)............‬‬\n      ‫إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر واملــدرج يف اجلــدول رقــم‬\n      ‫(‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه أقــر بشــراء وحيــازة احلشــيش املخــدر بقصــد‬\n      ‫التعاطــي وتعاطيــه لنوعــه وأنــه اشــتراها مــن شــخص يف الريــاض بقيمــة‬\n      ‫‪ 500‬ريــال ‪ .‬وانتهــى التحقيــق معــه علــى توجيــه االتهــام لــه بشــراء‬\n      ‫وحيــازة عــدد (‪ )6‬ســتة قطــع مــن احلشــيش املخــدر تــزن جميعهــا (‪)32.5‬‬\n      ‫اثنــن وثالثــن جــرام وخمســة مــن العشــرة مــن اجلــرام بقصــد التعاطــي‬\n      ‫وتعاطيــه لنوعــه ‪ ،‬واملجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (‪ )39‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وتســتره علــى مصــدر‬\n      ‫املضبوطــات التــي معــه وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف‬\n      ‫إقــرار املدعــى عليــه املــدون علــى محضــر االســتجواب املرفــق علــى اللفــة‬\n      ‫رقــم (‪ -2)11/12‬محضــر القبــض والتفتيــش املرفــق علــى اللفــة رقــم‬\n      ‫(‪ -3)4‬محضــر الــوزن والتحريــز املــدون علــى الصفحــة رقــم (‪ )4‬مــن‬\n\n‫‪211‬‬\n\f                  ‫ملــف االســتدالالت األوليــة املرفــق علــى اللفــة رقــم (‪. )8‬‬\n‫‪ -4‬التقريــر الكيمــاوي الشــرعي املرفــق علــى اللفــة رقــم (‪ )16‬وحيــث‬\n‫إن مــا أقــدم عليــه املدعــى عليــه املذكــور ‪ -‬وهــو بكامل أهليتــه املعتبرة‬\n‫نظامــا ؛ لــذا أطلــب إثبــات مــا أســند‬\n                                      ‫ً‬     ‫شــرع ًا ‪ -‬فعــل مجــرم ومعاقــب عليــه‬\n                                                  ‫إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫العقوبــات الــواردة يف نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n            ‫‪ /1-:‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪. )41‬‬\n‫‪ /2‬احلكــم بإبعــاده عــن اململكــة بعــد تنفيــذ محكوميتــه اســتناد ًا‬\n                             ‫للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن ذات النظــام‪.‬‬\n‫العقوبــات التعزيزيــة ‪ /1-:‬احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة‬\n                                          ‫لقــاء تســتره علــى املصــدر املخــدرات‪.‬‬\n‫هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن‬\n‫هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائـاً‪ :‬صحيــح‬\n‫مــا نســبه لــي املدعــي العــام مــن واقعــة القبــض ومــن شــرائي وحيــازة‬\n‫عــدد ســت قطــع مــن احلشــيش املخــدر تــزن جميعهــا(‪ )32.5‬اثنــن‬\n‫وثالثــن جــرام وخمســة مــن العشــرة مــن اجلــرام بقصــد االســتعمال ومــن‬\n‫اســتعمالي للحشــيش املخــدر وصحيــح اعتــرايف ونســبة (الســوابق ) لــي‬\n‫وقــد أخــذت محكوميتهــا وغيــر صحيــح تســتري على مصــدر املخدرات‬\n‫فقــد أخبــرت جهــة التحقيــق أننــي اشــتريتها عــن طريــق صديــق لــي‬\n‫اســمه ‪ ............‬مصــري اجلنســية وهــو الــذي يحضرهــا لــي عــن طريــق‬\n‫أنــاس يعرفهــم هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام هــل لديــه‬\n‫ـدي ســوى مــا يف أوراق‬ ‫بينــة علــى مــا نفــاه املدعــى عليــه فقــال ‪ :‬ليــس لـ َّ‬\n‫املعاملــة وأطلــب الرجــوع إليهــا هكــذا أجــاب فجــرى االطــاع علــى‬\n\n\n                                                                                         ‫‪212‬‬\n\f      ‫جميــع أوراق املعاملــة ومنهــا ‪ :‬التقريــر الكيمــاوي الشــرعي الصــادر مــن‬\n      ‫قســم الكيميــاء الشــرعية باملركــز اإلقليمــي ملراقبــة الســموم التابــع‬\n      ‫للمديريــة العامــة للشــؤون الصحيــة باملنطقــة الشــرقية برقــم ( ‪ 2081‬ك‬\n      ‫ش ) لعــام ‪1434‬ه ـ املتضمــن إيجابيــة عي ــنة مــا ضبــط للحشــيش املخــدر‬\n      ‫كمــا جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه املتضمــن خلــوه‬\n      ‫مــن الســوابق كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه‬\n      ‫املتضمنــة أنــه أوقــف بتاريخ‪1434/04/23‬ه ـ فبنــاء علــى مــا ورد مــن‬\n      ‫الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن‬\n      ‫أهليتــه وملــا ورد يف محضــر القبــض واعتــراف املدعــي عليــه ومبــا أنــه‬\n      ‫صــادق علــى صحــة مــا نســب إليــه مــن حيــازة احلشــيش املخــدر علــى‬\n      ‫صفــة مــا ورد يف الدعــوى ومبــا أن مــا صــدر منــه حــرام يف الشــريعة ملــا‬\n      ‫يف احلشــيش املخــدر مــن اخلطــر و الضــرر علــى البــاد والعبــاد وعلــى‬\n      ‫مــن صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي حــرم اهلل إال‬\n      ‫باحلــق) وقــال (وال تفســدوا يف األرض بعــد إصالحهــا ) ممــا يســتوجب‬\n      ‫معاقبــة املدعــى عليــه و تعزيــزه بالعقوبــة الــواردة يف املــادة الواحــدة‬\n      ‫واألربعــن مــن نظــام مكافحــة املخــدرات كمــا يتوجــه اســتحقاقه‬\n      ‫للعقوبــة الــواردة يف املــادة السادســة واخلمســن الفقــرة الثانيــة منهــا ومبــا‬\n      ‫أن املدعــى عليــه أقـ َّـر باســتعمال احلشــيش املخــدر واســتعماله يأخــذ‬       ‫َّ‬\n      ‫حكــم املســكر للتوافــق بينهمــا يف منــاط احلكــم وحــد املســكر أن‬\n      ‫يجلــد صاحبــه ثمانــن جلــدة علنــا كمــا اســتقر عليــه عمــل األمــة ممــا‬\n      ‫يتوجــب حــد املدعــى عليــه حــد املســكر الســتعماله للحشــيش املخــدر‬\n      ‫أن املدعــى عليــه أنكــر دعــوى املدعــي العــام باتهامــه بالتســتر علــى‬‫ومبــا َّ‬\n      ‫مصــدر املخــدرات وال بينــة للمدعــي العــام علــى ذلــك ممــا يســتوجب ر َّد‬\n\n\n‫‪213‬‬\n\f‫دعــوى املدعــي العــام بإثبــات إدانــة املدعــى عليــه بذلــك لــذا كلــه وألجــل‬\n‫ـدي إدانــة‬‫احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي ‪ :‬أو ًال ‪ /‬ثبــت لـ َّ‬\n‫املدعــى عليــه باســتعمال احلشــيش املخــدر ويجلــد حــد املســكر ثمانــن‬\n‫جلــدة دفعــة واحــدة علنـ ًا ‪ .‬ثانيـ ًا ‪ /‬ثبــت لــدي إدانــة املدعــى عليــه بشــراء‬\n‫وحيــازة عــدد ســت قطــع مــن احلشــيش املخــدر تــزن جميعهــا(‪ )32.5‬اثنني‬\n‫وثالثــن جــرام وخمســة مــن العشــرة مــن اجلــرام بقصــد االســتعمال وأن‬\n‫يعــزر بســجنه ملــدة ســنة مــن تاريــخ توقيفــه علــى ذمــة القضيــة وذلــك‬\n‫مبوجــب املــادة الواحــدة و األربعــن مــن نظــام مكافحــة املخــدرات‪.‬‬\n‫ثالثــا ‪ /‬وأن يبعــد عــن اململكــة بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه‬\n‫واســتيفاء مــا لــه ومــا عليــه مــن حقــوق وال يســمح لــه بالعــودة إليهــا فيمــا‬\n‫عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة حســب مقتضــى مــا ورد يف‬\n‫املــادة السادســة واخلمســن مــن النظــام نفســه الفقــرة الثانيــة‪ .‬رابعـ ًا ‪ /‬لــم‬\n‫ـدي إدانــة املدعــى عليــه بالتســتر علــى مصــدر املخــدرات وقــررت‬       ‫يثبــت لـ َّ‬\n‫ر َّد دعــوى املدعــي العــام بإثبــات إدانتــه بذلــك وبتــاوة احلكــم علــى‬\n‫الطرفــن وإفهــام املدعــى عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم‬\n‫وطلــب املدعــي العــام رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة‬\n‫هــي الئحــة الدعــوى هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن‬\n‫ذلــك حرمــة اســتعمال احلشــيش املخــدر وأثــره الســيئ علــى العقــل واملــال‬\n‫وأقفلــت اجللســة العاشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد‬\n       ‫وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف ‪1434/07/12‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n\n\n                                                                                           ‫‪214‬‬\n\f      ‫برقــم ‪ 341630165‬وتاريــخ ‪1434/7/19‬ه ـ املقيــدة لــدى احملكمــة‬\n      ‫برقــم ‪ 34/1787376‬وتاريــخ ‪1434/7/24‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ............‬املســجل برقــم‬\n      ‫‪ 34267356‬وتاريــخ ‪1434/7/12‬ه ـ اخلــاص بدعــوى‪ /‬املدعــي العــام‬\n      ‫ضــد‪ ............/‬الســيد ‪ ....‬مصــري اجلنســية يف قضيــة مخــدرات وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                    ‫‪1434/8/7‬ه ـ ‪.‬‬\n\n\n\n\n‫‪215‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":209,"source_page_end":215,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d20f0fb040286783c21eef5df65d6433a026eb2e8e0d5e22e5de97bb1cf18bd","normalized_text_hash":"25676b725770d4763aa064915483ff5b1225d2fc98aa4ee23f56140fb778e2e2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p209-34267356"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"f66f04d9-0ca3-51ae-b906-752719ce02f4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج ومحاولة إدخالها إلى السجن -بينة غير موصلة -مقاومة رجال األمن - عدم ثبوت الدعوى.","document_number":"34375086","case_number":"34224886","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف التصديق على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/15","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج ومحاولة إدخالها إلى السجن -بينة غير موصلة -مقاومة رجال األمن - عدم ثبوت الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34375086:‬تاريخه‪1434/05/15 :‬هـ‬\n                          ‫رقم الدعوى‪34224886:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 35127293‬تاريخه‪1435/1/25:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصد الترويــج ومحاولة‬\n       ‫إدخالهــا إلــى الســجن ‪ -‬بينــة غيــر موصلــة ‪ -‬مقاومــة رجــال األمــن ‪-‬‬\n                                                           ‫عــدم ثبــوت الدعــوى‪.‬‬\n\n\n\n\n       ‫ـك َما‬     ‫يحـ ِ‬ ‫ـك َوأ َْط َيـ َـب ِر َ‬        ‫(مــا أ َْط َي َبـ ِ‬\n                                                                         ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪َ :‬‬\n       ‫ل ْر َمـ ُة ْالُ ْؤمِ ـ ِـن‬ ‫ـس ُم َح َّمــدٍ ِب َيــدِ ِه َ ُ‬   ‫ـك َوا َّلــذِ ي َن ْفـ ُ‬‫ـك َوأَعْ َظـ َـم ُح ْر َم َتـ ِ‬   ‫أَعْ َظ َمـ ِ‬\n                                                                                                                      ‫أَعْ َظـ ُـم عِ ْنـ َـد َّ ِ‬\n                                                                                              ‫الل ُح ْر َمـ ًة مِ ْنـ ِ‬\n                       ‫ـك َما ِلـ ِه َو َدمِ ـ ِه َوأ َْن َن ُظـ َّـن ِبـ ِه ِإ َّل َخ ْيـ ًـرا)‬\n                                                                                                                    ‫‪ -2‬الضرر يزال‪.‬‬\n                                                    ‫‪ -3‬املواد (‪ )22‬و(‪ )65‬من نظام املرافعات الشرعية‪.‬‬\n                                                             ‫‪ -4‬املادة (‪ )221‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n       ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n       ‫بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة بقصــد الترويــج ومحاولــة‬\n       ‫إدخالهــا إلــى الســجن ‪ ،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n       ‫واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n       ‫و بعقوبــة الســجن طبقــا لنظــام الســجن والتوقيــف وبعقوبــة تعزيريــة‬\n       ‫ملقاومــة رجــل األمــن‪ ،‬مت القبــض عليــه وهــو يحــاول إدخــال كيــس بــه‬\n\n‫‪175‬‬\n\f‫قطعــة مــن احلشــيش وعــدد مــن احلبــوب احملظــورة حتت شــبك أحــد عنابر‬\n‫الســجن‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n‫للحشــيش املخــدر واإلمفيتامــن‪ ،‬أنكــر أمــام احملكمــة مــا أســنده إليه‬\n‫املدعــي العــام‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه وقــررت‬\n‫ســماع شــهادة الشــهود فلــم جتــد فيهــا مــا يثبــت دعواه‪،‬قضــت احملكمــة‬\n‫بعــدم إدانــة املدعــى عليــه مبــا نســب إليــه يف الدعــوى وأخلــت ســبيله‬\n‫منهــا‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت‬\n                              ‫محكمــة االســتئناف التصديــق علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 34224886‬وتاريــخ‬\n‫‪1434/05/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341186809‬وتاريــخ‬\n‫‪ 1434/05/14‬ه ـ ففــي يــوم األحــد املوافق‪1434/06/18‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 :45‬صباح ـ ًا وفيهــا حضــر املدعــي العــام ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬والتكليــف رقــم‬\n‫‪ 24‬يف ‪1432/01/16‬ه ـ وتقــدم بالئحــة دعــواه ضــد‪ 26 ....... ،‬عام ـاً‪،‬‬\n‫‪ .......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ ،).....‬املهنــة ‪.......‬‬\n‫موظــف أهلــي‪ ،‬متعلــم‪ ،‬موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب‬\n‫أمــر متديــد التوقيــف رقــم ( ه ـ م‪ )8966/5/2‬وتاريــخ ‪1434/2/6‬ه ـ ‪،‬‬\n‫اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي على‬\n‫املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬انــه بتاريــخ ‪1434/1/10‬ه ـ‬\n\n                                                                                       ‫‪176‬‬\n\f      ‫وأثنــاء زيــارة نــزالء الســجن وصلــت إخباريــة مــن احــد الــزوار ألحــد‬\n      ‫حــراس الســجن بأنــه يوجــد يف شــبك الزيــارة التابــع بعنبــر (‪ )4‬شــخص‬\n      ‫يحــاول إدخــال ممنوعــات عــن طريــق الشــبك وبــدوره ابلــغ ضابــط خفــر‬\n      ‫فتــم القبــض عليــه مــن قبــل إفــراد احلراســات وبيــده كيــس مربــع‬\n      ‫الشــكل بيــده اليمنــى يوجــد بداخلــه مــادة ســوداء اللــون بلــغ وزنهــا‬\n      ‫(‪43,5‬جــم) مــن احلشــيش املخــدر وعــدد (‪ )12‬حبــة مــن احلبــوب املؤثــرة‬\n      ‫عقلي ـ ًا يحــاول إدخالهــا مــن حتــت الشــبك عــن طريــق ســلك معدنــي‬\n      ‫وعنــد محاولــه القبــض عليــه قــاوم ورمــى الكيــس باجتــاه الشــبك‪ .‬وقــد‬\n      ‫اثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/165‬ك ش م) لعــام ‪1434‬ه ـ‬\n      ‫إيجابيــة العينتــن مــن الكميتــن املضبوطــة واملرســلة للتحليــل علــى مادة‬\n      ‫اإلمفيتامــن املؤثــرة عقلي ـ ًا واحلشــيش املخــدر واملدرجــة باجلــدول رقــم‬\n      ‫(‪ )2‬فئــة (ب) وامللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n      ‫باســتجواب املدعــى عليــه أفــاد إنــه كان يف زيــارة ألخيــه بعنبــر (‪)4‬‬\n      ‫بالســجن العــام بجــدة وأثنــاء الزيــارة حضــر رجــل األمــن واتهمــه بحيــازة‬\n      ‫ممنوعــات وأن رجــل األمــن اآلخــر قــام بالتفتيــش أســفل شــبك الزيــارة‬\n      ‫ووجــد كيــس نايلــون يحتــوي علــى حبــوب وحشــيش وســلمها لرجــل‬\n      ‫األمــن الــذي قــام بتفتيشــه والقبــض عليــه‪ .‬وبســماع أقــوال الشــهود أفــاد‬\n      ‫املواطــن (‪ ).....‬أنــه كان متواجــد ًا بالســجن العــام لزيــارة أخيــه بعنبــر‬\n      ‫(‪ )4‬وأثنــاء ذلــك شــاهد رجــل األمــن يصــرخ ثــم امســك باملدعــى عليــه‬\n      ‫مــن كتفــه وفتشــه وفتــش جــواره ولــم يجــد شــيء مــن املمنوعــات ثــم‬\n      ‫أحضــر رجــل األمــن الثانــي املتواجــد بــن الشــبكني كيــس نايلــون‬\n      ‫شــفاف ال يعلــم مــا بداخلــه‪ .‬وبســماع أقــوال الشــاهد الثانــي املواطــن‬\n      ‫(‪ ).....‬شــهد انــه كان متواجــد ًا بالســجن العــام لزيــارة أخيــه بعنبــر‬\n\n\n‫‪177‬‬\n\f‫(‪ )4‬وأثنــاء ذلــك شــاهد رجــل األمــن يصــرخ ثــم أمســك املدعــى عليــه‬\n‫ولــم يجــد معــه شــيء مــن املمنوعــات ولــم يشــاهد رجــل االمــن الثانــي‬\n‫عندمــا وجــد كيــس نايلــون بــن الشــبكني ‪ ،‬وأضــاف ان رجــل االمــن‬\n‫الثانــي لــم يقــم مــن علــى كرســيه لكونــه خــرج مــن موقــع الزيــارة حــن‬\n‫محاولــة رجــل األمــن األول القبــض علــى املدعــى عليــه‪ .‬وبســماع أقــوال‬\n‫رجــل األمــن (‪ ).....‬أفــاد انــه أثنــاء عملــه بالســجن اخبــره احــد الــزوار‬\n‫أن املدعــى عليــه يحــاول إدخــال ممنوعــات إلــى الســجن فاخبــر ضابــط‬\n‫العنبــر وكلفــه بالذهــاب إلــى عنبــر (‪ )4‬فشــاهد املدعــى عليــه وبيــده‬\n‫اليمنــى كيــس نايلــون يحــاول إدخالــه مــن أســفل الشــبك عــن طريــق‬\n‫ســلك معدنــي ممــدود مــن داخــل العنبــر وعنــد القبــض عليــه قــام املدعــى‬\n‫عليــه مبقاومــة عنيفــة ورمــى مــا بيــده باجتــاه الشــبك فبحــث عنــه ولــم‬\n‫يجــده وســمع أثنــاء القبــض عليــه الســجناء يقولــون لــه ارميــه وبحــث عنــه‬\n‫ولــم يجــده ثــم ذهــب رجــل األمــن اآلخــر إلــى مــا بــن الشــبكني فاحضــر‬\n‫الكيــس وســلمه لــه‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام إلــى‬\n‫املدعــى عليــه بحيــازة (‪ )43,5‬ثالثــة وأربعــن جرام ـ ًا مــن مــادة احلشــيش‬\n‫املخــدر وعــدد (‪ )12‬حبــه مــن حبــوب اإلمفيتامــن املؤثــرة عقليـ ًا بقصــد‬\n‫الترويــج اســتناد ًا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ومحاولــة إدخالهــا إلــى الســجن العــام وفــق‬\n‫الفقــرة (‪ )2‬مــن املــادة (‪ )29‬مــن نظــام الســجن ودور التوقيــف‪ .‬وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪-1 -:‬مــا جــاء بشــهادة الشــهود املنــوه عنهــا لفــه‬\n‫ا املرفــق لفــه‬\n               ‫(‪-2 .)21-20‬مــا ورد مبحضــر القبــض املنــوه عنــه تفصي ـ ً‬\n‫ا املرفــق لفــه (‪.)2‬‬  ‫(‪-3 .)1‬مــا ورد مبحضــر التحريــز املنــوه عنــه تفصي ـ ً‬\n‫‪-4‬مــا ورد بالتقريــر الكيميائــي املنــوه عنــه املرفــق لفــه (‪ .)22‬وباالطــاع‬\n\n\n                                                                                       ‫‪178‬‬\n\f      ‫علــى ســوابقه عثــر لــه علــى ســابقة دخــول مدرســة‪ .‬وحيــث ان مــا أقــدم‬\n      ‫عليــه املدعــى عليــه مــن األفعــال احملرمــة شــرع ًا واحملرمــة نظامـ ًا طبقـ ًا‬\n      ‫للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثرات العقليــة الصادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ والقفــرة (‪ )2‬مــن‬\n      ‫املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف الصــادر باملرســوم امللكــي‬\n      ‫رقــم (م‪ )31/‬وتاريــخ ‪1398/6/21‬ه ـ ‪ ،‬لــذا اطلــب إثبــات مــا اســند‬\n      ‫إليــه واحلكــم عليــه مبعاقبتــه بالعقوبــات األصليــة والتكميليــة التاليــة‪:‬‬\n      ‫‪-1‬بالســجن لقــاء مــا اســند إليــه اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪)38‬‬\n      ‫مــن نظــام مكافحــة املخــدرات والفقــرة (‪ )2‬مــن املــادة (‪ )29‬مــن نظــام‬\n      ‫بالســجن والتوقيــف املشــار إليهمــا مــع اجللــد والغرامــة اســتناد ًا لــذات‬\n      ‫الفقــرة (‪ )1‬املــادة (‪ )38‬املشــار لهــا ‪ ،‬وتشــديد العقوبــة عليــه اســتناد ًا‬\n      ‫للفقــرة (‪ )2‬احلالــة (ب) مــن ذات املــادة (‪ )38‬مــن نظــام املخــدرات أعــاه‪.‬‬\n      ‫‪-2‬منعــه مــن الســفر إلــى خــارج اململكــة ‪ ،‬وذلــك بعــد انتهــاء تنفيــذ‬\n      ‫العقوبــة اســتناد ًا الفقرتــن (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة‬\n      ‫املخــدرات املشــار إليــه‪ .‬كمــا اطلــب بتعزيــره لقــاء املقاومــة لرجــل األمــن‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه أجــاب بقولــه ما ذكــره املدعي العام‬\n      ‫مــن أننــي حــزت احلشــيش املخــدر واحلبــوب املؤثــرة علــى العقــل بقصــد‬\n      ‫الترويــج وحاولــت إدخالهــا إلــى الســجن فغيــر صحيــح ومــا ذكــره مــن‬\n      ‫أننــي قاومــت حينمــا أرادوا تفتيشــي والقبــض علــي فغيــر صحيــح وعلــي‬\n      ‫الســابقة التــي ذكــر هكــذا أجــاب إثــر هــذا طلبــت مــن املدعــي العــام‬\n      ‫بينتــه طبــق دعــواه فاســتمهل فامهــل عليــه رفعــت اجللســة يف متــام الســاعة‬\n      ‫احلاديــة عشــرة صباحــا إلــى يــوم االثنــن املوافــق ‪1434/06/26‬ه ـ‬\n      ‫الســاعة التاســعة والربــع صباحــا وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n‫‪179‬‬\n\f‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/06/18‬ه ـ احلمــد هلل‬\n‫وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة مبحافظــة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة برقــم ‪ 34224886‬وتاريــخ ‪ 1434/05/15‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341186809‬وتاريــخ ‪ 1434/05/14‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافــق‪ 1434/06/27‬ه ـ افتتحت اجللســة الســاعة العاشــرة‬\n‫والربــع صباحــا وفيهــا حضــر ‪ .......‬ســعودي اجلنســية حامــل بطاقــة أحوال‬\n‫ذات الرقــم (‪ ).....‬و (‪ ).....‬ســعودي اجلنســية حامــل بطاقــة ذات الســجل‬\n‫املدنــي رقــم (‪ ).....‬وطلبــا اإلذن للشــهادة فأذنــت لهمــا فقــال كل واحــد‬\n‫منهمــا مبفــرده أشــهد هلل العظيــم أنــه ال عالقــة تربطنــي باملدعــى عليــه‬\n‫وأننــي كنــت يــوم القبــض علــى املدعــى عليــه يف الســجن زائــرا ورأيــت‬\n‫املدعــى عليــه يتهــم بحيازتــه ملخــدرات مــن قبــل العســكري الــذي يتجول‬\n‫علــى الســجناء بــدون مقدمــات توجــه إلــى املدعــى عليــه وقــال إنــك تدخــل‬\n‫مخــدرات وأخــذه إلــى الداخــل وزاد األول (‪ ).....‬وابلــغ مــن العمــر اثنــن‬\n‫وثالثــن ســنة وقــد كنــت زائــرا لصديــق لــي وزاد الثانــي وابلــغ مــن العمــر‬\n‫ســبعة وعشــرين ســنة وقــد كنــت بجــوار الزائــر للمدعــى عليــه ولــم أرى‬\n‫منه ما يريب فلم اره يســقط شــيئا أو يخفي شــيئا بل اســتنكرت اتهامه‬\n‫يف ذلــك هكــذا شــهد كل واحــد منهمــا مبفــرده إثــر هــذا أكــدت‬\n‫علــى املدعــي العــام إحضــار مزيــد بينــة و رفعــت اجللســة يف متــام الســاعة‬\n‫العاشــرة والنصــف صباحــا إلــى يــوم األربعــاء املوافــق ‪14340705‬ه ـ‬\n‫الســاعة التاســعة والربــع صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n\n\n                                                                                     ‫‪180‬‬\n\f      ‫مبحافظــة جــدة ففــي يــوم األحــد املوافــق‪ 1434/12/01‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة الثانيــة عشــرة ظهــرا وفيهــا حضــر الطرفــان فســألت‬\n      ‫املدعــي العــام عمــا رفعــت اجللســة الســابقة ألجلــه فأجــاب مقــرر ًا بينتــي‬\n      ‫هــي شــهادة رجــال الضبــط والتحريــز وقــد طلبتهــم للشــهادة عــدة مــرات‬\n      ‫ولــم ميتثلــوا هكــذا أجــاب إثــر هــذا رجعــت إلــى مــا جعلــه أدلــة لــه يف‬\n      ‫األوراق فاطلعــت علــى محضــر القبــض وتضمــن أنــه بنــاء علــى إخباريــة‬\n      ‫أحــد زوار الســجن بــأن زائــر ًا يحــاول إدخــال ممنوعــات للســجن جــرى‬\n      ‫ضبــط املدعــى عليــه وبيــده كيــس يحــوي مــادة ســوداء اللــون وهــو يزمــع‬\n      ‫إدخالــه مــن حتــت الشــبك عــن طريــق ســلك معدنــي وقــاوم أثنــاء القبــض‬\n      ‫عليــه ورمــى الكيــس كمــا اطلعــت علــى محضــر التحريــر لفــة رقــم‪2‬‬\n      ‫وتضمــن حتريــز املضبــوط مــع املدعــى عليــه وهــو مــادة الســوداء يشــتبه‬\n      ‫أن تكــون حشيش ـ ًا مخــدر ًا وبلــغ وزنهــا ثالثــة وأربعــون جرام ـ ًا ونصــف‬\n      ‫اجلــرام واثنــا عشــر حبــة يشــتبه أن تكــون حبوبـ ًا محظــورة كمــا اطلعــت‬\n      ‫علــى شــهادة الشــهود احملــررة يف ملــف التحقيــق لفــة رقــم‪ 30‬ولــم تــزد‬\n      ‫عمــا ذكــروه يف شــهادتهم يف اجللســة الســابقة فبنــاء علــى مــا تقــدم‬     ‫ّ‬\n      ‫مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه مــا اتهــم بــه وملــا ورد يف‬\n      ‫نظــام اإلجــراءات اجلزائيــة يف مادتــه الواحــدة والعشــرين بعــد املائتــن‬\n      ‫مــن أنــه تطبــق األحــكام الــواردة يف نظــام املرافعــات الشــرعية فيمــا‬\n      ‫لــم يــرد لــه حكــم يف نظــام اإلجــراءات اجلزائيــة وفيمــا ال يتعــارض مــع‬\n      ‫طبيعــة الدعــوى اجلنائيــة وملــا ورد يف نظــام املرافعــات الشــرعية يف مادتــه‬\n      ‫عمــا دفــع بــه‬\n                    ‫اخلامســة والســتني مــن جــواز إمهــال أحــد الطرفــن للجــواب ّ‬\n      ‫الطــرف اآلخــر وجــواز تكــرار املهلــة لعــذر شــرعي ويف مادتــه الثانيــة‬\n      ‫والعشــرين مــن اعتبــار مــن لــم يحضــر شــهوده عاجــز ًا بعــد تكــرار املهلــة‬\n\n\n‫‪181‬‬\n\f‫لــه وأن للمحكمــة حينئــذ الفصــل يف الدعــوى‪ ،‬وملــا ســبق مــن إقــرار‬\n‫املدعــي العــام بتغيــب شــهوده علــى طلبهــم مــرات عــدة وألن الضــرر يــزال‬\n‫وبقــاء الســجني دون حكــم ضــرر بـ ّـن وألن مــا يف األوراق ال يقــوم بينــة‬\n‫علــى مــا اتهــم بــه املدعــى عليــه وملــا شــهد بــه الشــهود مــن أنهــم لــم يــروا‬\n‫حســن‬   ‫شــيئ ًا وألن األصــل يف املســلم الســامة وال يظــن بــه إال خيــر ًا فقــد ّ‬\n                    ‫األلبانــي مــا رواه ابــن ماجــه والبيهقــي وغيرهمــا عــن َع ْبـ ُـد َّ ِ‬\n‫الل ْبـ ُـن ُع َمـ َـر‬\n‫ك ْع َب ـ ِة َو َي ُقــولُ ‪:‬‬‫ـوف ِبا ْل َ‬                                     ‫الل َص َّلــى َّ ُ‬\n                                         ‫الل َع َل ْي ـ ِه َو َسـل ََّم َي ُطـ ُ‬                   ‫قَ ــالَ َر َأ ْيـ ُـت َر ُســولَ َّ ِ‬\n‫ـس‬  ‫يحـ ِـك َمــا َأ ْع َظ َمـ ِـك َو َأ ْع َظـ َـم ُح ْر َم َتـ ِـك َوا َّلــذِ ي ن َْفـ ُ‬ ‫«مــا َأ ْط َي َبـ ِـك َو َأ ْط َيـ َـب ِر َ‬     ‫َ‬\n                                                         ‫ُم َح َّمــدٍ ِب َيــدِ ِه َل ُْر َمـ ُة ْال ُْؤمِ ـ ِـن َأ ْع َظـ ُـم عِ ْنـ َـد َّ ِ‬\n ‫الل ُح ْر َمـ ًة مِ ْنـ ِـك َما ِلـ ِه َو َدمِ ـ ِه َوأَنْ‬\n‫ن َُظـ َّـن ِب ـ ِه ِإ َّل َخ ْيـ ًـرا»‪ ،‬لــذا كلــه فلــم تثبــت لــدي إدانــة املدعــى عليــه مبــا‬\n‫نســب إليــه يف الدعــوى وأخليــت ســبيله منهــا وبذلــك حكمــت و وأعلنــت‬\n‫ذلــك يف متــام الســاعة الثانيــة عشــرة والربــع ظهــرا فقنــع بــه واعتــرض‬\n‫املدعــي العــام فأجبتــه لذلــك وجعلــت لــه يــوم غــد موعــد ًا الســتالم نســخة‬\n‫احلكــم وتقــدمي اعتراضــه عليــه يف مــدة أقصاهــا شــهر فــإن مضــت املــدة‬\n‫اكتســب احلكــم القطعيــة بقــوة النظــام فــأدرك ذلــك وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                                                       ‫‪ 1434/12/01‬ه ـ ‪.‬‬\n‫احلمــد اهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة برقــم ‪ 341186809‬وتاريــخ‬\n‫‪1435/1/16‬ه ـ املرفــق بهــا القــرار القضائــي رقــم ‪ 34375086‬وتاريــخ‬\n‫‪1434/12/1‬ه ـ الصــادر مــن فضيلــة الشــيخ (‪ )....‬القاضــي باحملكمــة‬\n\n\n                                                                                                                                                  ‫‪182‬‬\n\f      ‫اجلزائيــة بجــدة ‪ ،‬املتضمــن دعــوى املدعــى العــام ضــد (‪ )....‬املتهــم بحيــازة‬\n      ‫احلشــيش املخــدر واحلبــوب احملظــورة بقصــد الترويــج احملكــوم فيــه مبــا‬\n      ‫دون باطنــه وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫قررنــا املوافقــة علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                   ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪183‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":175,"source_page_end":183,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cadf8a01b93a83c06d97dd4ff047d57e5e71c898d2a10dbebd6cc076d492aafc","normalized_text_hash":"5cad1b401601b7bed63cdda7c43dc33550e21147955f7eb4f3c3433fde10960e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p175-34375086"},{"id":"a0d32998-d05b-50cb-9b01-1c83221236e2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -دفع غير مقبول -إدانة باحليازة املجردة عن القصد -حد املسكر -تعزير بالسجن واجللد والغرامة واإلبعاد .","document_number":"34227223","case_number":"34242690","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/26","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -دفع غير مقبول -إدانة باحليازة املجردة عن القصد -حد املسكر -تعزير بالسجن واجللد والغرامة واإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34227223:‬تاريخه‪1434/05/26 :‬هـ‬\n                    ‫رقم الدعوى‪34242690:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34282924‬تاريخه‪1434/7/30:‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬دفــع غيــر‬\n ‫مقبــول‪ -‬إدانــة باحليــازة املجــردة عــن القصــد ‪ -‬حــد املســكر ‪ -‬تعزيــر‬\n                                ‫بالســجن واجللــد والغرامــة واإلبعــاد ‪.‬‬\n\n\n\n\n ‫املــواد (‪ )39‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                          ‫العقليــة‪.‬‬\n\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n ‫بحيــازة احلشــيش املخــدر بقصــد االســتعمال وتعاطيه لــه ‪ ،‬واحلكم عليه‬\n ‫بعقوبــة الســجن واإلبعــاد عــن البــاد طبقــا لنظــام مكافحــة املخــدرات‬\n ‫واملؤثــرات العقليــة‪ ،‬مت تفتيشــه شــخصي ًا فعثــر داخــل جيــب قميصــه‬\n ‫األمامــي علــى قطعــة يشــتبه أن تكــون مــن احلشــيش‪ ،‬أثبــت التقريــر‬\n ‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر‪ ،‬أقــر‬\n ‫أمــام احملكمــة بتعاطــي احلشــيش وحيازتــه وأنكــر مــا أســنده إليــه‬\n ‫املدعــي العــام مــن حيازتــه بقصــد التعاطــي ودفــع بأنــه ال يعلــم عــن‬\n ‫وجودهــا يف جيبــه‪ ،‬قضــت احملكمــة بإدانتــه بتعاطــي احلشــيش املخــدر‬\n ‫وبحيازتــه حيــازة مجــردة وقــررت جلــده حــد املســكر ثمانــون جلــد ًة‬\n\n                                                                                ‫‪184‬‬\n\f      ‫علنـ ًا دفعــة واحــدة وســجنه ملــدة ســتة أشــهر وجلــده مائــة وخمســن جلــدة‬\n      ‫مفرقــة وتغرميــه مبلــغ ثالثــة آالف ريــال وإبعــاده عــن البــاد بعــد انتهــاء‬\n      ‫محكوميتــه‪ ،‬عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‪،‬‬\n                          ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق ‪1434/5/28‬ه ـ لــدي‬\n      ‫أنــا ‪ .......‬رئيــس احملكمــة اجلزائيــة بالدمــام وبنــاء علــى املعاملــة الــواردة‬\n      ‫إلينــا مــن هيئــة التحقيــق واالدعــاء العــام باملنطقــة الشــرقية برقــم‬\n      ‫‪ 27194‬وتاريــخ ‪1434/5/26‬ه ـ واملقيــدة لدينــا برقــم ‪341281228‬‬\n      ‫وتاريــخ ‪1434/5/26‬ه ـ واحملالــة لنــا برقــم ‪ 34242690‬وتاريــخ‬\n      ‫ا فيهــا ادعــي علــى‬ ‫‪1434/5/26‬ه ـ عليــه قــدم املدعــي العــام دعــواه قائـ ً‬\n      ‫‪ .......‬بنجالديشــي اجلنســية مبوجب رخصة اإلقامة رقم ‪ .......‬وباالطالع‬\n      ‫علــى محضــر القبــض املعــد مــن قبــل مركــز أمــن طــرق صالصــل بتاريخ‬\n      ‫‪1434/4/22‬ه ـ اتضــح أنــه أثنــاء إقامــة نقطــة تفتيــش مقابــل املركــز مت‬\n      ‫االشــتباه بســيارة مــن نــوع (‪ )......‬حتمــل اللوحــة رقــم (‪ )....‬بقيــادة املدعــى‬\n      ‫عليــه املذكــور أعــاه ويرافقــه املقيــم (‪ - )..‬صــدر بحــق مرافــق املدعــى‬\n      ‫عليــه املقيــم‪ .......‬أمــر حفــظ الدعــوى رقــم (‪36‬ح‪ /‬ه ـ ق‪ )34/9‬وتاريــخ‬\n      ‫‪1434/5/5‬ه ـ اســتناد ًا للمــادة (‪ )124‬مــن نظــام اإلجــراءات اجلزائيــة ‪.-‬‬\n      ‫وباســتيقافهما وطلــب إثباتيهمــا لوحــظ عليهمــا االرتبــاك وصــدور رائحة‬\n      ‫يشــتبه أنهــا رائحــة املســكر وبتفتيــش املدعــى عليــه املذكــور أعــاه‬\n      ‫عثــر داخــل جيــب قميصــه األمامــي علــى قطعــة صغيــرة تــزن (‪ )0.3‬ثالثــة‬\n      ‫مــن العشــرة مــن مــادة يشــتبه أنهــا احلشــيش املخدر‪،‬وبتفتيــش املرافــق‬\n\n‫‪185‬‬\n\f‫عثــر معــه علــى مــادة يشــتبه أنهــا محظــورة فتــم القبــض عليهمــا‪ .‬وببعــث‬\n‫عينــه مــن (دم ‪ +‬بــول) املدعــى عليــه املذكــور أعــاه للتحليــل ‪ ،‬ورد‬\n‫تقريــر مركــز الســموم والكيميــاء الشــرعية رقــم(‪712‬م أ) وتاريــخ‬\n‫‪1434/4/30‬ه ـ املتضمــن إيجابيــة عينــة البــول املأخــوذة منــه ملركبــات‬\n‫احلشــيش املخــدر احملظــور دولي ـ ًا واخلاضــع لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم(م‪ )39/‬وتاريــخ‬\n‫‪1426/7/8‬ه ـ واملــدرج يف اجلــدول رقــم(‪ )1‬فقــرة (أ) امللحــق بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وببعــث عينــة مــن القطعــة‬\n‫املضبوطــة معــه للتحليــل‪ ،‬ورد تقريــر مركــز الســموم والكيميــاء‬\n‫الشــرعية رقــم(‪2024‬ك ش) وتاريخ‪1434/4/27‬ه ـ املتضمــن إيجابيــة‬\n‫عينــة القطعــة املرســلة واملضبوطــة مــع املدعــى عليــه ملــادة احلشــيش‬\n‫املخــدر احملظــور دولي ـ ًا واملــدرج يف اجلــدول رقــم(‪ )1‬فقرة(أ)امللحــق‬\n‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــد اســتهلكت العينــة‬\n‫يف التحليــل‪ .‬وبســماع أقوالــه واســتجوابه أقــر بصحــة واقعــة القبــض‬\n‫عليــه ووجــود قطعــة احلشــيش املخــدر داخــل جيــب قميصــه‪ ،‬وأفــاد‬\n‫انــه اشــترى قميصــه الــذي ضبــط بداخلــة قطعــة احلشــيش املخــدر مــن‬\n‫شــخص ال يعرفــه وانــه قــد تكــون تلــك القطعــة املضبوطــة عائــدة لــه‪.‬‬\n‫وانتهــى التحقيــق معــه إلــى توجيــه االتهــام لــه بتعاطــي احلشــيش املخــدر‬\n‫‪ ،‬وحيازتــه لقطعــة تــزن (‪ )0،3‬ثالثــة مــن العشــرة مــن اجلــرام مــن‬\n‫احلشــيش املخــدر بقصــد االســتعمال‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬إقــراره حتقيقــا بوجــود القطعــة داخــل القميــص الــذي يرتديــه املــدون‬\n‫علــى الصفحتــن رقــم(‪ )2،1‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪)25‬‬\n‫وإقــراره أثنــاء ســماع أقوالــه املــدون علــى الصفحــة رقــم (‪ )3‬مــن ملــف‬\n\n\n                                                                                   ‫‪186‬‬\n\f      ‫إجــراءات االســتدالل املرفــق لفــة رقــم (‪ -2 .)1‬مــا تضمنــاه التقريــران‬\n      ‫الكيميائيــان الشــرعيان املرفقــان علــى اللفتــن رقمــي (‪-3.)32،29‬‬\n      ‫مــا جــاء يف محضــر التحريــز املــدون علــى الصفحــة رقــم (‪ )1‬مــن ملــف‬\n      ‫إجــراءات االســتدالل املرفــق لفــه رقــم(‪ - 4)1‬مــا تضمنــه محضــر القبض‬\n      ‫والتفتيــش املرفــق علــى اللفــة رقــم(‪ .)2‬وبالبحــث عمــا إذا كان لديــه‬\n      ‫ســوابق اتضــح عــدم وجــود ســوابق مســجلة عليــه وحيــث إن مــا أقــدم‬\n      ‫عليــه املدعــى عليــه املذكــور ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪-‬‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا اســتنادا للفقــرة الثانيــة مــن‬\n      ‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ يف عقوباتــه‬\n      ‫األصليــة والتكميليــة أطلــب بإثبــات إدانتــه مبــا نســب إليــه واحلكــم‬\n      ‫عليــه باالتــي‪ -1:‬عقوبــة الســجن الــواردة يف الفقرة(‪)1‬األولــى مــن املــادة‬\n      ‫(‪ )41‬مــن النظــام املشــار إليــه أعــاه بحقــه لقــاء مــا اســند إليــه مــن‬\n      ‫اتهــام‪ -2.‬إبعــاده عــن البــاد بعــد تنفيــذ عقوبتــه وفقـ ًا ملــا تضمنتــه الفقــرة‬\n      ‫(‪ )2‬الثانيــة مــن املــادة (‪ )56‬السادســة واخلمســن مــن النظــام املشــار إليــه‬\n      ‫هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه بواســطة‬\n      ‫املترجــم املتعــاون بنجالديشــي اجلنســية مبوجــب اإلقامــة الصــادرة مــن‬\n      ‫الدمــام برقــم ‪ .......‬قــال مــا ذكــره املدعــي العــام مــن تعاطــي احلشــيش‬\n      ‫وحيازتــي قطعــة احلشــيش يف جيــب قميصــي صحيــح ولكننــي ال أعلــم‬\n      ‫عنهــا فقــد اشــتريت القميــص يف نفــس يــوم القبــض علــي هكــذا أجــاب‬\n      ‫وقــد جــرى منــا دراســة أوراق املعاملــة واالطــاع علــى ملــف التحقيــق مــع‬\n      ‫املدعــى عليــه لفــة ‪ 25‬فوجــد يتضمــن املصادقــة علــى وجــود القطعــة يف‬\n      ‫قميصــه وإنــكار عائديتهــا لــه كمــا جــرى منــا االطــاع علــى التقريــر‬\n\n\n‫‪187‬‬\n\f‫الكيمــاوي الشــرعي رقــم ‪ 2024‬ك ش املتضمــن إيجابيــة القطــع ملــادة‬\n‫احلشــيش كمــا جــرى منــا االطــاع علــى صحيفــة ســوابق املدعــى عليــه‬\n‫فوجــدت خاليــة فبنــاء علــى مــا تقــدم وحيــث صــادق املدعــى عليــه علــى‬\n‫تعاطــي احلشــيش وأقــر بوجــود القطعــة يف قميصــه ومــا دفــع بــه ال يقبــل‬\n‫لــذا فقــد قــررت االتــي اوالً‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بحيــازة‬\n‫قطعــة احلشــيش تــزن ثالثــة مــن العشــرة مــن اجلــرام حيــازة مجــرده ثانيــا‪:‬‬\n‫اهمــال املــادة ((‪ ))41‬لعــدم ثبــوت موجبهــا واعمــال املــادة ((‪ ))39‬مــن‬\n‫نظــام املكافحــة مــع مراعــاة ((‪ ))60‬مــن النظــام لكــون املدعــى عليــه‬\n‫وافــد مصيــره االبعــاد وذلــك بســجنه ســتة أشــهر مــن تاريــخ إيقافــه علــى‬\n‫ذمــة هــذه القضيــة وجلــده مائــة وخمســن جلــده مفرقــة بــن كل دفعــة‬\n‫وأخــرى عشــرة أيــام وإلزامــه بدفــع غرامــة ثالثــة آالف ريــال لبيــت املــال‬\n‫وجلــده حــد املســكر ثمانــون جلــدة علنــا دفعــة واحــدة يفــرق بينهــا وبــن‬\n‫التعزيــز بعشــرة أيــام وإبعــاده عــن البــاد بعــد انتهــاء محكوميتــه اعمــا ًال‬\n‫للمــادة ((‪ ))56‬مــن نظــام املكافحــة وبذلــك حكمــت للحــق العــام‬\n‫وبعــرض احلكــم علــى الطرفــن قــررا االعتــراض وبــاهلل التوفيــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر ‪1434/5/28‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/8/16‬ه ـ افتتحــت‬\n‫اجللســة الرابعــة يف متــام الســاعة التاســعة والنصــف صباحــا حيــث وردتنــا‬\n‫املعاملــة املتعلقــة بدعــوى املدعــي العــام ضــد مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية بخطــاب رقــم ‪ 341676917‬وتاريــخ ‪1434/8/8‬ه ـ‬\n‫وبرفقهــا القــرار رقــم ‪ 34282924‬وتاريــخ ‪1434/7/30‬ه ـ واملتضمــن‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم وقــد أغلقــت اجللســة يف متــام الســاعة احلاديــة عشــر‬\n                          ‫وخمســة وأربعــون دقيقــة حــرر يف ‪1434/8/16‬هــ‪.‬‬\n                                                                                       ‫‪188‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":184,"source_page_end":188,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ef7c05a3586c0e8cf19ab785b68c40a229d5f473be67578c8e27bcc62669990d","normalized_text_hash":"bc7c851699d819d46c2044853796f49e521ec902b3af89dea5ab17176cf8a2fb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p184-34227223"},{"id":"1a569809-961f-5226-91f7-5bfed047e912","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -إقرار -إدانة- نزول عن احلد األدنى للعقوبة -ال اجتهاد مع وجود نص نظامي -قيادة سيارة حتت تأثير املخدر -حد املسكر -تعزير بالسجن واإلبعاد -إثبات.","document_number":"3424254","case_number":"34244859","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف أن وقف تنفيذ عقوبة اإلبعاد اجتهاد مع وجود نص نظامي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/05/27","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -إقرار -إدانة- نزول عن احلد األدنى للعقوبة -ال اجتهاد مع وجود نص نظامي -قيادة سيارة حتت تأثير املخدر -حد املسكر -تعزير بالسجن واإلبعاد -إثبات.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3424254 :‬تاريخه‪1433/05/27 :‬هـ‬\n                         ‫رقم الدعوى‪34244859:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34246254‬تاريخه‪1434/06/19 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬إقــرار‪ -‬إدانــة‪-‬‬\n      ‫نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬ال اجتهــاد مــع وجــود نــص نظامــي‬\n      ‫‪ -‬قيــادة ســيارة حتــت تأثيــر املخــدر ‪ -‬حــد املســكر ‪ -‬تعزيــر بالســجن‬\n                                                              ‫واإلبعــاد ‪ -‬إثبــات‪.‬‬\n\n\n\n\n      ‫املــواد (‪ )41‬و(‪ )56‬و (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                ‫العقليــة‪.‬‬\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n      ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لــه‪ ،‬واحلكــم عليــه‬\n      ‫بعقوبــة الســجن واإلبعــاد عــن البــاد طبقــا لنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة‪ ،‬مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا‬\n      ‫علــى ســيجارة يشــتبه أن تكــون مخلوطــة باحلشــيش‪ ،‬أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر‪ ،‬أقــر‬\n      ‫أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬قضــت احملكمــة بإدانــة‬\n      ‫املدعــى عليــه بحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لــه‬\n      ‫وقــررت جلــده ثمانــن جلــدة دفعــة واحــدة حــد املســكر وســجنه ملــدة‬\n\n‫‪189‬‬\n\f‫أربعــة أشــهر وإبعــاده عــن البــاد بعــد تنفيــذ العقوبــة بحقــه مــع وقــف‬\n‫تنفيــذ هــذه العقوبــة بحقــه‪ ،‬الحظــت محكمــة االســتئناف أن وقــف‬\n‫تنفيــذ عقوبــة اإلبعــاد اجتهــاد مــع وجــود نــص نظامــي‪ ،‬قــررت احملكمــة‬\n‫االبتدائيــة الرجــوع عمــا حكمــت بــه مــن وقــف التنفيــذ‪ ،‬عــارض املدعى‬\n‫عليــه علــى احلكــم ولــم يعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة‬\n               ‫االســتئناف املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪ 34244859‬وتاريــخ‬\n‫‪1434/05/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341292609‬وتاريــخ‬\n‫‪1434/05/27‬ه ـ ففــي يــوم االثنــن املوافق‪1434/06/12‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 :15‬وفيهــا حضــر املدعــي العــام املكلــف من مرجعة‬\n‫برقــم ه ـ ع ‪ 51/3/‬يف ‪1431/5/24‬ه ـ وحضــر حلضــوره املدعــى عليــه‬\n‫‪ .......‬مينــي اجلنســية مبوجــب رخصــة إقامــة رقــم ‪ .......‬وادعــى املدعــى‬\n‫العــام بدعــواه احملــررة لدينــا أنــه عنــد الســاعة الثانيــة عشــر مســاء‬\n‫اخلميــس املوافــق ‪1434/5/2‬ه ـ وأثنــاء قيــام فرقــة املخــدرات بعملهــا‬\n‫يف حــي ‪ .....‬بخميــس مشــيط مت االشــتباه يف ســيارة ‪ .....‬وباســتيقافها‬\n‫وطلــب إثبــات قائدهــا املتهــم وبتفتيشــه لــم يعثــر معــه علــى أي شــيء مــن‬\n‫املمنوعــات وبتفتيــش الســيارة عثــر بداخلهــا علــى ســيجارة يشــتبه أن‬\n‫تكــون مخلوطــة مبــادة احلشــيش املخــدر بلــغ وزنهــا (‪ )0.7‬ســبعة مــن‬\n‫العشــرة مــن اجلــرام فقبــض عليــه وســلم إلــى إدارة مكافحــة املخــدرات‬\n\n                                                                                    ‫‪190‬‬\n\f      ‫بخميــس مشــيط وســلمت لــه ســيارته وأغراضــه الشــخصية وبســماع‬\n      ‫أقــوال املتهــم أقــر بأنــه عثــر يف ســيارته علــى ســيجارة مخلوطــة مبــادة‬\n      ‫احلشــيش املخــدر وهدفــه مــن حيازتهــا االســتعمال وانــه اســتخدم مــن‬\n      ‫املضبــوط كمــا أقــر بأنــه يتعاطــى احلشــيش املخــدر من الســابق وبتحليل‬\n      ‫عينــة ممــا مت ضبطــه ثبــت أنهــا مخلوطــة مبــادة احلشــيش املخــدر مبوجــب‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم (‪/938‬م) لعــام ‪1434‬ه ـ الصــادر من‬\n      ‫مركــز مراقبــة الســموم الطبيــة الشــرعية مبنطقــة عســير وقــد انتهــى‬\n      ‫التحقيــق مــع املذكــور إلــى توجيــه االتهــام لــه بحيــازة أعقاب ســجائر بلغ‬\n      ‫وزنهــا (‪ )0.7‬ســبعة مــن العشــرة مــن اجلــرام بقصــد التعاطــي والتعاطــي‬\n      ‫مــن نــوع املضبــوط ومــن الســابق كمــا أقــرر توجيــه االتهــام لــه بقيــادة‬\n      ‫الســيارة حتــت تأثيــر احلشــيش املخــدر وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪1‬ـ مــا تضمنــه إقــراره علــى صفحــة (‪ )9-12‬مــن ملــف ضبــط إجــراءات‬\n      ‫قضيــة مخــدرات مرفــق لفــة رقــم (‪2 )1‬ـ مــا تضمنــه محضــر القبــض‬\n      ‫والتفتيــش لفــه رقــم (‪3 )9‬ـ مــا تضمنــه التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪/938‬م) لعــام ‪1432‬ه ـ لفــه رقــم (‪ )16‬وبالبحــث عــن ســوابقه‬\n      ‫اتضــح عــدم وجــود ســوابق مســجلة عليــه لــذا أطلــب إثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه مبــا يلــي ‪1‬ـ عقوبــة تعزيريــة وفقــا ملــا ورد يف املــادة (‪)1/41‬‬\n      ‫احلاديــة واألربعــن الفقــرة األولــى مــن النظــام املشــار إليــه لقــاء حيازتــه‬\n      ‫ســيجاره مخلوطــة مبــادة احلشــيش املخــدر بلــغ وزنهــا (‪ )0.7‬ســبعة مــن‬\n      ‫العشــرة مــن اجلــرام بقصــد االســتعمال واســتعمال مــن املضبــوط يف‬\n      ‫الســابق ‪2‬ـ إبعــاده مــن اململكــة العربيــة الســعودية بعــد تنفيــذ العقوبــة‬\n      ‫وفقــا ملــا ورد يف املــادة (‪ )56‬السادســة واخلمســن الفقــرة (‪ )2‬الثانيــة مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ -3‬إثبــات إدانتــه بقيــادة‬\n\n\n‫‪191‬‬\n\f‫الســيارة حتــت تأثيــر احلشــيش املخــدر وإفهامــه بــأن عقوبتــه الــواردة‬\n‫بالفقــرة رقــم (‪ )1‬مــن املــادة (‪ )68‬الثامنــة والســتون مــن نظــام املــرور‬\n‫علــى ذلــك عائــد للجهــات املختصــة هكــذا ادعــى وبســؤال املدعــى عليــه‬\n‫أجــاب قائــا مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح وصحيــح‬\n‫أننــي أتعاطــي احلشــيش املخــدر ومــا حصــل خطــأ منــي وأنــا تائــب إلــى‬\n‫اهلل ممــا فعلــت لكنــي معتــرض علــى إبعــادي عــن البــاد فأنــا مســتثمر‬\n‫يف هــذه البــاد ولــدي مــا يزيــد عــن أربعــن عامــا وعــدة مصانــع للرخــام‬\n‫علي وعلى‬ ‫املزخــرف والطــاوالت الرخاميــة ويف إبعــادي عــن البالد ضــرر ّ‬\n‫مــن يعمــل عنــدي وفيــه خســارة ماليــة كبيــرة جــدا هكــذا أفــاد ثــم ابــرز‬\n‫لنــا مــا يفيــد ذلــك مــن ســجالت جتاريــة بعــدد أربــع مصانــع يف ‪ ....‬و‪......‬‬\n‫و‪ ..........‬و‪ .....‬ومرخــص لــه مــن قبــل الهيئــة العامــة لالســتثمار وبرنــت‬\n‫صــادر مــن اجلــوازات مبــن يعمــل لديــه مرفقــه صورهــا باملعاملــة وبعــد‬\n‫ذلــك رأيــت رفــع اجللســة للتأمــل وحــدد لهــم موعــد يــوم االثنــن املوافــق‬\n‫‪1434/6/19‬ه ـ الســاعة التاســعة اختتمــت اجللســة الســاعة ‪ 8.55‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                           ‫يف ‪1434/06/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االثنــن املوافــق ‪1434/06/19‬‬\n‫ويف متــام الســاعة التاســعة افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‬\n‫وحضــر حلضــوره املدعــى عليــه وبعــد تأمــل الدعــوى واإلجابــة واالطــاع‬\n‫علــى املعاملــة اخلاصــة بهمــا وبنــاء علــى مــا تقــدم وبنــاء علــى التقريــر‬\n‫الكيميائــي الشــرعي املتضمــن إيجابيــة العينــة املضبوطــة مــع املدعــى‬\n‫عليــه وبنــاء علــى مصادقــة املدعــى عليــه علــى دعــوى املدعــي العــام‬\n‫وأعلــن توبتــه وندمــه وذكــر انــه مســتثمر يف البــاد وان يف احلكــم يف‬\n\n\n                                                                                      ‫‪192‬‬\n\f      ‫إبعــاده عــن البــاد مفســده وبنــاء علــى القاعــدة الشــرعية التــي تقــول درء‬\n      ‫املفاســد أولــى مــن جلــب املصالــح ‪ ،‬وهــي قاعــدة جليلــة القــدر عظيمــة‬\n      ‫النفــع‪ ،‬وحاصلهــا أن دالئــل الشــريعة املطهــرة دلــت علــى أنــه حكــم اهلل‬\n      ‫تعالــى يــدور مــع مــا يترجــح عنــد تعــارض املصالــح واملفاســد‪ ،‬واملضــار‬\n      ‫واملنافــع‪ ،‬فيكــون الشــيء مطلوبــا شــرعا إن ترجحــت مصاحلــه علــى‬\n      ‫مفاســده‪ ،‬ويكــون ممنوعــا إن كان العكــس ‪ ،‬ومبــا أن يف إبعــاد‬\n      ‫املدعــى عليــه عــن البــاد مفســدة أعظــم مــن املصلحــة يف عقوبتــه بإبعــاده‬\n      ‫إذ الضــرر متعــدٍ عليــه وعلــى غيــره ولقولــه الرســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم ( ال ضرر وال ضرار )‪ ،‬حديث حســن رواه ابن ماجة والدارقطني‬\n      ‫وحيــث ال يوجــد ســوابق مســجلة علــى املدعــى عليــه لذلــك كلــه ثبــت‬\n      ‫لــدي شــرعا إدانــة املدعــى عليــه مبــا نســب إليــه يف الدعــوى وحكمــت‬\n      ‫عليــه باالتــي أو ًال ‪ /‬حكمــت علــى املدعــى عليــه مبوجــب املــادة احلاديــة‬\n      ‫واألربعــن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واســتنادا‬\n      ‫إلــى املــادة الســتني مــن ذات النظــام وحيــث اظهــر املدعــى عليــه توبتــه‬\n      ‫وندمــه ولعــدم وجــود ســوابق مســجلة عليــه لــذا حكمــت عليــه بالســجن‬\n      ‫أربعــة أشــهر‪ .‬ثانيـاً‪ /‬حكمــت عليــه مبوجــب املــادة السادســة واخلمســن‬\n      ‫الفقــرة الثانيــة مــن ذات النظــام بإبعــاده عــن البــاد بعــد تنفيــذ العقوبــة‬\n      ‫بحقــه وال يســمح لــه بالعــودة إليهــا‪ ،‬إال فيمــا عــدا مــا تســمح بــه تعليمــات‬\n      ‫احلــج والعمــرة مــع وقــف تنفيــذ العقوبــة بحقــه للمصلحــة الراجحــة يف‬\n      ‫ذلــك ويف حــال عودتــه ألي فعــل معاقــب عليــه شــرعا تنفــذ العقوبــة بحقــه‬\n      ‫بإبعــاده عــن البــاد‪ .‬ثالث ـاً‪ /‬حكمــت عليــه بجلــده ثمانــن جلــده دفعــة‬\n      ‫واحــده حــد املســكر لقــاء اعترافــه بتعاطــي احلشــيش املخــدر‪ .‬رابع ـاً‪/‬‬\n      ‫ثبــت لــدي إدانتــه بقيــادة الســيارة حتــت تأثيــر احلشــيش املخــدر وافهمتــه‬\n\n\n‫‪193‬‬\n\f‫إن عقوبتــه علــى ذلــك عائــدة للجهــة املختصــة هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم‬\n‫كمــا قــرر املدعــي العــام املعارضــة علــى احلكــم وطلــب رفــع احلكــم‬\n‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة واالكتفــاء بالئحــة‬\n‫الدعــوى العامــة وأمــرت بتنظيــم القــرار الــازم لذلــك ورفعــه مــع كامــل‬\n‫أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم اختتمــت اجللســة‬\n‫الســاعة ‪ ...9.45‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/08/09‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليــه وقــد عــادت أوراق املعاملــة بخطــاب رئيــس محكمــة االســتئناف‬\n‫برقــم ‪ 341657838‬يف ‪1434/07/29‬ه ـ مشــفوعا بهــا قــرار املالحظــة‬\n‫مــن أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة اجلزائيــة الثالثــة برقــم‬\n‫‪34272315‬يف ‪1434/07/18‬ه ـ املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫وباالطــاع علــى مــا جــاء يف القــرار وصــورة ضبطــه وأوراق املعاملــة تقــرر‬\n‫إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن مــا قــرره فضيلتــه مــن وقــف‬\n‫تنفيــذ العقوبــة املقــررة بحــق املدعــى عليــه يف الفقــرة ثانيــا ملــا قــرره مــن‬\n‫تعليــل يف غيــر محلــه فــا اجتهــاد مــع وجــود نــص نظامــي فعلــى فضيلتــه‬\n‫مالحظــة مــا ذكــر وإكمــال الــازم واهلل املوفــق وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى الــه وصحبــه ســلم أه ـ ولوجاهــة مــا ذكــره أصحــاب‬\n‫الفضيلــة قضــاة االســتئناف فقــد رجعــت عــن حكمــي يف وقــف تنفيــذ‬\n‫العقوبــة بحــق املدعــى عليــه يف إبعــاده عــن البــاد وأفهمــت املدعــى عليــه‬\n\n\n                                                                                          ‫‪194‬‬\n\f      ‫إن احلكــم نافــذا حســب األنظمــة والتعليمــات يف ذلــك هــذا مــا ظهــر لــي‬\n      ‫وبــه حكمــت وبعرضــه علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب‬\n      ‫رفــع احلكــم لالســتئناف بــدون الئحــة واالكتفــاء بــاألوراق الســابقة‬\n      ‫املرفقــة باملعاملــة وأمــا املدعــي العــام فقــرر عــدم املعارضــة علــى احلكــم‬\n      ‫وأمــرت باحلــاق ذلــك يف القــرار وإعــادة كامــل أوراق املعاملــة حملكمــة‬\n      ‫االســتئناف لتدقيــق احلكــم اختتمــت اجللســة الســاعة الثامنــة والربــع‬\n      ‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم‪ .‬حــرر يف ‪1434/08/09‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف خميــس مشــيط برقــم‬\n      ‫‪ 341876675‬وتاريــخ ‪1434/8/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .................‬برقــم ‪34246254‬‬\n      ‫وتاريــخ ‪1434/6/19‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪............‬‬\n      ‫مينــي اجلنســية ‪ -‬يف قضيــة (مخــدرات) علــى الصفــة املوضحــة يف القــرار‬\n      ‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث ســبق‬\n      ‫دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب‬\n      ‫بــه فضيلتــه واحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قــرار الدائــرة رقــم‬\n      ‫‪ 34272315‬وتاريــخ ‪1434/7/18‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء األخيــر‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                      ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪195‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":189,"source_page_end":195,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"945c5bbccaa75f2947df26644f59da368422a4f45d9bd3ab32adc7f36a2a3669","normalized_text_hash":"78f4c07eb053d77581c2f00631788611b894d90667514e26712d6e3c993b53c5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p189-3424254"},{"id":"21972ea3-c061-5778-8d22-6620cc4e50f3","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي والترويج -إقرار -دفع غير مقبول ملوجب -إدانة باحليازة املجردة عن القصد -عقوبة بحدها األعلى -سوابق.","document_number":"34241672","case_number":"34255436","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/14","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي والترويج -إقرار -دفع غير مقبول ملوجب -إدانة باحليازة املجردة عن القصد -عقوبة بحدها األعلى -سوابق.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34241672:‬تاريخه‪1434/06/14:‬هـ‬\n                   ‫رقم الدعوى‪34255436:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34269274‬تاريخه‪1434/07/16:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي‬\n‫والترويــج‪ -‬إقــرار‪ -‬دفــع غيــر مقبــول ملوجــب‪ -‬إدانــة باحليــازة املجــردة‬\n                     ‫عــن القصــد ‪ -‬عقوبــة بحدهــا األعلــى ‪ -‬ســوابق‪.‬‬\n\n\n\n\n‫املــواد (‪ )38‬و(‪ )39‬و(‪ )56‬و(‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                               ‫العقليــة‪.‬‬\n\n\n\n\n‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة بقصــد الترويــج وحيــازة‬\n‫ســيجارة حشــيش بقصــد االســتعمال ‪ ،‬واحلكــم عليــه بعقوبــة الســجن‬\n‫واجللــد والغرامــة واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة حيــث قبــض عليــه بعــد ورود معلومــات عــن ترويجــه‬\n‫املخــدرات وبتفتيشــه شــخصيا عثــر بحوزتــه علــى حبــوب محظــورة‬\n‫و ســيجارة حشــيش وبتفتيــش منزلــه عثــر علــى كميــة كبيــرة مــن‬\n‫احلشــيش واحلبــوب احملظــورة‪ -‬أثبــت التقريــر الكيميائــي الشــرعي‬\n‫إيجابيــة العينــة املرســلة للحشــيش املخــدر واإلمفيتامــن‪ ،‬أقــر أمــام‬\n‫احملكمــة بحيــازة املخــدرات إال أنــه دفــع بكــون قصــده مــن حيازتهــا‬\n\n                                                                                 ‫‪196‬‬\n\f      ‫تســليمها للجهــة املختصــة‪ ،‬املدعــى عليــه مــن أربــاب الســوابق ومــا دفــع‬\n      ‫بــه غيــر مقبــول فقــد قضــت احملكمــة بإدانــة املدعــى عليــه بحيــازة‬\n      ‫احلشــيش املخــدر واحلبــوب احملظــورة حيــازة مجــردة مــع التهمــة القويــة‬\n      ‫بــأن يكــون قصــده الترويــج وقــررت ســجنه ملــدة خمــس ســنوات وجلــده‬\n      ‫خمســمائة جلــدة مفرقــة وتغرميــه مبلــغ خمســة آالف ريــال ومنعــه مــن‬\n      ‫الســفر خــارج اململكــة ملــدة خمــس ســنوات وقــد عــارض املدعــى عليــه‬\n      ‫واملدعــي العــام علــى احلكــم‪ ،‬قــررت محكمــة االســتئناف املوافقــة‬\n                                                                       ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/6/14‬ه ـ لــدي أنــا‬\n      ‫القاضــي باحملكمــة اجلزائيــة بالطائــف وبنــاء علــى املعاملــة املقيــدة برقم‬\n      ‫‪ 341345013‬يف ‪1434/6/4‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيس برقم‬\n      ‫‪ 34255436‬يف ‪1434/6/4‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــى‬\n      ‫العــام بالتعميــد رقــم ‪ 2367‬يف ‪1433/3/12‬هـ ـ وادعــى علــى احلاضــر‬\n      ‫باملجلــس الشــرعي‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫ـاء علــى توفــر املعلومــات إلدارة مكافحــة املخــدرات‬      ‫‪ .......‬قائــا انــه بنـ ً‬\n      ‫عــن قيــام شــخص بترويــج احلبــوب احملظــورة واحلشــيش املخــدر بحــي‬\n      ‫العقيــق وميتلــك ســيارة رقــم اللوحــة (‪ ).....‬ومبتابعتــه والبحــث والتحــري‬\n      ‫عنــه لوحــظ املدعــى عليــه بقيــادة الســيارة املذكــورة مبحطــة جبــال‬\n      ‫الهــدا وبالقبــض عليــه وتفتيشــه ضبــط يف برجلــه اليمنــى كيــس نايلــون‬\n      ‫بداخلــه (‪ )399‬حبــة كانــت (بالشــراب) وضبــط برجلــه اليمنــى علــى‬\n      ‫بكــت دخــان بداخلــه ســيجارة ملفوفــة تــزن (‪ )2.3‬جرامــن وثالثــة‬\n\n‫‪197‬‬\n\f‫مــن العشــرة مــن اجلــرام كانــت بالشــراب وباالنتقــال ملنــزل املدعــى‬\n‫عليــه وتفتيــش الغرفــة اخلاصــة باملدعــى عليــه عثــر علــى حقيبتــن‬\n‫ذكــر املدعــى عليــه بأنهــا لــه وبتفتيــش احلقيبــة األولــى ضبــط بداخلهــا‬\n‫(‪ )6896‬حبــه وبتفتيــش احلقيبــة الثانيــة ضبــط بداخلهــا أكيــاس تــزن‬\n‫(‪ )2869.5‬ألفــان وثمامنائــة وتســعة وســتون جــرام ونصــف كمــا عثــر‬\n‫داخــل الشــنطة علــى ثالثــة مسدســات (مت فــرز أوراق مســتقلة لقضيــة‬\n‫الســاح ) وقــد أثبتــت التقريــر الكيميائــي الشــرعي رقــم ( ‪)5805‬‬\n‫وتاريــخ ‪1434/4/2‬ه ـ احتــواء مــا مت ضبطــه علــى مادتــي احلشــيش‬\n‫املخــدر واإلمفيتامــن احملظورتــن وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫للمدعــى عليــه بحيــازة (‪ )7295‬ســبعة اآلف ومائتــن وخمســة وتســعني‬\n‫حبــة مــن حبــوب اإلمفيتامــن احملظــورة وأكيــاس بهــا حشــيش مخــدر‬\n‫تــزن (‪ )2869.5‬ألفــان وثمامنائــة وتســعة وســتون جــرام وخمســة مــن‬\n‫العشــرة مــن اجلــرام بقصــد الترويــج لكبــر الكميــة وحيــازة ســيجارة‬\n‫ممزوجــة باحلشــيش املخــدر تــزن (‪ )2.3‬جرامــن وثالثــة مــن العشــرة‬\n‫مــن اجلــرام بقصــد االســتعمال وهــو فعــل محــرم ومعاقــب عليــه نظام ـ ًا‬\n‫وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات الصــادر‬\n‫باملرســوم امللكــي رقــم (‪ )39‬وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة‬\n‫والقرائــن التاليــة ‪ -1‬محضــر القبــض والتفتيــش املنــوه عنــه ‪ -2‬التقريــر‬\n‫الكيميائــي الشــرعي املنــوه عنــه املرفــق وبالبحــث عــن ســوابقه عثــر لــه‬\n‫علــى أربعــة عشــر ســابقة ســت ســوابق ســرقة نصــب واحتيــال وســابقة‬\n‫مضاربــة وســابقة محاولــة لــواط وســابقة فعــل فاحشــة لــواط ونهــب‬\n‫وســابقتي حيــازة واســتعمال مخــدرات وســابقة اشــتباه ترويــج مخــدرات‬\n‫وســابقة تســتر وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n\n\n                                                                                  ‫‪198‬‬\n\f      ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ومجــرم نظامـ ًا أطلــب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه‪ -1 -:‬ســجنه وجلــده وتغرميــه وفقـ ًا‬\n      ‫للفقــرة األولــى مــن املــادة الثامنــة والثالثــن مــن النظــام املشــار إليــه‪-2 .‬‬\n      ‫منعــه مــن الســفر خلــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتــه وفقـ ًا للفقــرة‬\n      ‫األولــى مــن املــادة السادســة واخلمســن‪ .‬هــذه دعــواي‪ .‬وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره املدعــي العــام يف دعــواه مــن‬\n      ‫اتهامــي بحيــازة الكميــة املضبوطــة مــن احلبــوب احملظــورة واحلشــيش‬\n      ‫املخــدر بقصــد الترويــج وحيازتــي لســيجارة ممزوجــة باحلشــيش املخــدر‬\n      ‫بقصــد االســتعمال فكلــه غيــر صحيــح إطالق ـ ًا ‪ ،‬والصحيــح أننــي‬\n      ‫اســتأجرت ســيارة وركــب معــي شــخص أثيوبــي وعنــد مشــاهدته‬\n      ‫رجــال األمــن هــرب فذهبــت إلــى البيــت ووجــدت يف شــنطة الســيارة‬\n      ‫الشــنطتني املضبوطتــن وأظنهــا لذلــك الشــخص فقمــت بإنزالهــا يف‬\n      ‫منزلــي بقصــد تســليمها للقســم الحق ـ ًا وأنــا ال أعلــم مــا بداخلهــا ويف‬\n      ‫اليــوم التالــي وجــدت يف الســيارة كيــس نايلــون يحتــوي علــى (‪)399‬‬\n      ‫ثالثمائــة وتســع وتســعني حبــة مــن احلبــوب احملظــورة وســيجارة حشــيش‬\n      ‫فخشــيت أن يتــم القبــض علــي وهــي بحوزتــي فقمــت بوضــع الكيــس‬\n      ‫الــذي يحتــوي علــى احلبــوب بداخــل شــرابي وســيجارة احلشــيش بداخلهــا‬\n      ‫البكــت املربــوط برجلــي حتــى أرجــع إلــى البيــت وأســلمها جميع ـ ًا‬\n      ‫للحكومــة مــع الشــنطتني التــي يف املنــزل فتــم القبــض علــي واتهامــي‬\n      ‫بذلــك ‪ ،‬وأمــا الســوابق التــي علــى فصحيحــة هكــذا أجــاب فســألت‬\n      ‫املدعــي العــام عــن البينــة علــى دعــواه فيمــا نفــاه املدعــى عليــه فأجــاب‬\n      ‫بقولــه‪ :‬بينتــي علــى ذلــك إقــراره املرصــود باملعاملــة لفــة (‪ )1‬ص (‪)14‬‬\n      ‫املتضمــن (إقــراره بــأن جميــع مــا ضبــط بحوزتــه يعــود لــه شــخصياً) ‪،‬‬\n\n\n‫‪199‬‬\n\f‫وكــون الكميــة املضبوطــة كبيــرة ‪ ،‬وليــس لــدي ســوى ذلــك هكــذا‬\n‫أجــاب وبعــرض هــذا اإلقــرار علــى املدعــى عليــه أجــاب بقولــه‪ :‬إننــي لــم‬\n‫أعتــرف بذلــك إطالقـ ًا هكــذا أجــاب وبتصفــح أوراق املعاملــة لفــه (‪)1‬‬\n‫ص (‪ )23‬تبــن وجــود إقــرار للمدعــى عليــه يتضمــن (اعترافــه بأنــه أقــر‬\n‫بإقــراره الســابق خوف ـ ًا علــى والدتــه) وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أجــاب بقولــه‪ :‬هــذا صحيــح فقــد اعترفــت بذلــك خوف ـ ًا علــى والدتــي‬\n‫ألنهــا كانــت معــي وأريــد الذهــاب بهــا إلــى املنــزل هكــذا أجــاب فبعــد‬\n‫ســماعي للدعــوى وإجابــة املدعــى عليــه بنفــي مــا جــاء فيهــا مــع إقــراره‬\n‫بحيــازة الكميــة الــواردة يف الدعــوى وإخفــاءه لكميــة مــن احلبــوب‬\n‫ا ذلــك‬ ‫وســيجارة حشــيش يف رجلــه ويف الشــراب التــي كانــت عليــه معلـ ً‬\n‫مبــا جــاء يف جوابــه ‪ ،‬وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا أقــوال‬\n‫املدعــى عليــه املشــار إلــى مضمونهــا ســابق ًا ‪ ،‬والتقريــر الكيميائــي‬\n‫الشــرعي املتضمــن إيجابيــة العينــات املضبوطــة ملادتــي احلشــيش املخــدر‬\n‫واإلمفيتامــن احملظورتــن ‪ ،‬وألن مــا ذكــره املدعــى عليــه مــن تعليــل ال‬\n‫ميكــن قبولــه ؛ ألن املفتــرض يف مثــل هــذه احلالــة تســليم هــذه احلقائــب‬\n‫إلــى اجلهــة املختصــة مباشــرة ‪ ،‬كمــا أن مــا ذكــره مــن إخفــاءه لكميــة‬\n‫مــن احلبــوب احملظــورة وســيجارة حشــيش يــدل علــى أنهــا تعــود لــه ‪،‬‬\n‫كمــا أن تضــارب أقوالــه يف املعاملــة وأثنــاء احملاكمــة يقــوي التهمــة‬\n‫ضــده بصحــة مــا نســب إليــه إضافــة إلــى وجــود ســوابق لــه يف حيــازة‬\n‫وترويــج املخــدرات ‪ ،‬ولكــون الكميــة املضبوطــة كبيــرة واألصــل يف‬\n‫ـاء علــى املــواد الثامنــة والثالثني والتاســعة‬\n                                               ‫مثلهــا أن يكــون للترويــج ‪ ،‬وبنـ ً‬\n‫والثالثــن والسادســة واخلمســن والثانيــة والســتني مــن نظــام مكافحــة‬\n‫املخــدرات ‪ ،‬وألن بينــة املدعــي العــام يف كــون الكميــة املضبوطــة مــع‬\n\n\n                                                                                       ‫‪200‬‬\n\f      ‫املدعــى عليــه تعــود لــه بقصــد الترويــج غيــر موصلــة وألن األصــل أن مــن‬\n      ‫وجــد معــه شــيء فهــو لــه حتــى يثبــت خــاف ذلــك ‪ ،‬ولكثــرة ســوابق‬\n      ‫املدعــى عليــه لهــذا كلــه فقــد صــدر منــي مــا يلــي‪ :‬أوالً‪ :‬ثبــت لــدي‬\n      ‫إدانــة املدعــى عليــه بحيــازة الكميــة املضبوطــة والــواردة يف الدعــوى‬\n      ‫مــن احلشــيش املخــدر وحبــوب االمفتيامــن احملظــورة حيــازة مجــردة‬\n      ‫وحكمــت عليــه لقــاء ذلــك بســجنه خمــس ســنوات مــن تاريــخ إيقافــه ‪،‬‬\n      ‫وجلــده خمســمائة جلــده مفرقــة علــى عشــر دفعــات متســاوية يف العــدد‬\n      ‫بــن كل دفعــة وأخــرى مــدة ال تقــل عــن أســبوع ‪ ،‬وتغرميــه خمســة آالف‬\n      ‫ريــال ‪ ،‬ومنعــه مــن الســفر خــارج اململكــة ملــدة خمس ســنوات بعــد انتهاء‬\n      ‫محكوميتــه‪ .‬ثاني ـاً‪ :‬لــم تثبــت لــدي إدانتــه بحيــازة الكميــة املضبوطــة‬\n      ‫بقصــد الترويــج وإمنــا تتوجــه التهمــة القويــة ضــده بذلــك واكتفيــت‬\n      ‫بعقوبتــه علــى ذلــك مبــا ورد يف (أوال) ‪ ،‬وبعــرض احلكــم علــى املدعــى‬\n      ‫عليــه قــرر االعتــراض بــدون الئحــة وأمــا املدعــي العــام فقــرر االعتــراض‬\n      ‫بالئحــة فجــرى إفهامــه بتعليمــات االســتئناف وصلــى اهلل وســلم علــى‬\n      ‫ســيدنا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1434/6/14‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافــق ‪1434/7/29‬ه ـ‬\n      ‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n      ‫قــرار الدائــرة اجلزائيــة اخلامســة رقــم (‪ )34269274‬يف ‪1434/7/16‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬وللمعلوميــة جــرى حتريــر ذلــك ‪،‬‬\n              ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/7/29‬هــ‪.‬‬\n\n\n\n\n‫‪201‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":196,"source_page_end":201,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ede58b3296b7aa0b02b5afb2de2a8882bcd23c42e3167866327f7669e66618d4","normalized_text_hash":"5c25449eed0c1007307d9d030e418306c1a4d91c4d0ebdd9536c7f96bc9c5012","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p196-34241672"},{"id":"946f735f-b6ad-5637-841b-f3aa78492a59","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد الترويج وتعاطيه والشروع يف بيعه- إقرار -عدم احلاجة لسماع شهادة الشهود -بينة غير موصلة -إدانة باحليازة بقصد التعاطي -نزول عن احلد األدنى للعقوبة.","document_number":"34252509","case_number":"34283189","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/26","year":"1434","subject":"مخدرات -حيازة حشيش بقصد الترويج وتعاطيه والشروع يف بيعه- إقرار -عدم احلاجة لسماع شهادة الشهود -بينة غير موصلة -إدانة باحليازة بقصد التعاطي -نزول عن احلد األدنى للعقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34252509 :‬تاريخه‪1434/06/26 :‬هـ‬\n                    ‫رقم الدعوى‪34283189 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34277618‬تاريخه‪1434/7/24:‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد الترويــج وتعاطيــه والشــروع يف بيعه‪-‬‬\n ‫إقــرار‪ -‬عــدم احلاجــة لســماع شــهادة الشــهود ‪ -‬بينــة غيــر موصلــة‪ -‬إدانــة‬\n              ‫باحليــازة بقصــد التعاطــي‪ -‬نــزول عــن احلــد األدنــى للعقوبة‪.‬‬\n\n\n\n\n ‫املــواد (‪ )41‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                          ‫العقليــة‪.‬‬\n\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n ‫بحيــازة احلشــيش املخــدر بقصــد الترويــج وشــروعه يف ترويجــه وتعاطيــه‬\n ‫لــه‪ ،‬واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة واملصــادرة واإلبعــاد‬\n ‫عــن البــاد طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬مت‬\n ‫االتفــاق معــه علــى شــراء حشــيش مخــدر فوافــق علــى ذلــك ويف الوقــت‬\n ‫واملــكان احملدديــن حضــر وعنــد شــروعه يف اإلســتالم والتســليم شــاهد‬\n ‫رجــال األمــن فحــاول ابتــاع قطعــة احلشــيش املتفق على شــراءها فقبض‬\n ‫عليــه‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n ‫للحشــيش املخــدر‪ ،‬أقــر أمــام احملكمــة بحيــازة احلشــيش املخــدر‬\n ‫بقصــد التعاطــي وتعاطيــه لــه وأنكــر أن يكــون قصــده الترويــج‪،‬‬\n\n                                                                                     ‫‪202‬‬\n\f      ‫اطلعــت احملكمــة علــى بينــات املدعــي العــام وقــررت عدم احلاجة لســماع‬\n      ‫شــهادة شــهود محضــر القبــض لكونــه لــم يتضمــن اإلشــارة إلــى عمليــة‬\n      ‫االســتالم والتســليم‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه بحيــازة‬\n      ‫احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لــه وقــررت جلــده ثمانــن‬\n      ‫جلــدة دفعــة واحــدة حــد املســكر وســجنه ملــدة شــهرين وإبعــاده إلــى‬\n      ‫بــاده‪ ،‬كمــا قضــت بــرد طلــب املدعــي العــام تطبيــق املــواد (‪)53-38‬‬\n      ‫بحقــه لعــدم ثبــوت موجبــه‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‬\n           ‫العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنا القاضــي يف احملكمة اجلزائية مبحافظة‬\n      ‫القطيــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة مبحافظــة القطيف برقــم ‪ 34283189‬وتاريخ ‪1434/06/19‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 341487741‬وتاريــخ ‪1434/06/19‬ه ـ ففــي‬\n      ‫يــوم االثنــن ‪ 1434/06/26‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪10 :30‬‬\n      ‫وفيهــا حضــر املدعــي العــام بصفتــي مدعي ـ ًا عامــا يف دائــرة التحقيــق‬\n      ‫واالدعــاء العــام مبحافظــة القطيــف أدعــي علــى البالــغ مــن العمــر (‪)25‬‬\n      ‫بحرينــي اجلنســية الجــئ برقــم (‪ )....‬محصــن موظــف أهلــي املقبــوض‬\n      ‫عليــه بتاريــخ ‪1434/4/21‬ه ـ وأحيــل لســجن محافظــة القطيــف اســتنادا‬\n      ‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ باالطــاع علــى‬\n      ‫محضــر البــاغ والقبــض والتفتيــش املعــد مــن قبل رجال الضبــط اجلنائي‬\n      ‫مبكافحــة املخــدرات بالدمــام تبــن أنــه بتاريــخ ‪ 1434/4/21‬ه ـ وبنــاء‬\n      ‫علــى املعلومــات املتوفــرة مــن أحــد مصادرهــم الســرية والتــي تفيــد عــن‬\n\n‫‪203‬‬\n\f‫شــخص يدعــى (‪ )....‬مــن ســكان القطيــف داريــن لــه نشــاط يف ترويــج‬\n‫احلشــيش املخــدر واحلبــوب احملظــورة ويســتخدم اجلــوال رقــم () واســتعد‬\n‫املصــدر لإلطاحــة باملذكــور باجلــرم املشــهود عليــه فقــد مت متكــن‬\n‫املصــدر مــن االتصــال هاتفيــا علــى املــروج وطلــب منــه شــراء حشــيش‬\n‫مخــدر مببلــغ مئتــي ريــال وحبــوب محظــورة مببلــغ مئتــي ريــال فوافــق‬\n‫املــروج علــى ذلــك وطلــب مــن املصــدر احلضــور لــه عنــد منزلــه وأنــه جاهــز‬\n‫لتســليمها وجــرى تفتيــش املصــدر وســيارته وترقيــم مبلــغ وقــدره (‪)400‬‬\n‫أربعمائــة ريــال وزود املصــدر باملبلــغ احلكومــي وحتــرك حتــت أنظــار‬\n‫الفرقــة حتــى تقابــل مــع املروج ثم ركب املروج مع املصدر وعند شــروعه‬\n‫يف عمليــة االســتالم والتســليم شــاهد الفرقــة فحــاول ابتــاع القطعة التي‬\n‫مت االتفــاق علــى بيعهــا ومتــت الســيطرة عليــه وبتفتيشــه شــخصي ًا لــم يعثــر‬\n‫بحوزتــه علــى أي شــيء مــن احملظــورات وعثــر معــه علــى الهاتــف اجلــوال‬\n‫الــذي قــام باســتخدامه للتنســيق يف عمليــة الترويــج ومبلــغ وقــدره (‪)886‬‬\n‫ثمامنائــة وســتة وثمانــون ريــاال وبطاقــة صــراف (‪ ).....‬وفيــزا كارت (‪).....‬‬\n‫ومفتــاح ســيارة وأقــر املــروج أمــام الفرقــة بــأن هــذه هــي القطعــة التــي‬\n‫أحضرهــا للترويــج والتــي حــاول ابتالعهــا‪ ،‬وهــي قطعــة تــزن خمســة‬\n‫جرامــات وثمانيــة مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر أثبــت‬\n‫التقريــر الكيميائــي الشــرعي رقــم (‪ )2035‬وتاريــخ ‪ 1434/4/29‬ه ـ‬\n‫إيجابيــة عينــة مــا مت ضبطــه ملــادة احلشــيش املخــدر واملــدرج علــى اجلــدول‬\n‫األول فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات وباســتجوابه أقــر‬\n‫بأنــه يتعاطــى احلشــيش املخــدر ومبواجهتــه مبــا ورد مبحضــر القبــض‬\n‫مــن أنــه مت االتصــال بــه علــى جوالــه رقــم () ذكــر أن بينــه وبــن صلــة‬\n‫قرابــة وأنــه اتصــل بــه أكثــر مــن مــرة يطلــب منــه املخــدرات وذكــر‬\n\n                                                                                      ‫‪204‬‬\n\f      ‫لــه بأنــه ال يســتطيع إحضــار املخــدرات لــه وانــه ال يقــوم بالترويــج وقــد‬\n      ‫أســفر التحقيــق عــن اتهامــه بحيــازة قطعــة تــزن خمســة جرامــات وثمانيــة‬\n      ‫مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر بقصــد الترويــج والشــروع‬\n      ‫وفقــا للفقــرة رقــم (‪ )2‬مــن‬\n                                   ‫يف بيعهــا وتعاطيــه احلشــيش املخــدر املجــرم ً‬\n      ‫املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة ‪-1‬محضــر البــاغ والقبــض والتفتيــش املنــوه‬\n      ‫عنــه املــدون علــى الصفحــات رقــم (‪ )11-2‬مــن ملــف ضبــط إجــراءات‬\n      ‫االســتدالل املرفــق علــى اللفــة رقــم (‪-2 )1‬إقــراره بــان مــا مت ضبطــه يعــود‬\n      ‫لــه شــخصيا بقصــد االســتخدام وباســتخدامه للحشــيش املخــدر املــدون‬\n      ‫علــى الصفحــة رقــم (‪ )1‬مــن محضــر االســتجواب املرفــق علــى اللفــة‬\n      ‫رقــم (‪-3 )13‬التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق علــى‬\n      ‫اللفــة رقــم (‪ )19‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى‬\n      ‫ســوابق مســجله علــى املســتوى العــام وحيــث إن مــا أقــدم عليــه املذكــور‬\n      ‫وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ونظام ـ ًا لــذا أطلــب احلكــم عليــه مبــا يلــي أوال‪ :‬إثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه مبــا يلــي ‪ -1‬بعقوبــة الســجن واجللــد والغرامــة الــواردة‬\n      ‫بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام مــع مراعــاة مــا ورد‬\n      ‫باملــادة رقــم (‪ )62/1‬مــن النظــام ‪-2‬إبعــاده عــن اململكــة إعمــاال ملقتضــى‬\n      ‫الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن النظــام ثانيـاً‪ :‬مصــادرة الهاتــف‬\n      ‫اجلــوال العائــد للمدعــى عليــه مــن نــوع (‪ ).....‬برقــم االتصــال (‪ ).....‬ويحمــل‬\n      ‫الرقــم املصنعــي (‪ ).....‬الرتباطــه بالقضيــة وفقــا للفقــرة رقــم (‪ )1‬مــن‬\n      ‫املــادة رقــم (‪ )53‬مــن النظــام مــع املطالبــة بإســقاط شــريحة الهاتــف‬\n      ‫النقــال وعــدم صرفهــا لنفــس املدعــى عليــه وفقــا لتعميــم ســمو وزيــر‬\n\n\n‫‪205‬‬\n\f‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1429/2/10-9‬ه ـ هــذه دعواي والســام‬\n‫وبعرضهــا علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام مــن القبــض‬\n‫علــي يف تاريــخ ‪ 1434/4/21‬ه ـ عندمــا اتصــل بــي صديــق لــي وطلــب‬\n‫مقابلتــي عنــد البــاب وخرجــت وركبــت معــه الســيارة وأثنــاء ذلــك حضــر‬\n‫فرقــة مــن مكافحــة املخــدرات وعندمــا شــاهدتهم كان معــي قطعــة‬\n‫حشــيش مخــدر صغيــرة حاولــت ابتالعهــا والعثــور بحوزتــي علــى الهاتــف‬\n‫اجلــوال رقــم (‪ ).....‬ومبلــغ قــدره ثمامنائــة وســتة وثمانــون ريــا ًال وبطاقــة‬\n‫صــراف ومفتــاح ســيارة وجهــاز جــوال مــن نــوع (‪ ).....‬كل ذلــك صحيــح‬\n‫ا وقصــدي مــن حيــازة هــذه القطعــة التعاطــي الشــخصي‬          ‫جملـ ًة وتفصيـ ً‬\n‫وأنــا أتعاطــى احلشــيش املخــدر منــذ فتــرة وأمــا مــا ذكــره املدعــي العــام‬\n‫مــن ترويجــي احلشــيش املخــدر واحلبــوب احملظــورة وشــروعي يف عمليــة‬\n‫ا والصحيــح‬    ‫بيــع هــذه القطعــة كل ذلــك غيــر صحيــح جمل ـ ًة وتفصي ـ ً‬\n‫مــا ذكرتــه لكــم وبطلــب البينــة مــن املدعــي العــام علــى نيــة الترويــج‬\n‫وشــروعه يف بيعهــا قــال بينتــي إقــراره حتقيق ـ ًا املــدون علــى لفــة رقــم‬\n‫(‪ )13-12-11‬ومحضــر البــاغ والقبــض والتفتيــش املــدون علــى صفحــة‬\n‫(‪ )11-2‬مــن ملــف التحقيــق املرفــق لفــة رقــم (‪ )1‬ومبطالعــة اقــراره‬\n‫حتقيق ـ ًا وجدتــه موافق ـ ًا إلجابتــه لدينــا يف املجلــس الشــرعي ومبطالعــة‬\n‫محضــر القبــض املــدون علــى صفحــة (‪ )11‬مــن ملف التحقيــق املرفق لفة‬\n‫رقــم (‪ )1‬وجدتــه موافق ـ ًا لدعــوى املدعــي العــام وبعــرض احملضــر علــى‬\n‫املدعــى عليــه قــال احملضــر غيــر صحيــح بخصــوص شــروعي يف عمليــة‬\n‫ترويــج هــذه القطعــة مــن احلشــيش املخــدر والصحيــح مــا ذكرتــه لكــم‬\n‫هــذا وقــد جــرى االطــاع علــى التقريــر الكيمــاوي الشــرعي املشــار‬\n‫إليــه أعــاه فوجدتــه كمــا ذكــر وإلــى أن محضــر القبــض والتفتيــش‬\n\n\n                                                                                       ‫‪206‬‬\n\f      ‫والضبــط املشــار إليــه أعــاه ليــس فيــه مــا يشــير إلــى عمليــة االســتالم‬\n      ‫والتســليم وهــي الركــن األســاس واملؤثــر يف إثبــات الترويــج مــن عدمــه‬\n      ‫ـاء علــى مــا تقــدم مــن‬\n                              ‫لــذا لــم أجــد مــا يبــرر إحضــار الفرقــة القابضــة فبنـ ً‬\n      ‫الدعــوى واإلجابــة وإلــى مصادقــة املدعــى عليــه علــى دعــوى املدعي العام‬\n      ‫بخصــوص حيازتــه قطعــة احلشــيش املخــدر املذكــورة أعــاه لقصــد‬\n      ‫التعاطــي وتعاطيــه احلشــيش املخــدر وإنــكاره ترويــج احلشــيش املخــدر‬\n      ‫ولــم يثبــت املدعــي العــام ذلــك وإلــى أن محضــر القبــض خــال مــن الركن‬\n      ‫األســاس إلثبــات عمليــة الترويــج وهــي االســتالم والتســليم وإلــى مــا تــدل‬\n      ‫عليــه املــادة التاســعة واخلمســون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫التــي تتضمــن أن احملكمــة ال تتقيــد بالوصــف الــوارد يف الئحــة الدعــوى‬\n      ‫وعليهــا أن تعطــي الفعــل الوصــف الــذي يســتحقه وإلــى مــا تــدل عليــه‬\n      ‫املادتــان الواحــدة واألربعــون والسادســة واخلمســون مــن نظــام مكافحــة‬\n      ‫املخــدرات وإلــى عــدم الســوابق وقلــة الكميــة ومــا تــدل عليــه املــادة‬\n      ‫الســتون مــن نظــام مكافحــة املخــدرات لــكل مــا ســبق فقــد ثبــت لــدي‬\n      ‫إدانــة املدعــى عليــه بحيــازة قطعــة حشــيش مخــدر وزنها خمســة جرامات‬\n      ‫وثمانيــة بالعشــرة مــن اجلــرام لقصــد التعاطــي وتعاطيــه احلشــيش املخــدر‬\n      ‫وبعــده حكمــت مبــا يلــي أو ًال بســجن املدعــى عليــه ملــدة شــهرين اعتبــار ًا‬\n      ‫مــن تاريــخ إيداعــه الســجن تطبيقـ ًا للمــادة الواحــدة واألربعــن مــن نظــام‬\n      ‫مكافحــة املخــدرات ومت النــزول عــن احلــد األدنــى مــن العقوبــة إعمــا ًال‬\n      ‫للمــادة الســتني مــن ذات النظــام ثاني ـ ًا إبعــاده إلــى بــاده بعــد إنهــاء مــا‬\n      ‫لــه ومــا عليــه تطبيقـ ًا للمــادة السادســة واخلمســن مــن ذات النظــام ثالثـ ًا‬\n      ‫بجلــده ثمانــن جلــدة دفعــة واحــدة حــد املســكر يف مــكان عــام رابع ـ ًا‬\n      ‫رددت دعــوى املدعــي العــام بخصــوص تطبيــق املادتــن الثامنــة والثالثــن‬\n\n\n‫‪207‬‬\n\f‫والثالثــة واخلمســن مــن نظــام مكافحــة املخــدرات لعــدم ثبــوت قيــام‬\n‫املوجــب الشــرعي وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫القناعــة واملدعــي العــام عدمهــا وطلــب االســتئناف وأجيــب لطلبــه كمــا‬\n‫قــرر أن الئحتــه االعتراضيــة مــا يف أوراق املعاملــة وأمــرت برفــع كامــل‬\n‫أوراق املعاملــة إلــى محكمــة االســتئناف باملنطقــة الشــرقية وأغلقــت‬\n‫اجللســة يف متــام الســاعة ‪ 10 :55‬وصــل اهلل علــى نبينــا محمــد وعلــى الــه‬\n‫وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة‬\n‫اجلزائيــة مبحافظــة القطيــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم ‪ 34283189‬وتاريخ‬\n‫‪ 1434/06/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341487741‬وتاريــخ‬\n‫‪ 1434/06/19‬ه ـ ففــي يــوم األربعــاء ‪ 1434/08/03‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 08 :30‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية مبوجــب خطابهــم رقــم ‪ 341658512‬وتاريــخ ‪1434/07/30‬ه ـ‬\n‫واملقيــدة لدينــا برقــم ‪ 341658512‬وتاريــخ ‪1434/08/02‬ه ـ وبرفقهــا‬\n‫القــرار الصــادر مــن قضــاة محكمــة االســتئناف الدائــرة اجلزائيــة‬\n‫الثالثيــة األولــى ‪ -‬ج‪ 1/‬رقــم ‪ 34277618‬يف ‪1434/07/24‬ه ـ واملتضمن‬\n‫املصادقــة علــى احلكــم وبــه تعتبــر القضيــة منتهيــة وأغلقــت اجللســة يف‬\n‫متــام الســاعة ‪ 08 :45‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                           ‫وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":202,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"99018e4e721455ec99aff1adb12508a148b77e369fed91abfe86002b4780ccfd","normalized_text_hash":"9eafc6dcc3a1c130c2853ca8888392b2f444b5b7757304dfd37d1b2c8217999d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p202-34252509"},{"id":"c93af952-71aa-5d84-8bfb-bc2f830132a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -شراء وحيازة احلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -التستر على مصدر املضبوطات -إقرار املدعى عليه بشراء وحيازة احلشيش املخدر -إنكار املدعى عليه التستر على مصدر املضبوطات -إقامة حد املسكر -تعزير املدعى عليه بالسجن واإلبعاد عن الباد.","document_number":"34267356","case_number":"34311511","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/12","year":"1434","subject":"مخدرات -شراء وحيازة احلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -التستر على مصدر املضبوطات -إقرار املدعى عليه بشراء وحيازة احلشيش املخدر -إنكار املدعى عليه التستر على مصدر املضبوطات -إقامة حد املسكر -تعزير املدعى عليه بالسجن واإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34267356 :‬تاريخه ‪1434/7/12:‬هـ‬\n                         ‫رقم القضية‪34311511 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34290705‬تاريخه‪1434/08/08 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬شــراء وحيــازة احلشــيش املخــدر بقصــد التعاطــي ‪ -‬تعاطــي‬\n      ‫احلشــيش املخــدر ‪ -‬التســتر علــى مصــدر املضبوطــات ‪ -‬إقــرار املدعــى‬\n      ‫عليــه بشــراء وحيــازة احلشــيش املخــدر ‪ -‬إنــكار املدعــى عليــه التســتر‬\n      ‫علــى مصــدر املضبوطــات ‪ -‬إقامــة حــد املســكر ‪ -‬تعزيــر املدعــى عليــه‬\n                                                  ‫بالســجن واإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                 ‫‪ -1‬قوله تعالى( وال تقتلوا النفس التي حرم اهلل إال باحلق)‪.‬‬\n                       ‫‪ -2‬قوله تعالى (وال تفسدوا يف األرض بعد صالحها )‪.‬‬\n                   ‫‪ -3‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n      ‫‪ -4‬املــادة ‪ 56‬الفقــرة الثانيــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                       ‫العقليــة‪.‬‬\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليــه مقيــم بشــراء وحيــازة احلشــيش املخدر‬\n      ‫بقصــد التعاطــي‪ ،‬تعاطيــه احلشــيش املخــدر‪ ،‬التســتر علــى مصــدر‬\n      ‫املضبوطــات‪ ،‬وطلــب املدعــي العــام إثبــات مــا اســند إليــه واحلكــم عليــه‬\n      ‫بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬و إبعــاده عن اململكة‬\n      ‫بعــد تنفيــذ احملكوميــة و بعقوبــة تعزيريــة لقــاء تســتره علــى مصــدر‬\n\n‫‪209‬‬\n\f‫املخــدرات‪ ،‬مت القبــض علــى املدعــى عليــه بعــد اســتيقافه و تفتيشــه‬\n‫بعــد االشــتباه بــه مــن قبــل ســلطات األمــن و بتفتيشــه ضبــط كميــة مــن‬\n‫احلشــيش املخــدر‪ ،‬إقــرار املدعــى عليــه بشــراء وحيــازة احلشــيش املخــدر‬\n‫بقصــد التعاطــي‪ ،‬إقــرار املدعــى عليــه بتعاطــي احلشــيش املخــدر‪،‬‬\n‫إنــكار املدعــى عليــه التســتر علــى مصــدر املضبوطــات‪ ،‬عــدم وجــود‬\n‫بينــة للمدعــي العــام علــى مــا أنكــره املدعــى عليــه ســوى مــا جــاء يف‬\n‫أوراق املعاملــة‪ ،‬إقامــة حــد املســكر علــى املدعــى عليــه‪ ،‬تعزيــر املدعــى‬\n‫عليــه بالســجن واإلبعــاد فيمــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة‪،‬‬\n‫عــدم ثبــوت إدانــة املدعــى عليــه بالتســتر علــى مصــدر املضبوطــات‪،‬‬\n                               ‫تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة‬\n                  ‫أنــا ‪ ............‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫الــواردة إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ‪ 10097‬وتاريــخ ‪1434/7/4‬ه ـ واملقيــدة بهــذه احملكمــة برقــم‬\n‫‪ 341630165‬وتاريــخ ‪1434/7/5‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيــس‬\n‫برقــم ‪ 34311511‬وتاريــخ ‪1434/7/5‬ه ـ فتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام ‪ ............‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب‬\n‫خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n‫األحســاء ذي الرقــم ‪ ............‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه‬\n‫ا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لدائــرة التحقيــق‬      ‫قائ ـ ً‬\n‫واالدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪ ............‬مصــري‬\n\n                                                                                          ‫‪210‬‬\n\f      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ............‬العمــر ‪ 33‬عام ـ ًا احلالــة‬\n      ‫االجتماعيــة متــزوج باالطــاع علــى محضــر القبــض رقــم (‪ )............‬املعــد‬\n      ‫مــن قبــل أمــن الطــرق التابــع ملركــز الدهنــاء تبــن أنــه مت اســتيقاف‬\n      ‫املدعــى عليــه حيــث كان يقــود ســيارة مــن نــوع بيجــو (‪2007‬م) حتمــل‬\n      ‫اللوحــة (‪ )............‬اللــون (أســود) وبتفتيشــه وتفتيــش املركبــة ضبــط‬\n      ‫علــى عــدد (‪ )6‬ســتة قطــع ســوداء اللــون تــزن جميعهــا (‪ )32.5‬اثنــن‬\n      ‫وثالثــن جــرام وخمســة مــن العشــرة مــن اجلــرام كانــت موجــودة بداخــل‬\n      ‫جــوارب كانــت موضوعــه بداخلــه حــذاء موضــع علــى املقعــدة اخللفيــة‬\n      ‫بالســيارة ‪ .‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪)............‬‬\n      ‫إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر واملــدرج يف اجلــدول رقــم‬\n      ‫(‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه أقــر بشــراء وحيــازة احلشــيش املخــدر بقصــد‬\n      ‫التعاطــي وتعاطيــه لنوعــه وأنــه اشــتراها مــن شــخص يف الريــاض بقيمــة‬\n      ‫‪ 500‬ريــال ‪ .‬وانتهــى التحقيــق معــه علــى توجيــه االتهــام لــه بشــراء‬\n      ‫وحيــازة عــدد (‪ )6‬ســتة قطــع مــن احلشــيش املخــدر تــزن جميعهــا (‪)32.5‬‬\n      ‫اثنــن وثالثــن جــرام وخمســة مــن العشــرة مــن اجلــرام بقصــد التعاطــي‬\n      ‫وتعاطيــه لنوعــه ‪ ،‬واملجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (‪ )39‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وتســتره علــى مصــدر‬\n      ‫املضبوطــات التــي معــه وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف‬\n      ‫إقــرار املدعــى عليــه املــدون علــى محضــر االســتجواب املرفــق علــى اللفــة‬\n      ‫رقــم (‪ -2)11/12‬محضــر القبــض والتفتيــش املرفــق علــى اللفــة رقــم‬\n      ‫(‪ -3)4‬محضــر الــوزن والتحريــز املــدون علــى الصفحــة رقــم (‪ )4‬مــن‬\n\n‫‪211‬‬\n\f                  ‫ملــف االســتدالالت األوليــة املرفــق علــى اللفــة رقــم (‪. )8‬‬\n‫‪ -4‬التقريــر الكيمــاوي الشــرعي املرفــق علــى اللفــة رقــم (‪ )16‬وحيــث‬\n‫إن مــا أقــدم عليــه املدعــى عليــه املذكــور ‪ -‬وهــو بكامل أهليتــه املعتبرة‬\n‫نظامــا ؛ لــذا أطلــب إثبــات مــا أســند‬\n                                      ‫ً‬     ‫شــرع ًا ‪ -‬فعــل مجــرم ومعاقــب عليــه‬\n                                                  ‫إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫العقوبــات الــواردة يف نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n            ‫‪ /1-:‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪. )41‬‬\n‫‪ /2‬احلكــم بإبعــاده عــن اململكــة بعــد تنفيــذ محكوميتــه اســتناد ًا‬\n                             ‫للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن ذات النظــام‪.‬‬\n‫العقوبــات التعزيزيــة ‪ /1-:‬احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة‬\n                                          ‫لقــاء تســتره علــى املصــدر املخــدرات‪.‬‬\n‫هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن‬\n‫هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائـاً‪ :‬صحيــح‬\n‫مــا نســبه لــي املدعــي العــام مــن واقعــة القبــض ومــن شــرائي وحيــازة‬\n‫عــدد ســت قطــع مــن احلشــيش املخــدر تــزن جميعهــا(‪ )32.5‬اثنــن‬\n‫وثالثــن جــرام وخمســة مــن العشــرة مــن اجلــرام بقصــد االســتعمال ومــن‬\n‫اســتعمالي للحشــيش املخــدر وصحيــح اعتــرايف ونســبة (الســوابق ) لــي‬\n‫وقــد أخــذت محكوميتهــا وغيــر صحيــح تســتري على مصــدر املخدرات‬\n‫فقــد أخبــرت جهــة التحقيــق أننــي اشــتريتها عــن طريــق صديــق لــي‬\n‫اســمه ‪ ............‬مصــري اجلنســية وهــو الــذي يحضرهــا لــي عــن طريــق‬\n‫أنــاس يعرفهــم هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام هــل لديــه‬\n‫ـدي ســوى مــا يف أوراق‬ ‫بينــة علــى مــا نفــاه املدعــى عليــه فقــال ‪ :‬ليــس لـ َّ‬\n‫املعاملــة وأطلــب الرجــوع إليهــا هكــذا أجــاب فجــرى االطــاع علــى‬\n\n\n                                                                                         ‫‪212‬‬\n\f      ‫جميــع أوراق املعاملــة ومنهــا ‪ :‬التقريــر الكيمــاوي الشــرعي الصــادر مــن‬\n      ‫قســم الكيميــاء الشــرعية باملركــز اإلقليمــي ملراقبــة الســموم التابــع‬\n      ‫للمديريــة العامــة للشــؤون الصحيــة باملنطقــة الشــرقية برقــم ( ‪ 2081‬ك‬\n      ‫ش ) لعــام ‪1434‬ه ـ املتضمــن إيجابيــة عي ــنة مــا ضبــط للحشــيش املخــدر‬\n      ‫كمــا جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه املتضمــن خلــوه‬\n      ‫مــن الســوابق كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه‬\n      ‫املتضمنــة أنــه أوقــف بتاريخ‪1434/04/23‬ه ـ فبنــاء علــى مــا ورد مــن‬\n      ‫الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن‬\n      ‫أهليتــه وملــا ورد يف محضــر القبــض واعتــراف املدعــي عليــه ومبــا أنــه‬\n      ‫صــادق علــى صحــة مــا نســب إليــه مــن حيــازة احلشــيش املخــدر علــى‬\n      ‫صفــة مــا ورد يف الدعــوى ومبــا أن مــا صــدر منــه حــرام يف الشــريعة ملــا‬\n      ‫يف احلشــيش املخــدر مــن اخلطــر و الضــرر علــى البــاد والعبــاد وعلــى‬\n      ‫مــن صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي حــرم اهلل إال‬\n      ‫باحلــق) وقــال (وال تفســدوا يف األرض بعــد إصالحهــا ) ممــا يســتوجب‬\n      ‫معاقبــة املدعــى عليــه و تعزيــزه بالعقوبــة الــواردة يف املــادة الواحــدة‬\n      ‫واألربعــن مــن نظــام مكافحــة املخــدرات كمــا يتوجــه اســتحقاقه‬\n      ‫للعقوبــة الــواردة يف املــادة السادســة واخلمســن الفقــرة الثانيــة منهــا ومبــا‬\n      ‫أن املدعــى عليــه أقـ َّـر باســتعمال احلشــيش املخــدر واســتعماله يأخــذ‬       ‫َّ‬\n      ‫حكــم املســكر للتوافــق بينهمــا يف منــاط احلكــم وحــد املســكر أن‬\n      ‫يجلــد صاحبــه ثمانــن جلــدة علنــا كمــا اســتقر عليــه عمــل األمــة ممــا‬\n      ‫يتوجــب حــد املدعــى عليــه حــد املســكر الســتعماله للحشــيش املخــدر‬\n      ‫أن املدعــى عليــه أنكــر دعــوى املدعــي العــام باتهامــه بالتســتر علــى‬‫ومبــا َّ‬\n      ‫مصــدر املخــدرات وال بينــة للمدعــي العــام علــى ذلــك ممــا يســتوجب ر َّد‬\n\n\n‫‪213‬‬\n\f‫دعــوى املدعــي العــام بإثبــات إدانــة املدعــى عليــه بذلــك لــذا كلــه وألجــل‬\n‫ـدي إدانــة‬‫احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي ‪ :‬أو ًال ‪ /‬ثبــت لـ َّ‬\n‫املدعــى عليــه باســتعمال احلشــيش املخــدر ويجلــد حــد املســكر ثمانــن‬\n‫جلــدة دفعــة واحــدة علنـ ًا ‪ .‬ثانيـ ًا ‪ /‬ثبــت لــدي إدانــة املدعــى عليــه بشــراء‬\n‫وحيــازة عــدد ســت قطــع مــن احلشــيش املخــدر تــزن جميعهــا(‪ )32.5‬اثنني‬\n‫وثالثــن جــرام وخمســة مــن العشــرة مــن اجلــرام بقصــد االســتعمال وأن‬\n‫يعــزر بســجنه ملــدة ســنة مــن تاريــخ توقيفــه علــى ذمــة القضيــة وذلــك‬\n‫مبوجــب املــادة الواحــدة و األربعــن مــن نظــام مكافحــة املخــدرات‪.‬‬\n‫ثالثــا ‪ /‬وأن يبعــد عــن اململكــة بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه‬\n‫واســتيفاء مــا لــه ومــا عليــه مــن حقــوق وال يســمح لــه بالعــودة إليهــا فيمــا‬\n‫عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة حســب مقتضــى مــا ورد يف‬\n‫املــادة السادســة واخلمســن مــن النظــام نفســه الفقــرة الثانيــة‪ .‬رابعـ ًا ‪ /‬لــم‬\n‫ـدي إدانــة املدعــى عليــه بالتســتر علــى مصــدر املخــدرات وقــررت‬       ‫يثبــت لـ َّ‬\n‫ر َّد دعــوى املدعــي العــام بإثبــات إدانتــه بذلــك وبتــاوة احلكــم علــى‬\n‫الطرفــن وإفهــام املدعــى عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم‬\n‫وطلــب املدعــي العــام رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة‬\n‫هــي الئحــة الدعــوى هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن‬\n‫ذلــك حرمــة اســتعمال احلشــيش املخــدر وأثــره الســيئ علــى العقــل واملــال‬\n‫وأقفلــت اجللســة العاشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد‬\n       ‫وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف ‪1434/07/12‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n\n\n                                                                                           ‫‪214‬‬\n\f      ‫برقــم ‪ 341630165‬وتاريــخ ‪1434/7/19‬ه ـ املقيــدة لــدى احملكمــة‬\n      ‫برقــم ‪ 34/1787376‬وتاريــخ ‪1434/7/24‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ............‬املســجل برقــم‬\n      ‫‪ 34267356‬وتاريــخ ‪1434/7/12‬ه ـ اخلــاص بدعــوى‪ /‬املدعــي العــام‬\n      ‫ضــد‪ ............/‬الســيد ‪ ....‬مصــري اجلنســية يف قضيــة مخــدرات وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                    ‫‪1434/8/7‬ه ـ ‪.‬‬\n\n\n\n\n‫‪215‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":209,"source_page_end":215,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d20f0fb040286783c21eef5df65d6433a026eb2e8e0d5e22e5de97bb1cf18bd","normalized_text_hash":"25676b725770d4763aa064915483ff5b1225d2fc98aa4ee23f56140fb778e2e2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p209-34267356"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
